-- ═══════════════════════════════════════════════════════════════════════════
-- Vers des Tages: automatische Dauer-Planung
--
-- GENERATED by tool/verse_schedule/build_migration.py – edit the template
-- (tool/verse_schedule/migration_template.sql), not this file.
--
-- What this does
--   1. verse_pool: every distinct verse that was "Vers des Tages" BEFORE 2026
--      (de-duplicated by reference AND text, Schlachter 2000 wording,
--      no translation name anywhere).
--   2. verse_of_the_day gets pool_id / auto_scheduled / image_source_hash and
--      a UNIQUE date (exactly one verse per day).
--   3. schedule_verses_of_the_day(until): fills every free day with a pool
--      verse such that a verse
--        • appears at most ONCE per calendar year and
--        • is at least 365 days away from any other appearance
--      (checked against ALL rows, also manually created/edited ones).
--   4. A daily pg_cron job keeps the plan 10 years ahead forever and prepares
--      translations for the next 21 days.
--   5. get_verse_schedule_overview() / check_verse_conflicts() for the admin.
--
-- Existing verses are never changed. Bulk inserts run with user triggers
-- disabled, so no push notification / translation storm is triggered.
-- ═══════════════════════════════════════════════════════════════════════════

SET statement_timeout = 0;

BEGIN;

-- ───────────────────────────────────────────────────────────────────────────
-- 1) Normalisation helpers (used for duplicate detection)
-- ───────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.verse_text_key(p_text text)
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
  SELECT regexp_replace(
           normalize(
             replace(
               lower(
                 regexp_replace(
                   regexp_replace(coalesce(p_text, ''), '<[^>]*>', ' ', 'g'),
                   '&[a-zA-Z#0-9]+;', ' ', 'g'
                 )
               ),
               'ß', 'ss'
             ),
             NFKD
           ),
           '[^a-z0-9]', '', 'g'
         );
$$;

CREATE OR REPLACE FUNCTION public.verse_ref_key(p_ref text)
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
  SELECT regexp_replace(
           replace(
             regexp_replace(
               regexp_replace(
                 lower(regexp_replace(coalesce(p_ref, ''), '<[^>]*>|&[a-zA-Z#0-9]+;|[​-‏‪-‮⁠﻿]', '', 'g')),
                 'brief', '', 'g'
               ),
               '[\s.]', '', 'g'
             ),
             ':', ','
           ),
           '(\d)[a-c]($|[^a-z])', '\1\2', 'g'
         );
$$;

-- ───────────────────────────────────────────────────────────────────────────
-- 2) Verse pool
-- ───────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.verse_pool (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  verse text NOT NULL,
  reference text NOT NULL,
  ref_key text GENERATED ALWAYS AS (public.verse_ref_key(reference)) STORED,
  text_key text GENERATED ALWAYS AS (public.verse_text_key(verse)) STORED,
  -- keys of every spelling/variant of this passage that was ever used
  alt_ref_keys text[] NOT NULL DEFAULT '{}',
  is_active boolean NOT NULL DEFAULT true,
  source text NOT NULL DEFAULT 'manual' CHECK (source IN ('history', 'manual')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS verse_pool_text_key_uidx ON public.verse_pool (text_key);
CREATE INDEX IF NOT EXISTS verse_pool_ref_key_idx ON public.verse_pool (ref_key);
CREATE INDEX IF NOT EXISTS verse_pool_alt_ref_keys_idx ON public.verse_pool USING gin (alt_ref_keys);

ALTER TABLE public.verse_pool ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS verse_pool_admin_all ON public.verse_pool;
CREATE POLICY verse_pool_admin_all ON public.verse_pool
  FOR ALL TO authenticated
  USING (public.is_admin()) WITH CHECK (public.is_admin());

COMMENT ON TABLE public.verse_pool IS
  'Verses the automatic Vers-des-Tages planner may use (one row per passage). Seeded with every verse used before 2026. is_active=false excludes a verse from future planning.';

-- ───────────────────────────────────────────────────────────────────────────
-- 3) verse_of_the_day: new columns
-- ───────────────────────────────────────────────────────────────────────────
ALTER TABLE public.verse_of_the_day
  ADD COLUMN IF NOT EXISTS pool_id bigint REFERENCES public.verse_pool (id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS auto_scheduled boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS image_source_hash text,
  ADD COLUMN IF NOT EXISTS text_key text GENERATED ALWAYS AS (public.verse_text_key(verse)) STORED,
  ADD COLUMN IF NOT EXISTS ref_key text GENERATED ALWAYS AS (public.verse_ref_key(reference)) STORED;

COMMENT ON COLUMN public.verse_of_the_day.pool_id IS 'Which verse_pool passage this day shows (used for the no-repeat rule).';
COMMENT ON COLUMN public.verse_of_the_day.auto_scheduled IS 'true = created by schedule_verses_of_the_day().';
COMMENT ON COLUMN public.verse_of_the_day.image_source_hash IS 'Set when image_url was generated automatically (sha1 of verse+reference). NULL = manual image, never overwritten.';

CREATE INDEX IF NOT EXISTS verse_of_the_day_pool_date_idx ON public.verse_of_the_day (pool_id, date);
CREATE INDEX IF NOT EXISTS verse_of_the_day_text_key_idx ON public.verse_of_the_day (text_key, date);
CREATE INDEX IF NOT EXISTS verse_of_the_day_ref_key_idx ON public.verse_of_the_day (ref_key, date);

-- exactly one verse per day (the app loads "today" with maybeSingle())
CREATE UNIQUE INDEX IF NOT EXISTS verse_of_the_day_date_uidx ON public.verse_of_the_day (date);

-- ───────────────────────────────────────────────────────────────────────────
-- 4) Keep pool_id in sync when verses are created/edited manually
-- ───────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.verse_pool_match(p_verse text, p_reference text)
RETURNS bigint
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT p.id
  FROM public.verse_pool p
  WHERE p.text_key = public.verse_text_key(p_verse)
     OR p.ref_key = public.verse_ref_key(p_reference)
     OR public.verse_ref_key(p_reference) = ANY (p.alt_ref_keys)
  ORDER BY (p.text_key = public.verse_text_key(p_verse)) DESC, p.id
  LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.trg_verse_of_the_day_pool()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.pool_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.verse IS NOT DISTINCT FROM OLD.verse
     AND NEW.reference IS NOT DISTINCT FROM OLD.reference THEN
    RETURN NEW;
  END IF;
  NEW.pool_id := public.verse_pool_match(NEW.verse, NEW.reference);
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_verse_of_the_day_pool ON public.verse_of_the_day;
CREATE TRIGGER trg_verse_of_the_day_pool
BEFORE INSERT OR UPDATE OF verse, reference ON public.verse_of_the_day
FOR EACH ROW EXECUTE FUNCTION public.trg_verse_of_the_day_pool();

-- ───────────────────────────────────────────────────────────────────────────
-- 5) The rule: same passage not in the same calendar year and not within
--    364 days. The forbidden window around day d is one contiguous range:
--    [least(d-364, 1 Jan), greatest(d+364, 31 Dec)].
-- ───────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.verse_conflict_window_start(d date)
RETURNS date LANGUAGE sql IMMUTABLE AS
$$ SELECT least(d - 364, date_trunc('year', d)::date) $$;

CREATE OR REPLACE FUNCTION public.verse_conflict_window_end(d date)
RETURNS date LANGUAGE sql IMMUTABLE AS
$$ SELECT greatest(d + 364, (date_trunc('year', d) + interval '1 year - 1 day')::date) $$;

-- Rows that would clash with putting (verse, reference) on p_date.
CREATE OR REPLACE FUNCTION public.check_verse_conflicts(
  p_verse text,
  p_reference text,
  p_date date,
  p_exclude_id uuid DEFAULT NULL
)
RETURNS TABLE (id uuid, date date, reference text, verse text)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH me AS (
    SELECT public.verse_pool_match(p_verse, p_reference) AS pool_id,
           public.verse_text_key(p_verse) AS tk,
           public.verse_ref_key(p_reference) AS rk
  )
  SELECT v.id, v.date, v.reference, v.verse
  FROM public.verse_of_the_day v, me
  WHERE v.date BETWEEN public.verse_conflict_window_start(p_date)
                   AND public.verse_conflict_window_end(p_date)
    AND (p_exclude_id IS NULL OR v.id <> p_exclude_id)
    AND (
      (me.pool_id IS NOT NULL AND v.pool_id = me.pool_id)
      OR v.text_key = me.tk
      OR v.ref_key = me.rk
    )
  ORDER BY v.date;
$$;

GRANT EXECUTE ON FUNCTION public.check_verse_conflicts(text, text, date, uuid) TO authenticated;

-- All rule violations in the plan (for the admin overview).
CREATE OR REPLACE VIEW public.verse_schedule_conflicts
WITH (security_invoker = true) AS
WITH pairs AS (
  SELECT a.id AS a_id, b.id AS b_id
  FROM public.verse_of_the_day a
  JOIN public.verse_of_the_day b
    ON b.pool_id = a.pool_id
   AND b.date > a.date AND b.date <= public.verse_conflict_window_end(a.date)
  UNION
  SELECT a.id, b.id
  FROM public.verse_of_the_day a
  JOIN public.verse_of_the_day b
    ON b.text_key = a.text_key
   AND b.date > a.date AND b.date <= public.verse_conflict_window_end(a.date)
  UNION
  SELECT a.id, b.id
  FROM public.verse_of_the_day a
  JOIN public.verse_of_the_day b
    ON b.ref_key = a.ref_key
   AND b.date > a.date AND b.date <= public.verse_conflict_window_end(a.date)
)
-- b lies inside a's forbidden window = same calendar year or < 365 days apart
SELECT a.id AS first_id, a.date AS first_date,
       b.id AS second_id, b.date AS second_date,
       b.reference, (b.date - a.date) AS days_between
FROM pairs
JOIN public.verse_of_the_day a ON a.id = pairs.a_id
JOIN public.verse_of_the_day b ON b.id = pairs.b_id;

-- ───────────────────────────────────────────────────────────────────────────
-- 6) Planner
-- ───────────────────────────────────────────────────────────────────────────
-- content.created_at of pre-planned verses is pinned to 2026-01-01 so that
-- thousands of future verses never push real posts/videos out of the
-- "newest content" lists (search etc.) that sort by content.created_at.
CREATE OR REPLACE FUNCTION public.schedule_verses_of_the_day(
  p_until date,
  p_from date DEFAULT NULL
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_from date := greatest(coalesce(p_from, current_date + 1), current_date + 1);
  v_day date;
  v_pick bigint;
  v_inserted integer := 0;
BEGIN
  DROP TABLE IF EXISTS _vs_days, _vs_use, _vs_last, _vs_plan;

  CREATE TEMP TABLE _vs_days ON COMMIT DROP AS
  SELECT g.d::date AS d
  FROM generate_series(v_from, p_until, interval '1 day') g(d)
  WHERE NOT EXISTS (SELECT 1 FROM public.verse_of_the_day v WHERE v.date = g.d::date);

  IF NOT EXISTS (SELECT 1 FROM _vs_days) THEN
    RETURN 0;
  END IF;

  -- Every existing appearance of every pool verse (linked rows + manual rows
  -- that only match by text/reference).
  CREATE TEMP TABLE _vs_use ON COMMIT DROP AS
  SELECT v.pool_id, v.date AS d FROM public.verse_of_the_day v WHERE v.pool_id IS NOT NULL
  UNION
  SELECT p.id, u.date
  FROM public.verse_of_the_day u
  JOIN public.verse_pool p
    ON u.text_key = p.text_key
    OR u.ref_key = p.ref_key
    OR u.ref_key = ANY (p.alt_ref_keys)
  WHERE u.pool_id IS NULL;
  CREATE INDEX ON _vs_use (pool_id, d);

  CREATE TEMP TABLE _vs_last ON COMMIT DROP AS
  SELECT p.id AS pool_id,
         (SELECT max(u.d) FROM _vs_use u WHERE u.pool_id = p.id AND u.d < v_from) AS last_d
  FROM public.verse_pool p
  WHERE p.is_active;
  CREATE INDEX ON _vs_last (last_d NULLS FIRST, pool_id);

  CREATE TEMP TABLE _vs_plan (d date PRIMARY KEY, pool_id bigint, cid uuid DEFAULT gen_random_uuid()) ON COMMIT DROP;
  ANALYZE _vs_use;
  ANALYZE _vs_last;

  FOR v_day IN SELECT d FROM _vs_days ORDER BY d LOOP
    -- least-recently-used verse that is allowed on this day; a little
    -- randomness among the 25 longest-unused ones so it is not a fixed cycle.
    SELECT c.pool_id INTO v_pick
    FROM (
      SELECT l.pool_id
      FROM _vs_last l
      WHERE NOT EXISTS (
        SELECT 1 FROM _vs_use u
        WHERE u.pool_id = l.pool_id
          AND u.d BETWEEN public.verse_conflict_window_start(v_day)
                      AND public.verse_conflict_window_end(v_day)
      )
      ORDER BY l.last_d NULLS FIRST, l.pool_id
      LIMIT 25
    ) c
    ORDER BY random()
    LIMIT 1;

    IF v_pick IS NULL THEN
      RAISE WARNING 'schedule_verses_of_the_day: no eligible verse for % (pool too small?)', v_day;
      CONTINUE;
    END IF;

    UPDATE _vs_last SET last_d = v_day WHERE pool_id = v_pick;
  END LOOP;

  -- Write the plan in one go. No push / translation / webhook triggers for
  -- bulk planning; the lock is held only for these few statements' transaction,
  -- so other sessions never see the triggers disabled.
  ALTER TABLE public.verse_of_the_day DISABLE TRIGGER USER;
  ALTER TABLE public.content DISABLE TRIGGER USER;

  -- content.created_at pinned to 2026-01-01: pre-planned verses must not push
  -- real posts/videos out of "newest content" lists sorted by created_at.
  SELECT cid, 'verse', 'published', timestamptz '2026-01-01 00:00:00+00' FROM _vs_plan;

  SELECT pl.cid, p.verse, p.reference, pl.d, p.id, true
  FROM _vs_plan pl JOIN public.verse_pool p ON p.id = pl.pool_id
  ON CONFLICT (date) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- a day that was filled manually in the meantime -> drop its unused content row
  DELETE FROM public.content c
  USING _vs_plan pl
  WHERE c.id = pl.cid
    AND NOT EXISTS (SELECT 1 FROM public.verse_of_the_day v WHERE v.content_id = c.id);

  ALTER TABLE public.verse_of_the_day ENABLE TRIGGER USER;
  ALTER TABLE public.content ENABLE TRIGGER USER;

  RETURN v_inserted;
END;
$$;

REVOKE ALL ON FUNCTION public.schedule_verses_of_the_day(date, date) FROM PUBLIC, anon, authenticated;

-- ───────────────────────────────────────────────────────────────────────────
-- 7) Translations for the next days: reuse existing translations of the
--    identical verse (no new AI cost), queue the rest.
-- ───────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.prepare_upcoming_verse_translations(p_days integer DEFAULT 21)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  r record;
  v_queued integer := 0;
  v_targets integer;
BEGIN
  SELECT count(*) INTO v_targets FROM public.translation_targets WHERE is_active;

  FOR r IN
    SELECT v.id, v.content_id, v.verse, v.reference
    FROM public.verse_of_the_day v
    WHERE v.date BETWEEN current_date AND current_date + p_days
  LOOP
    -- copy from an earlier row with exactly the same text
    SELECT DISTINCT ON (ct.language, ct.field_name)
           r.content_id, ct.language, ct.field_name, ct.value, ct.source_hash, 'auto'
    FROM public.verse_of_the_day o
    JOIN public.content_translations ct ON ct.content_id = o.content_id
    WHERE o.id <> r.id
      AND o.verse = r.verse
      AND o.reference = r.reference
      AND ct.field_name IN ('verse', 'reference')
    ORDER BY ct.language, ct.field_name, (ct.source_hash IS NOT NULL) DESC, ct.updated_at DESC NULLS LAST
    ON CONFLICT (content_id, language, field_name) DO NOTHING;

    IF (SELECT count(*) FROM public.content_translations ct
        WHERE ct.content_id = r.content_id AND ct.source_hash IS NOT NULL
          AND ct.field_name IN ('verse', 'reference')) < v_targets * 2 THEN
      PERFORM public.enqueue_translation('verse', r.id::text, 5);
      v_queued := v_queued + 1;
    END IF;
  END LOOP;

  IF v_queued > 0 THEN
    PERFORM public.kick_translation_worker();
  END IF;
  RETURN v_queued;
EXCEPTION WHEN undefined_function OR undefined_table THEN
  RAISE WARNING 'translation system not installed – skipping verse translations';
  RETURN 0;
END;
$$;

REVOKE ALL ON FUNCTION public.prepare_upcoming_verse_translations(integer) FROM PUBLIC, anon, authenticated;

-- ───────────────────────────────────────────────────────────────────────────
-- 8) Daily maintenance: always 10 years planned ahead ("für unendlich")
-- ───────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.maintain_verse_schedule()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_planned integer;
  v_queued integer;
BEGIN
  v_planned := public.schedule_verses_of_the_day((current_date + interval '10 years')::date);
  v_queued := public.prepare_upcoming_verse_translations(21);
  RETURN jsonb_build_object('planned', v_planned, 'translations_queued', v_queued);
END;
$$;

REVOKE ALL ON FUNCTION public.maintain_verse_schedule() FROM PUBLIC, anon, authenticated;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname = 'verse-schedule-maintenance';
    PERFORM cron.schedule('verse-schedule-maintenance', '17 2 * * *', 'select public.maintain_verse_schedule();');
  ELSE
    RAISE WARNING 'pg_cron not installed – run select public.maintain_verse_schedule(); regularly';
  END IF;
END
$$;

-- ───────────────────────────────────────────────────────────────────────────
-- 9) Admin overview
-- ───────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_verse_schedule_overview()
RETURNS TABLE (
  year integer,
  days_in_year integer,
  days_planned integer,
  auto_planned integer,
  with_image integer,
  conflicts integer,
  first_free_day date
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH years AS (
    SELECT generate_series(
             extract(year FROM current_date)::int,
             greatest(extract(year FROM current_date)::int,
                      extract(year FROM (SELECT max(date) FROM public.verse_of_the_day))::int)
           ) AS y
  ),
  conf AS (
    SELECT extract(year FROM second_date)::int AS y, count(*)::int AS n
    FROM public.verse_schedule_conflicts
    WHERE second_date >= current_date
    GROUP BY 1
  )
  SELECT
    y.y,
    (make_date(y.y + 1, 1, 1) - make_date(y.y, 1, 1))::int,
    count(v.id)::int,
    count(v.id) FILTER (WHERE v.auto_scheduled)::int,
    count(v.id) FILTER (WHERE coalesce(v.image_url, '') <> '')::int,
    coalesce(max(conf.n), 0)::int,
    (SELECT min(g.d)::date
       FROM generate_series(greatest(make_date(y.y, 1, 1), current_date), make_date(y.y, 12, 31), interval '1 day') g(d)
      WHERE NOT EXISTS (SELECT 1 FROM public.verse_of_the_day x WHERE x.date = g.d::date))
  FROM years y
  LEFT JOIN public.verse_of_the_day v ON extract(year FROM v.date)::int = y.y
  LEFT JOIN conf ON conf.y = y.y
  GROUP BY y.y
  ORDER BY y.y;
$$;

GRANT EXECUTE ON FUNCTION public.get_verse_schedule_overview() TO authenticated;

-- ───────────────────────────────────────────────────────────────────────────
-- 10) Seed the pool + link existing rows (data generated from history)
-- ───────────────────────────────────────────────────────────────────────────
ALTER TABLE public.verse_of_the_day DISABLE TRIGGER USER;

CREATE TEMP TABLE _pool_seed (idx integer PRIMARY KEY, verse text, reference text, raw_refs text[]) ON COMMIT DROP;
CREATE TEMP TABLE _row_map (row_id uuid PRIMARY KEY, idx integer) ON COMMIT DROP;










SELECT s.verse, s.reference,
       ARRAY(SELECT DISTINCT public.verse_ref_key(x) FROM unnest(s.raw_refs || s.reference) x),
       'history'
FROM _pool_seed s
ORDER BY s.idx
ON CONFLICT (text_key) DO NOTHING;

UPDATE public.verse_of_the_day v
SET pool_id = p.id
FROM _row_map m
JOIN _pool_seed s ON s.idx = m.idx
JOIN public.verse_pool p ON p.text_key = public.verse_text_key(s.verse)
WHERE v.id = m.row_id
  AND v.pool_id IS NULL;

-- rows created after the data export: match by text / reference
UPDATE public.verse_of_the_day v
SET pool_id = public.verse_pool_match(v.verse, v.reference)
WHERE v.pool_id IS NULL;

ALTER TABLE public.verse_of_the_day ENABLE TRIGGER USER;

-- ───────────────────────────────────────────────────────────────────────────
-- 11) Plan the next 10 years (+ rest of the last year) right away
-- ───────────────────────────────────────────────────────────────────────────
SELECT public.schedule_verses_of_the_day(make_date(extract(year FROM current_date)::int + 10, 12, 31));
SELECT public.prepare_upcoming_verse_translations(21);

COMMIT;
