    INSERT INTO _vs_plan (d, pool_id) VALUES (v_day, v_pick);
    INSERT INTO _vs_use (pool_id, d) VALUES (v_pick, v_day);
  INSERT INTO public.content (id, content_type, status, created_at)
  INSERT INTO public.verse_of_the_day (content_id, verse, reference, date, pool_id, auto_scheduled)
    INSERT INTO public.content_translations (content_id, language, field_name, value, source_hash, status)
INSERT INTO _pool_seed (idx, verse, reference, raw_refs) VALUES
  (0, 'Jesus aber sprach zu ihnen: Ich bin das Brot des Lebens. Wer zu mir kommt, den wird nicht hungern, und wer an mich glaubt, den wird niemals dürsten.', 'Johannes 6,35', ARRAY['Johannes 6,35', 'Johannes 6:35']::text[]),
  (1, 'Der Gerechte muss viel Böses erleiden; aber aus allem rettet ihn der HERR.', 'Psalm 34,20', ARRAY['Psalm 34,20', 'Psalmen 34:20']::text[]),
  (2, 'Wenn wir sagen, dass wir Gemeinschaft mit ihm haben, und doch in der Finsternis wandeln, so lügen wir und tun nicht die Wahrheit.', '1. Johannes 1,6', ARRAY['1.Johannes 1,6']::text[]),
  (3, 'Um deines Namens willen, HERR, erhalte mich am Leben; durch deine Gerechtigkeit führe meine Seele aus der Not!', 'Psalm 143,11', ARRAY['Psalm 143,11']::text[]),
  (4, 'Gütig ist der HERR, eine Zuflucht am Tag der Not; und er kennt die, welche auf ihn vertrauen.', 'Nahum 1,7', ARRAY['Nahum 1,7']::text[]),
  (5, 'Alle eure Sorge werft auf ihn; denn er sorgt für euch.', '1. Petrus 5,7', ARRAY['1. Petrus 5,7', '1.Petrus 5,7']::text[]),
  (6, 'Naht euch zu Gott, so naht er sich zu euch! Reinigt die Hände, ihr Sünder, und heiligt eure Herzen, die ihr geteilten Herzens seid!', 'Jakobus 4,8', ARRAY['Jakobus 4,8', 'Jakobus 4,8a']::text[]),
  (7, 'Großen Frieden haben, die dein Gesetz lieben, und nichts bringt sie zu Fall.', 'Psalm 119,165', ARRAY['Psalm 119,165']::text[]),
  (8, 'Und als es das Buch nahm, fielen die vier lebendigen Wesen und die 24 Ältesten vor dem Lamm nieder, und sie hatten jeder eine Harfe und eine goldene Schale voll Räucherwerk; das sind die Gebete der Heiligen.', 'Offenbarung 5,8', ARRAY['Offenbarung 5,8']::text[]),
  (9, 'Es ist aber nahe gekommen das Ende aller Dinge. So seid nun besonnen und nüchtern zum Gebet.', '1. Petrus 4,7', ARRAY['1. Petrus 4,7', '1.Petrus 4,7']::text[]),
  (10, 'Von ferne her ist mir der HERR erschienen: Mit ewiger Liebe habe ich dich geliebt; darum habe ich dich zu mir gezogen aus lauter Gnade.', 'Jeremia 31,3', ARRAY['Jeremia 31,3']::text[]),
  (11, 'Siehe, ich komme bald; halte fest, was du hast, damit dir niemand deine Krone nehme!', 'Offenbarung 3,11', ARRAY['Offenbarung 3,11']::text[]),
  (12, 'Dann wird dein Licht hervorbrechen wie die Morgenröte, und deine Heilung wird rasche Fortschritte machen; deine Gerechtigkeit wird vor dir hergehen, und die Herrlichkeit des HERRN wird deine Nachhut sein!', 'Jesaja 58,8', ARRAY['Jesaja 58,8']::text[]),
  (13, 'Was wollen wir nun hierzu sagen? Ist Gott für uns, wer kann gegen uns sein?', 'Römer 8,31', ARRAY['Römer 8,31 b', 'Römerbrief 8:31']::text[]),
  (14, 'Jesus spricht zu ihm: Ich bin der Weg und die Wahrheit und das Leben; niemand kommt zum Vater als nur durch mich!', 'Johannes 14,6', ARRAY['Johannes 14,6', 'Johannes 14:6']::text[]),
  (15, 'Und du, Bethlehem im Land Juda, bist keineswegs die geringste unter den Fürstenstädten Judas; denn aus dir wird ein Herrscher hervorgehen, der mein Volk Israel weiden soll.', 'Matthäus 2,6', ARRAY['Matthäus 2,6']::text[]),
  (16, 'Sorgt euch um nichts; sondern in allem lasst durch Gebet und Flehen mit Danksagung eure Anliegen vor Gott kundwerden.', 'Philipper 4,6', ARRAY['Philipper 4,6']::text[]),
  (17, 'Besser ist’s, bei dem Herrn Schutz zu suchen, als sich auf Menschen zu verlassen.', 'Psalm 118,8', ARRAY['Psalm 118,8']::text[]),
  (18, 'Siehe, ich stehe vor der Tür und klopfe an. Wenn jemand meine Stimme hört und die Tür öffnet, so werde ich zu ihm hineingehen und das Mahl mit ihm essen und er mit mir.', 'Offenbarung 3,20', ARRAY['Offenbarung 3,20']::text[]),
  (19, 'Durch Glauben verließ er Ägypten, ohne die Wut des Königs zu fürchten; denn er hielt sich an den Unsichtbaren, als sähe er ihn.', 'Hebräer 11,27', ARRAY['Hebräer 11,27']::text[]),
  (20, 'Und er hat zu mir gesagt: Lass dir an meiner Gnade genügen, denn meine Kraft wird in der Schwachheit vollkommen! Darum will ich mich am liebsten vielmehr meiner Schwachheiten rühmen, damit die Kraft des Christus bei mir wohne.', '2. Korinther 12,9', ARRAY['2. Korinther 12,9', '2.Korinther 12,9']::text[]),
  (21, 'Der Herr aber lenke eure Herzen zu der Liebe Gottes und zum standhaften Ausharren des Christus!', '2. Thessalonicher 3,5', ARRAY['2. Thessalonicher 3,5', '2.Thessalonicher 3,5']::text[]),
  (22, 'Denn die Berge mögen weichen und die Hügel wanken, aber meine Gnade wird nicht von dir weichen und mein Friedensbund nicht wanken, spricht der HERR, dein Erbarmer.', 'Jesaja 54,10', ARRAY['Jesaja 54,10']::text[]),
  (23, 'Und siehe, des HERRN Engel trat zu ihnen, und die Klarheit des HERRN leuchtete um sie; und sie fürchteten sich sehr. 10 Und der Engel sprach zu ihnen: Fürchtet euch nicht! siehe, ich verkündige euch große Freude, die allem Volk widerfahren wird;', 'Lukas 2,9-10', ARRAY['Lukas 2,10-11', 'Lukas 2:9-10']::text[]),
  (24, 'Ich meine aber das: Wer da kärglich sät, der wird auch kärglich ernten; und wer da sät im Segen, der wird auch ernten im Segen.', '2. Korinther 9,6', ARRAY['2. Korinther 9,6', '2. Korinther 9:6', '2.Korinther 9,6']::text[]),
  (25, 'Sät euch Gerechtigkeit, erntet nach dem Maß der Gnade! Pflügt einen Neubruch, denn es ist Zeit, den Herrn zu suchen, bis er kommt und euch Gerechtigkeit regnen lässt!', 'Hosea 10,12', ARRAY['Hosea 10,12']::text[]),
  (26, 'Wenn ihr in mir bleibt und meine Worte in euch bleiben, so werdet ihr bitten, was ihr wollt, und es wird euch zuteilwerden.', 'Johannes 15,7', ARRAY['Johannes 15,7']::text[]),
  (27, 'Gott aber sei Dank, der uns den Sieg gibt durch unseren Herrn Jesus Christus!', '1. Korinther 15,57', ARRAY['1.Korinther 15,57']::text[]),
  (28, 'Ich bin der Weinstock, ihr seid die Reben. Wer in mir bleibt und ich in ihm, der bringt viel Frucht; denn getrennt von mir könnt ihr nichts tun.', 'Johannes 15,5', ARRAY['Johannes 15,5', 'Johannes 15,5b']::text[]),
  (29, 'Jesus aber sprach zu ihm: Wenn du glauben kannst — alles ist möglich dem, der glaubt!', 'Markus 9,23', ARRAY['Markus 9,23', 'Markus 9,23-24', 'Markus 9:23']::text[]),
  (30, 'Denn ich bin überzeugt, dass die Leiden der jetzigen Zeit nicht ins Gewicht fallen gegenüber der Herrlichkeit, die an uns geoffenbart werden soll.', 'Römer 8,18', ARRAY['Römer 8,18']::text[]),
  (31, 'Denn ihr sollt so gesinnt sein, wie es Christus Jesus auch war.', 'Philipper 2,5', ARRAY['Philipper 2,5']::text[]),
  (32, 'Wenn du aber seiner Stimme wirklich gehorchen und alles tun wirst, was ich sage, so will ich der Feind deiner Feinde sein und der Widersacher deiner Widersacher.', '2. Mose 23,22', ARRAY['2.Mose 23,22']::text[]),
  (33, 'Auf Gott vertraue ich und fürchte mich nicht; was kann ein Mensch mir antun?', 'Psalm 56,12', ARRAY['Psalm 56,12']::text[]),
  (34, 'Und sie sangen wie ein neues Lied vor dem Thron und vor den vier lebendigen Wesen und den Ältesten, und niemand konnte das Lied lernen als nur die hundertvierundvierzigtausend, die erkauft worden sind von der Erde.', 'Offenbarung 14,3', ARRAY['Offenbarung 14,3']::text[]),
  (35, 'Der Herr, dein Gott, ist in deiner Mitte, ein Held, der rettet; er wird sich über dich freuen mit Wonne, er wird still sein in seiner Liebe, er wird über dich jubelnd frohlocken.', 'Zephanja 3,17', ARRAY['Zefanja 3,17', 'Zephanja 3,17', 'Zephanja 3:17']::text[]),
  (36, 'Da ihr eure Seelen im Gehorsam gegen die Wahrheit gereinigt habt durch den Geist zu ungeheuchelter Bruderliebe, so liebt einander beharrlich und aus reinem Herzen!', '1. Petrus 1,22', ARRAY['1. Petrus 1,22', '1.Petrus 1,22']::text[]),
  (37, 'Denn siehe, der die Berge bildet und den Wind schafft und den Menschen wissen lässt, was seine Gedanken sind, der das Morgenrot und das Dunkel macht und einherschreitet über die Höhen der Erde — HERR, Gott der Heerscharen ist sein Name.', 'Amos 4,13', ARRAY['Amos 4,13']::text[]),
  (38, 'Unter euch aber soll es nicht so sein; sondern wer unter euch groß werden will, der sei euer Diener, und wer unter euch der Erste sein will, der sei euer Knecht.', 'Matthäus 20,26-27', ARRAY['Matthäus 20,26', 'Matthäus 20,26-27']::text[]),
  (39, 'Der HERR aber sprach zu Mose: Ist denn die Hand des HERRN zu kurz? Jetzt sollst du sehen, ob mein Wort vor dir eintreffen wird oder nicht!', '4. Mose 11,23', ARRAY['4.Mose 11,23']::text[]),
  (40, 'Lasst uns aber im Gutestun nicht müde werden; denn zu seiner Zeit werden wir auch ernten, wenn wir nicht ermatten.', 'Galater 6,9', ARRAY['Galater 6,9']::text[]),
  (41, 'Ich bin die Tür. Wenn jemand durch mich hineingeht, wird er gerettet werden und wird ein- und ausgehen und Weide finden.', 'Johannes 10,9', ARRAY['Johannes 10,9']::text[]),
  (42, 'So kommen wir nun zu dem Schluss, dass der Mensch durch den Glauben gerechtfertigt wird, ohne Werke des Gesetzes.', 'Römer 3,28', ARRAY['Römer 3,28']::text[]),
  (43, 'Bei den vielen Sorgen in meinem Herzen erquickten deine Tröstungen meine Seele.', 'Psalm 94,19', ARRAY['Psalm 94,18', 'Psalm 94,19', 'Psalmen 94:18', 'Psalmen 94:18-19', 'Psalmen 94:19']::text[]),
  (44, 'Habe ich dir nicht geboten, dass du stark und mutig sein sollst? Sei unerschrocken und sei nicht verzagt; denn der Herr, dein Gott, ist mit dir überall, wo du hingehst!', 'Josua 1,9', ARRAY['Josua 1,9']::text[]),
  (45, 'Und er sprach zu ihnen: Geht hin in alle Welt und verkündigt das Evangelium der ganzen Schöpfung!', 'Markus 16,15', ARRAY['Markus 16,15']::text[]),
  (46, 'Der Herr ist nahe allen, die ihn anrufen, allen, die ihn in Wahrheit anrufen;', 'Psalm 145,18', ARRAY['Psalm 145,18', 'Psalmen 145:18']::text[]),
  (47, 'sondern wie der, welcher euch berufen hat, heilig ist, sollt auch ihr heilig sein in eurem ganzen Wandel.', '1. Petrus 1,15', ARRAY['1. Petrus 1:15', '1.Petrus 1,15']::text[]),
  (48, 'So soll man uns betrachten: als Diener des Christus und Haushalter der Geheimnisse Gottes.', '1. Korinther 4,1', ARRAY['1.Korinther 4,1']::text[]),
  (49, 'Wenn du durchs Wasser gehst, so will ich bei dir sein, und wenn durch Ströme, so sollen sie dich nicht ersäufen. Wenn du durchs Feuer gehst, sollst du nicht versengt werden, und die Flamme soll dich nicht verbrennen. Denn ich bin der Herr, dein Gott, der Heilige Israels, dein Erretter! Ich habe Ägypten hingegeben als Lösegeld für dich, Kusch und Saba an deiner Stelle.', 'Jesaja 43,2-3', ARRAY['Jesaja 43,2', 'Jesaja 43,2-3']::text[]),
  (50, 'Da sprach Haggai, der Bote des HERRN, im Auftrag des HERRN zum Volk: Ich bin mit euch!, spricht der HERR.', 'Haggai 1,13', ARRAY['Haggai 1,13']::text[]),
  (51, 'Überaus trügerisch ist das Herz und bösartig; wer kann es ergründen? 10 Ich, der Herr, erforsche das Herz und prüfe die Nieren, um jedem Einzelnen zu vergelten entsprechend seinen Wegen, entsprechend der Frucht seiner Taten.', 'Jeremia 17,9-10', ARRAY['Jeremia 17,10', 'Jeremia 17:9-10']::text[]),
  (52, 'Darum wacht jederzeit und bittet, dass ihr gewürdigt werdet, diesem allem zu entfliehen, was geschehen soll, und vor dem Sohn des Menschen zu stehen!', 'Lukas 21,36', ARRAY['Lukas 21,36']::text[]),
  (53, 'Gedenkt an das Frühere von der Urzeit her, dass Ich Gott bin und keiner sonst; ein Gott, dem keiner zu vergleichen ist', 'Jesaja 46,9', ARRAY['Jesaja 46,9']::text[]),
  (54, 'Wisst ihr nicht, dass ihr Gottes Tempel seid, und dass der Geist Gottes in euch wohnt? Wenn jemand den Tempel Gottes verderbt, den wird Gott verderben; denn der Tempel Gottes ist heilig, und der seid ihr.', '1. Korinther 3,16-17', ARRAY['1. Korinther 3,16-17', '1.Korinther 3,16-17']::text[]),
  (55, 'Ich bin das A und das O, der Anfang und das Ende, spricht der Herr, der ist und der war und der kommt, der Allmächtige.', 'Offenbarung 1,8', ARRAY['Offenbarung 1,8']::text[]),
  (56, 'Ich sage euch, so ist auch Freude vor den Engeln Gottes über einen Sünder, der Buße tut.', 'Lukas 15,10', ARRAY['Lukas 15,10']::text[]),
  (57, 'Der Herr ist mein Teil!, spricht meine Seele; darum will ich auf ihn hoffen. Der Herr ist gütig gegen die, welche auf ihn hoffen, gegen die Seele, die nach ihm sucht.', 'Klagelieder 3,24-25', ARRAY['Klagelieder 3,24-25', 'Klagelieder 3,25']::text[]),
  (58, 'Die Opfer, die Gott gefallen, sind ein zerbrochener Geist; ein zerbrochenes und zerschlagenes Herz wirst du, o Gott, nicht verachten.', 'Psalm 51,19', ARRAY['Psalm 51,19']::text[]),
  (59, 'Das Herz des Menschen denkt sich seinen Weg aus, aber der Herr lenkt seine Schritte.', 'Sprüche 16,9', ARRAY['Sprüche 16,9', 'Sprüche 16:9']::text[]),
  (60, 'Als du anfingst zu beten, erging ein Wort, und ich bin gekommen, es dir zu verkünden; denn du bist ein viel geliebter Mann.', 'Daniel 9,23', ARRAY['Daniel 9,23']::text[]),
  (61, 'Kinder, ihr seid aus Gott und habt jene überwunden, weil der, welcher in euch ist, größer ist als der, welcher in der Welt ist.', '1. Johannes 4,4', ARRAY['1. Johannes 4,4', '1.Johannes 4,4']::text[]),
  (62, 'Und er sprach zum Menschen: »Siehe, die Furcht des Herrn, das ist Weisheit, und vom Bösen weichen, das ist Einsicht!«', 'Hiob 28,28', ARRAY['Hiob 28,28']::text[]),
  (63, 'Gott aber ist treu; er wird nicht zulassen, dass ihr über euer Vermögen versucht werdet, sondern er wird zugleich mit der Versuchung auch den Ausgang schaffen, sodass ihr sie ertragen könnt.', '1. Korinther 10,13', ARRAY['1.Korinther 10,13', '1.Korinther 10,13b']::text[]),
  (64, 'Ein fröhliches Herz fördert die Genesung, aber ein niedergeschlagener Geist dörrt das Gebein aus.', 'Sprüche 17,22', ARRAY['Sprüche 17,22']::text[]),
  (65, 'Ich selbst will vor dir herziehen und das Hügelige eben machen; ich will eherne Türen zerbrechen und eiserne Riegel zerschlagen; und ich will dir verborgene Schätze geben und versteckte Reichtümer, damit du erkennst, dass ich, der HERR, es bin, der dich bei deinem Namen gerufen hat, der Gott Israels.', 'Jesaja 45,2-3', ARRAY['Jesaja 45,2-3']::text[]),
  (66, 'Lasst das Wort des Christus reichlich in euch wohnen in aller Weisheit; lehrt und ermahnt einander und singt mit Psalmen und Lobgesängen und geistlichen Liedern dem Herrn lieblich in eurem Herzen.', 'Kolosser 3,16', ARRAY['Kolosser 3,16']::text[]),
  (67, 'Glückselig sind die geistlich Armen, denn ihrer ist das Reich der Himmel!', 'Matthäus 5,3', ARRAY['Matthäus 5,3']::text[]),
  (68, 'Wahrlich, wahrlich, ich sage euch: Wer mein Wort hört und dem glaubt, der mich gesandt hat, der hat ewiges Leben und kommt nicht ins Gericht, sondern er ist vom Tod zum Leben hindurchgedrungen.', 'Johannes 5,24', ARRAY['Johannes 5,24']::text[]),
  (69, 'Euch aber, die ihr hört, sage ich: Liebt eure Feinde, tut Gutes denen, die euch hassen; segnet, die euch fluchen, und betet für die, welche euch beleidigen!', 'Lukas 6,27-28', ARRAY['Lukas 6,27-28']::text[]),
  (70, 'So habt auch ihr nun Traurigkeit; ich werde euch aber wiedersehen, und dann wird euer Herz sich freuen, und niemand soll eure Freude von euch nehmen.', 'Johannes 16,22', ARRAY['Johannes 16,22', 'Johannes 16:22']::text[]),
  (71, 'Denn wer sich meiner und meiner Worte schämt, dessen wird sich auch der Sohn des Menschen schämen, wenn er kommen wird in seiner Herrlichkeit und der des Vaters und der heiligen Engel.', 'Lukas 9,26', ARRAY['Lukas 9,26']::text[]),
  (72, 'Mose aber sprach zum Volk: Fürchtet euch nicht! Steht fest und seht die Rettung des Herrn, die er euch heute bereiten wird; denn diese Ägypter, die ihr heute seht, die werdet ihr nicht wiedersehen in Ewigkeit! Der Herr wird für euch kämpfen, und ihr sollt still sein!', '2. Mose 14,13-14', ARRAY['2. Mose 14,13-14', '2.Mose 14,14']::text[]),
  (73, 'Der HERR ist meine Stärke und mein Lobgesang, und er wurde mir zum Heil! Das ist mein starker Gott, ich will ihn preisen; er ist der Gott meines Vaters, ich will ihn erheben.', '2. Mose 15,2', ARRAY['2. Mose 15,2', '2.Mose 15,2']::text[]),
  (74, 'Gott aber beweist seine Liebe zu uns dadurch, dass Christus für uns gestorben ist, als wir noch Sünder waren.', 'Römer 5,8', ARRAY['Römer 5,8']::text[]),
  (75, 'Ich sage aber: Wandelt im Geist, so werdet ihr die Lust des Fleisches nicht vollbringen.', 'Galater 5,16', ARRAY['Galater 5,16']::text[]),
  (76, 'Denn einen anderen Grund kann niemand legen außer dem, der gelegt ist, welcher ist Jesus Christus.', '1. Korinther 3,11', ARRAY['1.Korinther 3,11']::text[]),
  (77, 'Sammelt euch vielmehr Schätze im Himmel, wo weder die Motten noch der Rost sie fressen und wo die Diebe nicht nachgraben und stehlen! Denn wo euer Schatz ist, da wird auch euer Herz sein.', 'Matthäus 6,20-21', ARRAY['Matthäus 6,20-21']::text[]),
  (78, 'Durch Umkehr und Ruhe könntet ihr gerettet werden, im Stillesein und im Vertrauen läge eure Stärke. Aber ihr habt nicht gewollt.', 'Jesaja 30,15', ARRAY['Jesaja 30,15', 'Jesaja 30,15b']::text[]),
  (79, 'Aber die auf den Herrn harren, kriegen neue Kraft, dass sie auffahren mit Flügeln wie Adler, dass sie laufen und nicht matt werden, dass sie wandeln und nicht müde werden.', 'Jesaja 40,31', ARRAY['Jesaja 40,31']::text[]),
  (80, 'Glückselig sind die Trauernden, denn sie sollen getröstet werden!', 'Matthäus 5,4', ARRAY['Matthäus 5,4']::text[]),
  (81, 'Du nun, mein Kind, sei stark in der Gnade, die in Christus Jesus ist', '1. Timotheus 2,1', ARRAY['1.Timotheus 2,1']::text[]),
  (82, 'Jede gute Gabe und jedes vollkommene Geschenk kommt von oben herab, von dem Vater der Lichter, bei dem keine Veränderung ist, noch ein Schatten infolge von Wechsel.', 'Jakobus 1,17', ARRAY['Jakobus 1,17']::text[]),
  (83, 'Glückselig sind, die reinen Herzens sind, denn sie werden Gott schauen!', 'Matthäus 5,8', ARRAY['Matthäus 5,8']::text[]),
  (84, 'Denn für mich ist Christus das Leben, und das Sterben ein Gewinn.', 'Philipper 1,21', ARRAY['Philipper 1,21']::text[]),
  (85, 'Forscht nach im Buch des Herrn und lest es! Nicht eines von alledem wird fehlen; zu keinem Wort wird man die Erfüllung vermissen; denn mein Mund ist’s, der es befohlen, und sein Geist ist’s, der sie gesammelt hat.', 'Jesaja 34,16', ARRAY['Jesaja 34,16']::text[]),
  (86, 'Ein beständiges Feuer soll auf dem Altar in Brand gehalten werden; es soll nie erlöschen!', '3. Mose 6,6', ARRAY['3.Mose 6,6']::text[]),
  (87, 'Du leitest mich nach deinem Rat und nimmst mich danach in Herrlichkeit auf!', 'Psalm 73,24', ARRAY['Psalm 73,23-24', 'Psalm 73,24']::text[]),
  (88, 'Die aber Christus angehören, die haben das Fleisch gekreuzigt samt den Leidenschaften und Lüsten.', 'Galater 5,24', ARRAY['Galater 5,24']::text[]),
  (89, 'HERR, sei uns gnädig; wir hoffen auf dich! Sei du jeden Morgen unser Arm, ja, sei du unsere Rettung zur Zeit der Drangsal!', 'Jesaja 33,2', ARRAY['Jesaja 33,2']::text[]),
  (90, 'Ich aber vertraue auf deine Gnade; Mein Herz soll frohlocken in deinem Heil. Ich will dem HERRN singen, weil er mir wohlgetan hat.', 'Psalm 13,6', ARRAY['Psalm 13, 5-6', 'Psalm 13,6']::text[]),
  (91, 'Und ich hörte die Stimme des Herrn fragen: Wen soll ich senden, und wer wird für uns gehen? Da sprach ich: Hier bin ich, sende mich!', 'Jesaja 6,8', ARRAY['Jesaja 6,8']::text[]),
  (92, 'Er streckte seine Hand aus von der Höhe und ergriff mich, Er zog mich aus großen Wassern.', '2. Samuel 22,17', ARRAY['2.Samuel 22,17']::text[]),
  (93, 'Im Übrigen, ihr Brüder, freut euch, lasst euch zurechtbringen, lasst euch ermahnen, seid eines Sinnes, haltet Frieden; so wird der Gott der Liebe und des Friedens mit euch sein!', '2. Korinther 13,11', ARRAY['2.Korinther 13,11']::text[]),
  (94, 'Aber ich sage euch die Wahrheit: Es ist gut für euch, dass ich hingehe; denn wenn ich nicht hingehe, so kommt der Beistand nicht zu euch. Wenn ich aber hingegangen bin, will ich ihn zu euch senden.', 'Johannes 16,7', ARRAY['Johannes 16,7']::text[]),
  (95, 'Glückselig sind die Sanftmütigen, denn sie werden das Land erben', 'Matthäus 5,5', ARRAY['Matthäus 5,5']::text[]),
  (96, 'Seid fröhlich in Hoffnung, in Bedrängnis haltet stand, seid beharrlich im Gebet!', 'Römer 12,12', ARRAY['Römer 12,12']::text[]),
  (97, 'Behüte deine Zunge vor Bösem Und deine Lippen, dass sie nicht betrügen; Weiche vom Bösen und tue Gutes, Suche den Frieden und jage ihm nach!', 'Psalm 34,14-15', ARRAY['Psalm 34,14-15']::text[]),
  (98, 'Der gute Mensch bringt aus dem guten Schatz seines Herzens das Gute hervor, und der böse Mensch bringt aus dem bösen Schatz seines Herzens das Böse hervor; denn wovon sein Herz voll ist, davon redet sein Mund.', 'Lukas 6,45', ARRAY['Lukas 6,45']::text[]),
  (99, 'Und die Freundlichkeit des Herrn, unsres Gottes, sei über uns, und das Werk unsrer Hände fördere du für uns, ja, das Werk unsrer Hände wollest du fördern!', 'Psalm 90,17', ARRAY['Psalm 90,17']::text[]),
  (100, 'Von David. Der HERR ist mein Licht und mein Heil, vor wem sollte ich mich fürchten? Der Herr ist meines Lebens Kraft, vor wem sollte mir grauen?', 'Psalm 27,1', ARRAY['Psalm 27,1']::text[]),
  (101, 'Nur führt euer Leben würdig des Evangeliums von Christus, damit ich, ob ich komme und euch sehe oder abwesend bin, von euch höre, dass ihr fest steht in einem Geist und einmütig miteinander kämpft für den Glauben des Evangeliums.', 'Philipper 1,27', ARRAY['Philipper 1,27']::text[]),
  (102, 'Und ich will einen ewigen Bund mit ihnen schließen, dass ich nicht von ihnen ablassen will, ihnen wohlzutun. Und ich werde die Furcht vor mir in ihr Herz geben, damit sie nicht mehr von mir abweichen.', 'Jeremia 32,40', ARRAY['Jeremia 32,40']::text[]),
  (103, 'Lehre uns unsere Tage richtig zählen, damit wir ein weises Herz erlangen!', 'Psalm 90,12', ARRAY['Psalm 90,12']::text[]),
  (104, 'Und er führte sie heraus und sprach: Ihr Herren, was muss ich tun, dass ich gerettet werde? Sie aber sprachen: Glaube an den Herrn Jesus Christus, so wirst du gerettet werden, du und dein Haus!', 'Apostelgeschichte 16,30-31', ARRAY['Apostelgeschichte 16,30-31']::text[]),
  (105, 'Darum, weil du kostbar bist in meinen Augen und wert geachtet und ich dich lieb habe, so gebe ich Menschen für dich hin und Völker für dein Leben.', 'Jesaja 43,4', ARRAY['Jesaja 43,4']::text[]),
  (106, 'So lasst uns nun, wo wir Gelegenheit haben, an allen Gutes tun, besonders aber an den Hausgenossen des Glaubens.', 'Galater 6,10', ARRAY['Galater 6,10']::text[]),
  (107, 'Glückselig sind, die nach der Gerechtigkeit hungern und dürsten, denn sie sollen satt werden!', 'Matthäus 5,6', ARRAY['Matthäus 5,6']::text[]),
  (108, 'Das sind die, welche Trennungen verursachen, natürliche Menschen, die den Geist nicht haben.', 'Judas 19', ARRAY['Judas 19']::text[]),
  (109, 'Vertraue auf den Herrn von ganzem Herzen und verlass dich nicht auf deinen Verstand.', 'Sprüche 3,5', ARRAY['Sprüche 3,5', 'Sprüche 3,5-6']::text[]),
  (110, 'Denn ich schäme mich des Evangeliums von Christus nicht; denn es ist Gottes Kraft zur Errettung für jeden, der glaubt, zuerst für den Juden, dann auch für den Griechen; denn es wird darin geoffenbart die Gerechtigkeit Gottes aus Glauben zum Glauben, wie geschrieben steht: »Der Gerechte wird aus Glauben leben«.', 'Römer 1,16-17', ARRAY['Römer 1,16', 'Römer 1,16-17']::text[]),
  (111, 'Und wenn du gegessen hast und satt geworden bist, dann sollst du den Herrn, deinen Gott, loben für das gute Land, das er dir gegeben hat.', '5. Mose 8,10', ARRAY['5. Mose 8,10', '5.Mose 8,10']::text[]),
  (112, 'Dem HERRN, eurem Gott, sollt ihr nachfolgen und ihn fürchten und seine Gebote halten und seiner Stimme gehorchen und ihm dienen und ihm anhängen.', '5. Mose 13,5', ARRAY['5. Mose 13,5', '5.Mose 13,5']::text[]),
  (113, 'Siehe, wohl dem Menschen, den Gott zurechtweist! Darum verwirf die Züchtigung des Allmächtigen nicht! Denn er verwundet und verbindet; er zerschlägt, und seine Hand heilt.', 'Hiob 5,17-18', ARRAY['Hiob 5,17-18']::text[]),
  (114, 'Denn wir haben nicht einen Hohenpriester, der kein Mitleid haben könnte mit unseren Schwachheiten, sondern einen, der in allem versucht worden ist in ähnlicher Weise wie wir, doch ohne Sünde.', 'Hebräer 4,15', ARRAY['Hebräer 4,15', 'Hebräerbrief 4,15']::text[]),
  (115, 'Und es geschah, als die Priester aus dem Heiligtum hinausgingen, da erfüllte die Wolke das Haus des HERRN, sodass die Priester wegen der Wolke nicht hinzutreten konnten, um ihren Dienst zu verrichten; denn die Herrlichkeit des HERRN erfüllte das Haus des HERRN.', '1. Könige 8,10-11', ARRAY['1.Könige 8,10-11']::text[]),
  (116, 'Wenn wir aber unsere Sünden bekennen, so ist er treu und gerecht, dass er uns die Sünden vergibt und uns reinigt von aller Ungerechtigkeit.', '1. Johannes 1,9', ARRAY['1. Johannes 1,9', '1.Johannes 1,9']::text[]),
  (117, 'Ja, wahrlich, ich achte alles für Schaden gegenüber der alles übertreffenden Erkenntnis Christi Jesu, meines Herrn, um dessentwillen ich alles eingebüßt habe; und ich achte es für Dreck, damit ich Christus gewinne.', 'Philipper 3,8', ARRAY['Philipper 3,8']::text[]),
  (118, 'Der Gott der Hoffnung aber erfülle euch mit aller Freude und mit Frieden im Glauben, dass ihr überströmt in der Hoffnung durch die Kraft des Heiligen Geistes!', 'Römer 15,13', ARRAY['Römer 15,13']::text[]),
  (119, 'Glückselig sind die Barmherzigen, denn sie werden Barmherzigkeit erlangen!', 'Matthäus 5,7', ARRAY['Matthäus 5,7']::text[]),
  (120, 'So ist also das Gesetz unser Lehrmeister geworden auf Christus hin, damit wir aus Glauben gerechtfertigt würden.', 'Galater 3,24', ARRAY['Galater 3,24']::text[]),
  (121, 'Und ihr werdet die Wahrheit erkennen, und die Wahrheit wird euch frei machen!', 'Johannes 8,32', ARRAY['Johannes 8,32']::text[]),
  (122, 'Stärkt die schlaff gewordenen Hände und macht fest die strauchelnden Knie; sagt zu denen, die ein verzagtes Herz haben: Seid tapfer und fürchtet euch nicht! Seht, da ist euer Gott! Die Rache kommt, die Vergeltung Gottes; er selbst kommt und wird euch retten!', 'Jesaja 35,3-4', ARRAY['Jesaja 35,3-4']::text[]),
  (123, 'Dein Reich komme. Dein Wille geschehe, wie im Himmel, so auch auf Erden.', 'Matthäus 6,10', ARRAY['Matthäus 6,10']::text[]),
  (124, 'Wenn du sie suchst wie Silber Und nach ihr forschst wie nach Schätzen, Dann wirst du die Furcht des HERRN verstehen Und die Erkenntnis Gottes erlangen.', 'Sprüche 2,4-5', ARRAY['Sprüche 2,4-5']::text[]),
  (125, 'Ich aber bin wie ein grüner Ölbaum im Haus Gottes; Ich vertraue auf die Gnade Gottes für immer und ewig. Ich preise dich ewiglich, denn du hast es vollbracht, Und in der Gegenwart deiner Getreuen harre ich auf deinen Namen, weil er so gut ist.', 'Psalm 52,10-11', ARRAY['Psalm 52,10-11']::text[]),
  (126, 'Und er ging ein wenig weiter, warf sich auf sein Angesicht, betete und sprach: Mein Vater! Ist es möglich, so gehe dieser Kelch an mir vorüber; doch nicht wie ich will, sondern wie du willst!', 'Matthäus 26,39', ARRAY['Matthäus 26,39']::text[]),
  (127, 'Von David. Ein Maskil. Wohl dem, dessen Übertretung vergeben, Dessen Sünde zugedeckt ist! Wohl dem Menschen, dem der HERR keine Schuld anrechnet, Und in dessen Geist keine Falschheit ist!', 'Psalm 32,1-2', ARRAY['Psalm 32,1-2']::text[]),
  (128, 'Doch er wurde um unserer Übertretungen willen durchbohrt, wegen unserer Missetaten zerschlagen; die Strafe lag auf ihm, damit wir Frieden hätten, und durch seine Wunden sind wir geheilt worden.', 'Jesaja 53,5', ARRAY['Jesaja 53,5']::text[]),
  (129, 'Was ist der Mensch, dass du an ihn gedenkst, Und der Sohn des Menschen, dass du auf ihn achtest?', 'Psalm 8,5', ARRAY['Psalm 8,5']::text[]),
  (130, 'Du aber bleibe in dem, was du gelernt hast und was dir zur Gewissheit geworden ist, da du weißt, von wem du es gelernt hast.', '2. Timotheus 3,14', ARRAY['2.Timotheus 3,14', '2.Timothäus 3,14']::text[]),
  (131, 'Ich bin die Auferstehung und das Leben. Wer an mich glaubt wird leben, auch wenn er stirbt; und jeder, der lebt und an mich glaubt, wird in Ewigkeit nicht sterben.', 'Johannes 11,25-26', ARRAY['Johannes 11,25', 'Johannes 11,25-26']::text[]),
  (132, 'So lasst nun ab von dem Menschen, der nur Hauch in seiner Nase hat; denn wofür ist er zu achten?', 'Jesaja 2,22', ARRAY['Jesaja 2,22']::text[]),
  (133, 'Denn er wird seinen Engeln deinetwegen Befehl geben, Dass sie dich behüten auf allen deinen Wegen.', 'Psalm 91,11', ARRAY['Psalm 91,11']::text[]),
  (134, 'Gott ist Geist, und die ihn anbeten, müssen ihn im Geist und in der Wahrheit anbeten.', 'Johannes 4,24', ARRAY['Johannes 4,24']::text[]),
  (135, 'Habt acht, wacht und betet! Denn ihr wisst nicht, wann die Zeit da ist.', 'Markus 13,33', ARRAY['Markus 13,33']::text[]),
  (136, 'Und wenn ein Glied leidet, so leiden alle Glieder mit; und wenn ein Glied geehrt wird, so freuen sich alle Glieder mit.', '1. Korinther 12,26', ARRAY['1.Korinther 12,26']::text[]),
  (137, 'Niemand ist heilig wie der HERR, Ja, es ist keiner außer dir; Und es ist kein Fels wie unser Gott!', '1. Samuel 2,2', ARRAY['1.Samuel 2,2']::text[]),
  (138, 'Denn ihr kennt ja die Gnade unseres Herrn Jesus Christus, dass er, obwohl er reich war, um euretwillen arm wurde, damit ihr durch seine Armut reich würdet.', '2. Korinther 8,9', ARRAY['2. Korinther 8,9', '2.Korinther 8,9']::text[]),
  (139, 'Da legte Ananias ihm die Hände auf und sprach: Bruder Saul, der Herr hat mich gesandt, ….. damit du wieder sehend wirst und erfüllt wirst mit dem Heiligen Geist! Und sogleich fiel es wie Schuppen von seinen Augen…', 'Apostelgeschichte 9,17-18', ARRAY['Apostelgeschichte 9,17-18a']::text[]),
  (140, 'Der Lohn der Demut und der Furcht des HERRN Ist Reichtum, Ehre und Leben.', 'Sprüche 22,4', ARRAY['Sprüche 22,4']::text[]),
  (141, 'Denn ihr wart einst Finsternis; jetzt aber seid ihr Licht in dem Herrn. Wandelt als Kinder des Lichts!', 'Epheser 5,8', ARRAY['Epheser 5,8']::text[]),
  (142, 'Dein Wort ist meines Fußes Leuchte und ein Licht auf meinem Weg', 'Psalm 119,105', ARRAY['Psalm 119,105']::text[]),
  (143, 'Denn ich eifere um euch mit göttlichem Eifer; denn ich habe euch einem Mann verlobt, um euch als eine keusche Jungfrau Christus zuzuführen.', '2. Korinther 11,2', ARRAY['2.Korinther 11,2']::text[]),
  (144, 'So lasst uns nun mit Freimütigkeit hinzutreten zum Thron der Gnade, damit wir Barmherzigkeit erlangen und Gnade finden zu rechtzeitiger Hilfe!', 'Hebräer 4,16', ARRAY['Hebräer 4,16']::text[]),
  (145, 'Höre, mein Sohn, auf die Unterweisung deines Vaters, Und verwirf nicht die Lehre deiner Mutter!', 'Sprüche 1,8', ARRAY['Sprüche 1,8']::text[]),
  (146, 'Darum, Geliebte, weil ihr dies erwartet, so seid eifrig darum bemüht, dass ihr als unbefleckt und tadellos vor ihm erfunden werdet in Frieden!', '2. Petrus 3,14', ARRAY['2. Petrus 3,14', '2.Petrus 3,14']::text[]),
  (147, 'Ist es möglich, soviel an euch liegt, so haltet mit allen Menschen Frieden.', 'Römer 12,18', ARRAY['Römer 12,18']::text[]),
  (148, 'Ein Wallfahrtslied. Von Salomo. Wenn der HERR nicht das Haus baut, Dann arbeiten umsonst, die daran bauen; Wenn der HERR nicht die Stadt behütet, Dann wacht der Wächter umsonst.', 'Psalm 127,1', ARRAY['Psalm 127,1']::text[]),
  (149, 'So sind wir nun Botschafter für Christus, und zwar so, dass Gott selbst durch uns ermahnt; so bitten wir nun stellvertretend für Christus: Lasst euch versöhnen mit Gott!', '2. Korinther 5,20', ARRAY['2.Korinther 5,20']::text[]),
  (150, 'Der HERR aber wird um seines großen Namens willen sein Volk nicht verstoßen, denn es hat dem HERRN gefallen, euch zu seinem Volk zu machen.', '1. Samuel 12,22', ARRAY['1.Samuel 12,22']::text[]),
  (151, 'Wer auf die Unterweisung achtet, geht den Weg zum Leben, Wer aber aus der Schule läuft, gerät auf Irrwege.', 'Sprüche 10,17', ARRAY['Sprüche 10,17']::text[]),
  (152, 'Einer trage des anderen Lasten, und so sollt ihr das Gesetz des Christus erfüllen!', 'Galater 6,2', ARRAY['Galater 6,2']::text[]),
  (153, 'Glückselig sind die Friedfertigen, denn sie werden Söhne Gottes heißen!', 'Matthäus 5,9', ARRAY['Matthäus 5,9']::text[]),
  (154, 'Denn ihr seid teuer erkauft; darum verherrlicht Gott in eurem Leib und in eurem Geist, die Gott gehören!', '1. Korinther 6,20', ARRAY['1. Korinther 6,20', '1.Korinther 6,20']::text[]),
  (155, 'Und alles, was ihr bitten werdet in meinem Namen, das will ich tun, damit der Vater verherrlicht wird in dem Sohn.', 'Johannes 14,13', ARRAY['Johannas 14,13']::text[]),
  (156, 'Öffne mir die Augen, damit ich sehe die Wunder in deinem Gesetz!', 'Psalm 119,18', ARRAY['Psalm 119,18']::text[]),
  (157, 'Was ihr auch gelernt und empfangen und gehört und an mir gesehen habt, das tut; und der Gott des Friedens wird mit euch sein.', 'Philipper 4,9', ARRAY['Philipper 4,9']::text[]),
  (158, 'Ich habe den HERRN allezeit vor Augen;Weil er zu meiner Rechten ist, wanke ich nicht.', 'Psalm 16,8', ARRAY['Psalm 16,8']::text[]),
  (159, 'Mir aber ist die Nähe Gottes köstlich; Ich habe GOTT, den Herrn, zu meiner Zuflucht gemacht, Um alle deine Werke zu verkünden.', 'Psalm 73,28', ARRAY['Psalm 73,28']::text[]),
  (160, 'Und ich sage euch: Bittet, so wird euch gegeben; sucht, so werdet ihr finden; klopft an, so wird euch aufgetan! Denn jeder, der bittet, empfängt; und wer sucht, der findet; und wer anklopft, dem wird aufgetan.', 'Lukas 11,9-10', ARRAY['Lukas 11,9-10']::text[]),
  (161, 'Gehorcht euren Führern und fügt euch ihnen; denn sie wachen über eure Seelen als solche, die einmal Rechenschaft ablegen werden, damit sie das mit Freuden tun und nicht mit Seufzen; denn das wäre nicht gut für euch!', 'Hebräer 13,17', ARRAY['Hebräer 13,17']::text[]),
  (162, 'Herr, ich will dich preisen unter den Völkern, Ich will dir lobsingen unter den Nationen! Denn groß bis zum Himmel ist deine Gnade, Und deine Treue bis zu den Wolken!', 'Psalm 57,10-11', ARRAY['Psalm 57,10-11']::text[]),
  (163, 'Ich sage euch aber, dass die Menschen am Tag des Gerichts Rechenschaft geben müssen von jedem unnützen Wort, das sie geredet haben.', 'Matthäus 12,36', ARRAY['Matthäus 12,36']::text[]),
  (164, 'Euch aber lasse der Herr wachsen und überströmend werden in der Liebe zueinander und zu allen, gleichwie auch wir sie zu euch haben.', '1. Thessalonicher 3,12', ARRAY['1. Thessalonicher 3,12', '1. Thessalonicher 3,12-13', '1.Thessalonicher 3,12']::text[]),
  (165, 'Meinen Bund will ich nicht ungültig machen Und nicht ändern, was über meine Lippen gekommen ist.', 'Psalm 89,35', ARRAY['Psalm 89,35']::text[]),
  (166, 'Glückselig sind, die um der Gerechtigkeit willen verfolgt werden, denn ihrer ist das Reich der Himmel!', 'Matthäus 5,10', ARRAY['Matthäus 5,10']::text[]),
  (167, 'Ja, ich selbst werde ihn schauen, und meine Augen werden ihn sehen, ohne ihm fremd zu sein. Danach sehnt sich mein Herz in mir!', 'Hiob 19,27', ARRAY['Hiob 19,25-27', 'Hiob 19,27']::text[]),
  (168, 'Wahrlich, wahrlich, ich sage euch: Wer an mich glaubt, der hat ewiges Leben.', 'Johannes 6,47', ARRAY['Johannes 6,47']::text[]),
  (169, 'Denn nichts ist verborgen, das nicht offenbar gemacht wird, und nichts geschieht so heimlich, dass es nicht an den Tag kommt.', 'Markus 4,22', ARRAY['Markus 4,22']::text[]),
  (170, 'Gepriesen sei der Herr! Tag für Tag trägt er unsere Last, Gott ist unser Heil!', 'Psalm 68,20', ARRAY['Psalm 68,20', 'Psalm 68,20-21']::text[]),
  (171, 'Unter euch aber soll es nicht so sein, sondern wer unter euch groß werden will, der sei euer Diener, und wer von euch der Erste werden will, der sei aller Knecht.', 'Markus 10,43-44', ARRAY['Markus 10,43-44']::text[]),
  (172, 'Der Beistand aber, der Heilige Geist, den der Vater senden wird in meinem Namen, der wird euch alles lehren und euch an alles erinnern, was ich euch gesagt habe.', 'Johannes 14,26', ARRAY['Johannes 14,26']::text[]),
  (173, 'Sende dein Licht und deine Wahrheit, Dass sie mich leiten,Mich bringen zu deinem heiligen Berg,Und zu deinen Wohnungen,Dass ich komme zum Altar Gottes,Zu dem Gott, der meine Freude und Wonne ist,Und dich preise auf der Laute,O Gott, mein Gott!', 'Psalm 43,3-4', ARRAY['Psalm 43,3-4']::text[]),
  (174, 'Ich habe verkündigt, gerettet und von mir hören lassen und bin nicht fremd unter euch; und ihr seid meine Zeugen, spricht der HERR, dass ich Gott bin.', 'Jesaja 43,12', ARRAY['Jesaja 43,12']::text[]),
  (175, 'Weise mir, HERR, deinen Weg,Damit ich wandle in deiner Wahrheit; Richte mein Herz auf das eine,Dass ich deinen Namen fürchte!', 'Psalm 86,11', ARRAY['Psalm 86,11']::text[]),
  (176, 'Darum, meine geliebten Brüder, sei jeder Mensch schnell zum Hören, langsam zum Reden, langsam zum Zorn.', 'Jakobus 1,19', ARRAY['Jakobus 1,19', 'Jakobus 1,19-20']::text[]),
  (177, 'Du nun erdulde die Widrigkeiten als ein guter Streiter Christi!', '2. Timotheus 2,3', ARRAY['2.Timotheus 2,3']::text[]),
  (178, 'Wie sich ein Vater über Kinder erbarmt, so erbarmt sich der HERR über die, welche ihn fürchten; denn er weiß, was für ein Gebilde wir sind; er denkt daran, dass wir Staub sind.', 'Psalm 103,13-14', ARRAY['Psalm 103,13-14']::text[]),
  (179, 'Glückselig seid ihr, wenn sie euch schmähen und verfolgen und lügnerisch jegliches böse Wort gegen euch reden um meinetwillen!', 'Matthäus 5,11', ARRAY['Matthäus 5,11']::text[]),
  (180, 'Verweigere keine Wohltat dem, welchem sie zukommt, wenn es in der Macht deiner Hände liegt, sie zu erweisen!', 'Sprüche 3,27', ARRAY['Sprüche 3,27']::text[]),
  (181, 'So gibt es jetzt keine Verdammnis mehr für die, welche in Christus Jesus sind, die nicht gemäß dem Fleisch wandeln, sondern gemäß dem Geist.', 'Römer 8,1', ARRAY['Römer 8,1']::text[]),
  (182, 'Himmel und Erde werden vergehen, aber meine Worte werden nicht vergehen.', 'Matthäus 24,35', ARRAY['Lukas 21,33', 'Matthäus 24,35']::text[]),
  (183, 'Christus hat uns losgekauft von dem Fluch des Gesetzes, indem er ein Fluch wurde um unsertwillen (denn es steht geschrieben: »Verflucht ist jeder, der am Holz hängt«).', 'Galater 3,13', ARRAY['Galater 3,13']::text[]),
  (184, 'Und sie blieben beständig in der Lehre der Apostel und in der Gemeinschaft und im Brotbrechen und in den Gebeten.', 'Apostelgeschichte 2,42', ARRAY['Apostelgeschichte 2,42']::text[]),
  (185, 'Und er sprach zu ihnen: Was schlaft ihr? Steht auf und betet, damit ihr nicht in Anfechtung geratet!', 'Lukas 22,46', ARRAY['Lukas 22,46']::text[]),
  (186, 'Der Herr ist meine Stärke und mein Schild; auf ihn hat mein Herz vertraut, und mir wurde geholfen. Darum frohlockt mein Herz, und ich will ihm danken mit meinem Lied.', 'Psalm 28,7', ARRAY['Psalm 28,7', 'Psalmen 28:7']::text[]),
  (187, 'Und nun, Israel, was fordert der Herr, dein Gott, von dir, als nur, dass du den Herrn, deinen Gott, fürchtest, dass du in allen seinen Wegen wandelst und ihn liebst und dem Herrn, deinem Gott, dienst mit deinem ganzen Herzen und deiner ganzen Seele.', '5. Mose 10,12', ARRAY['5. Mose 10,12', '5.Mose 10,12']::text[]),
  (188, 'Lass dich nicht vom Bösen überwinden, sondern überwinde das Böse durch das Gute!', 'Römer 12,21', ARRAY['Römer 12,21']::text[]),
  (189, 'Über dies alles aber zieht die Liebe an, die das Band der Vollkommenheit ist.', 'Kolosser 3,14', ARRAY['Kolosser 3,14']::text[]),
  (190, 'Denn die Wege eines jeden liegen klar vor den Augen des HERRN, und Er achtet auf alle seine Pfade!', 'Sprüche 5,21', ARRAY['Sprüche 5,21']::text[]),
  (191, 'Dafür, dass ich sie liebe, sind sie mir feind; ich aber bete.', 'Psalm 109,4', ARRAY['Psalm 109,4']::text[]),
  (192, 'Meine Kinder, lasst uns nicht mit Worten lieben noch mit der Zunge, sondern in Tat und Wahrheit!', '1. Johannes 3,18', ARRAY['1. Johannes 3,18', '1.Johannes 3,18']::text[]),
  (193, 'Ihr seid das Salz der Erde. Wenn aber das Salz fade wird, womit soll es wieder salzig gemacht werden? Es taugt zu nichts mehr, als dass es hinausgeworfen und von den Leuten zertreten wird.', 'Matthäus 5,13', ARRAY['Matthäus 5,13']::text[]),
  (194, 'Verwundert euch nicht darüber! Denn es kommt die Stunde, in der alle, die in den Gräbern sind, seine Stimme hören werden, und sie werden hervorgehen: die das Gute getan haben, zur Auferstehung des Lebens; die aber das Böse getan haben, zur Auferstehung des Gerichts.', 'Johannes 5,28-29', ARRAY['Johannes 5,28-29']::text[]),
  (195, 'Liebt ihr mich, so haltet meine Gebote!', 'Johannes 14,15', ARRAY['Johannes 14,15']::text[]),
  (196, 'In ihm haben wir die Erlösung durch sein Blut, die Vergebung der Übertretungen nach dem Reichtum seiner Gnade,', 'Epheser 1,7', ARRAY['Epheser 1,7', 'Epheserbrief 1:7']::text[]),
  (197, 'Ihr aber, Geliebte, erbaut euch auf euren allerheiligsten Glauben und betet im Heiligen Geist!', 'Judas 20', ARRAY['Judas 20']::text[]),
  (198, 'Darum, Brüder, seid um so eifriger bestrebt, eure Berufung und Auserwählung fest zu machen; denn wenn ihr diese Dinge tut, werdet ihr niemals zu Fall kommen; denn auf diese Weise wird euch der Eingang in das ewige Reich unseres Herrn und Retters Jesus Christus reichlich gewährt werden.', '2. Petrus 1,10-11', ARRAY['2. Petrus 1,10-11', '2.Petrus 1,10-11']::text[]),
  (199, 'Ich gedenke an die längst vergangenen Tage,Rufe mir alle deine Taten in ErinnerungUnd sinne nach über die Werke deiner Hände.', 'Psalm 143,5', ARRAY['Psalm 143,5']::text[]);
INSERT INTO _pool_seed (idx, verse, reference, raw_refs) VALUES
  (200, 'Die Summe deines Wortes ist Wahrheit, Und jede Bestimmung deiner Gerechtigkeit bleibt ewiglich.', 'Psalm 119,160', ARRAY['Psalm 119,160']::text[]),
  (201, 'So bringt nun Früchte, die der Buße würdig sind! Und fangt nicht an, bei euch selbst zu sagen: Wir haben Abraham zum Vater! Denn ich sage euch: Gott vermag dem Abraham aus diesen Steinen Kinder zu erwecken.', 'Lukas 3,8', ARRAY['Lukas 3,8']::text[]),
  (202, 'So steht nun fest in der Freiheit, zu der uns Christus befreit hat, und lasst euch nicht wieder in ein Joch der Knechtschaft spannen!', 'Galater 5,1', ARRAY['Galater 5,1']::text[]),
  (203, 'Bedenke doch, dass mein Leben nur ein Hauch ist, dass mein Auge nichts Gutes mehr sehen wird!', 'Hiob 7,7', ARRAY['Hiob 7,7']::text[]),
  (204, 'Wer weinend hingehtUnd den Samen zur Aussaat trägt, Der kommt gewiss mit Freuden zurückUnd bringt seine Garben.', 'Psalm 126,6', ARRAY['Psalm 126,6']::text[]),
  (205, 'Und lasst uns aufeinander achtgeben, damit wir uns gegenseitig anspornen zur Liebe und zu guten Werken.', 'Hebräer 10,24', ARRAY['Hebräer 10, 24-25', 'Hebräer 10,24']::text[]),
  (206, 'Ihr seid das Licht der Welt. Es kann eine Stadt, die auf einem Berg liegt, nicht verborgen bleiben.', 'Matthäus 5,14', ARRAY['Matthäus 5,14']::text[]),
  (207, 'Wenn ihr aber von Kriegen und Kriegsgeschrei hören werdet, so erschreckt nicht; denn es muss geschehen, aber es ist noch nicht das Ende.', 'Markus 13,7', ARRAY['Markus 13,7']::text[]),
  (208, 'Denn mit dem Herzen glaubt man, um gerecht zu werden, und mit dem Mund bekennt man, um gerettet zu werden; denn die Schrift spricht: »Jeder, der an ihn glaubt, wird nicht zuschanden werden!«', 'Römer 10,10-11', ARRAY['Römer 10,10-11', 'Römer 10,9', 'Römer 10,9-10']::text[]),
  (209, 'So ermahne ich euch nun, ich, der Gebundene im Herrn, dass ihr der Berufung würdig wandelt, zu der ihr berufen worden seid.', 'Epheser 4,1', ARRAY['Epheser 4,1']::text[]),
  (210, 'Darum nehmt einander an, gleichwie auch Christus uns angenommen hat, zur Ehre Gottes!', 'Römer 15,7', ARRAY['Römer 15,7']::text[]),
  (211, 'Habe acht auf dich selbst und auf die Lehre; bleibe beständig dabei! Denn wenn du dies tust, wirst du sowohl dich selbst retten als auch die, welche auf dich hören.', '1. Timotheus 4,16', ARRAY['1.Timotheus 4,16']::text[]),
  (212, 'Was der Gottlose fürchtet, das wird über ihn kommen,Den Wunsch der Gerechten aber wird Er erfüllen.', 'Sprüche 10,24', ARRAY['Sprüche 10,24']::text[]),
  (213, 'Und ich bin noch heute so stark, wie ich war an dem Tag, als mich Mose aussandte; wie meine Kraft damals war, so ist sie auch jetzt, zu kämpfen und aus- und einzuziehen.', 'Josua 14,11', ARRAY['Josua 14,11']::text[]),
  (214, 'Wer im Geringsten treu ist, der ist auch im Großen treu; und wer im Geringsten ungerecht ist, der ist auch im Großen ungerecht.', 'Lukas 16,10', ARRAY['Lukas 16,10']::text[]),
  (215, 'So werft nun eure Zuversicht nicht weg, die eine große Belohnung hat!', 'Hebräer 10,35', ARRAY['Hebräer 10,35']::text[]),
  (216, 'Glückselig ist der Mann, der die Anfechtung erduldet; denn nachdem er sich bewährt hat, wird er die Krone des Lebens empfangen, welche der Herr denen verheißen hat, die ihn lieben.', 'Jakobus 1,12', ARRAY['Jakobus 1,12']::text[]),
  (217, 'Gegen eine kleine Stadt, in der wenige Männer waren, kam ein großer König und belagerte sie und baute große Belagerungstürme gegen sie. Da fand sich in derselben Stadt ein armer, aber weiser Mann, der rettete die Stadt durch seine Weisheit, und doch gedachte kein Mensch an diesen armen Mann.', 'Prediger 9,14-15', ARRAY['Prediger 9,14-15']::text[]),
  (218, 'Denn wir sind seine Schöpfung, erschaffen in Christus Jesus zu guten Werken, die Gott zuvor bereitet hat, damit wir in ihnen wandeln sollen.', 'Epheser 2,10', ARRAY['Epheser 2,10']::text[]),
  (219, 'Ich aber sage euch: Liebt eure Feinde, segnet, die euch fluchen, tut wohl denen, die euch hassen, und bittet für die, welche euch beleidigen und verfolgen.', 'Matthäus 5,44', ARRAY['Matthäus 5,44']::text[]),
  (220, 'Und die Menschen wurden versengt von großer Hitze, und sie lästerten den Namen Gottes, der Macht hat über diese Plagen, und sie taten nicht Buße, um ihm die Ehre zu geben.', 'Offenbarung 16,9', ARRAY['Offenbarung 16,9']::text[]),
  (221, 'O Gott, dein Weg ist heilig! Wer ist ein so großer Gott wie du, o Gott? Du bist der Gott, der Wunder tut; du hast deine Macht erwiesen an den Völkern!', 'Psalm 77,14-15', ARRAY['Psalm 77,14-15', 'Psalm 77,15']::text[]),
  (222, 'Habt acht, dass euch niemand beraubt durch die Philosophie und leeren Betrug, gemäß der Überlieferung der Menschen, gemäß den Grundsätzen der Welt und nicht Christus gemäß.', 'Kolosser 2,8', ARRAY['Kolosser 2,8']::text[]),
  (223, 'Ein Mensch, der das Blut einer Seele auf dem Gewissen hat,Muss bis zum Grab flüchtig sein; niemand soll ihm helfen!', 'Sprüche 28,17', ARRAY['Sprüche 28,17']::text[]),
  (224, 'Menschenfurcht ist ein Fallstrick; wer aber auf den Herrn vertraut, der ist geborgen.', 'Sprüche 29,25', ARRAY['Sprüche 29,25']::text[]),
  (225, 'Und es geschah, als ich diese Worte hörte, da setzte ich mich hin und weinte und trug Leid etliche Tage lang; und ich fastete und betete vor dem Gott des Himmels.', 'Nehemia 1,4', ARRAY['Nehemia 1,4']::text[]),
  (226, 'Wirkt nicht für die Speise, die vergänglich ist, sondern für die Speise, die bis ins ewige Leben bleibt, die der Sohn des Menschen euch geben wird; denn diesen hat Gott, der Vater, bestätigt!', 'Johannes 6,27', ARRAY['Johannes 6,27']::text[]),
  (227, 'Denn so spricht der Hohe und Erhabene, der ewig wohnt und dessen Name »Der Heilige« ist: In der Höhe und im Heiligtum wohne ich und bei dem, der zerschlagenen und gedemütigten Geistes ist, damit ich den Geist der Gedemütigten belebe und das Herz der Zerschlagenen erquicke.', 'Jesaja 57,15', ARRAY['Jesaja 57,15', 'Jesaja 57:15']::text[]),
  (228, 'Und passt euch nicht diesem Weltlauf an, sondern lasst euch in eurem Wesen verwandeln durch die Erneuerung eures Sinnes, damit ihr prüfen könnt, was der gute und wohlgefällige und vollkommene Wille Gottes ist.', 'Römer 12,2', ARRAY['Römer 12,2', 'Römerbrief 12:2']::text[]),
  (229, 'Meine Augen sind stets auf den HERRN gerichtet,Denn er wird meine Füße aus dem Netz ziehen.', 'Psalm 25,15', ARRAY['Psalm 25,15']::text[]),
  (230, 'Und Petrus ging hinaus und weinte bitterlich.', 'Lukas 22,62', ARRAY['Lukas 22,62']::text[]),
  (231, 'Da bildete Gott der HERR den Menschen, Staub von der Erde, und blies den Odem des Lebens in seine Nase, und so wurde der Mensch eine lebendige Seele.', '1. Mose 2,7', ARRAY['1.Mose 2,7']::text[]),
  (232, 'Alle Schrift ist von Gott eingegeben und nützlich zur Belehrung, zur Überführung, zur Zurechtweisung, zur Erziehung in der Gerechtigkeit.', '2. Timotheus 3,16', ARRAY['2.Timotheus 3,16']::text[]),
  (233, 'Nehmt den Schwachen im Glauben an, ohne über Gewissensfragen zu streiten.', 'Römer 14,1', ARRAY['Römer 14,1']::text[]),
  (234, 'Ich vermag alles durch den, der mich stark macht, Christus.', 'Philipper 4,13', ARRAY['Philipper 4,13']::text[]),
  (235, 'Lasst uns nicht nach leerem Ruhm streben, einander nicht herausfordern noch einander beneiden!', 'Galater 5,26', ARRAY['Galater 5,26']::text[]),
  (236, 'Harre auf den HERRN! Sei stark, und dein Herz fasse Mut,Und harre auf den HERRN!', 'Psalm 27,14', ARRAY['Psalm 27,14']::text[]),
  (237, 'Aber ich habe gegen dich, dass du deine erste Liebe verlassen hast. Bedenke nun, wovon du gefallen bist, und tue Buße und tue die ersten Werke! Sonst komme ich rasch über dich und werde deinen Leuchter von seiner Stelle wegstoßen, wenn du nicht Buße tust!', 'Offenbarung 2,4-5', ARRAY['Offenbarung 2,4', 'Offenbarung 2,4-5']::text[]),
  (238, 'Im übrigen, ihr Brüder, alles, was wahrhaftig, was ehrbar, was gerecht, was rein, was liebenswert, was wohllautend, was irgend eine Tugend oder etwas Lobenswertes ist, darauf seid bedacht!', 'Philipper 4,8', ARRAY['Philipper 4,8']::text[]),
  (239, 'Und ich will euch ein Vater sein, und ihr sollt mir Söhne und Töchter sein, spricht der Herr, der Allmächtige.', '2. Korinther 6,18', ARRAY['2.Korinther 6,18']::text[]),
  (240, 'Da hob mich der Geist empor, und ich hörte hinter mir eine Stimme, ein gewaltiges Getöse: Gepriesen sei die Herrlichkeit des HERRN von seiner Wohnstätte her!', 'Hesekiel 3,12', ARRAY['Hesekiel 3,12']::text[]),
  (241, 'Richtet nicht, damit ihr nicht gerichtet werdet!', 'Matthäus 7,1', ARRAY['Matthäus 7,1', 'Matthäus 7,1-2', 'Matthäus 7,2', 'Matthäus 7:1']::text[]),
  (242, 'Wer freigiebig ist, der wird gesegnet, Denn er gibt dem Armen von seinem Brot.', 'Sprüche 22,9', ARRAY['Sprüche 22,9']::text[]),
  (243, 'Aber auf das alles nehme ich keine Rücksicht; mein Leben ist mir auch selbst nicht teuer, wenn es gilt, meinen Lauf mit Freuden zu vollenden und den Dienst, den ich von dem Herrn Jesus empfangen habe, nämlich das Evangelium der Gnade Gottes zu bezeugen.', 'Apostelgeschichte 20,24', ARRAY['Apostelgeschichte 20,24']::text[]),
  (244, 'Jetzt aber, in Christus Jesus, seid ihr, die ihr einst fern wart, nahe gebracht worden durch das Blut des Christus.', 'Epheser 2,13', ARRAY['Epheser 2,13']::text[]),
  (245, 'Denn das Wort Gottes ist lebendig und wirksam und schärfer als jedes zweischneidige Schwert, und es dringt durch, bis es scheidet sowohl Seele als auch Geist, sowohl Mark als auch Bein, und es ist ein Richter der Gedanken und Gesinnungen des Herzens.', 'Hebräer 4,12', ARRAY['Hebräer 4,12']::text[]),
  (246, 'Und dass ihr sie umso mehr in Liebe achtet um ihres Werkes Willen. Lebt in Frieden miteinander!', '1. Thessalonicher 5,13', ARRAY['1.Thessalonicher 5,13']::text[]),
  (247, 'Denn das Wort vom Kreuz ist eine Torheit denen, die verlorengehen; uns aber, die wir gerettet werden, ist es eine Gotteskraft;', '1. Korinther 1,18', ARRAY['1. Korinther 1,18', '1. Korinther 1:18', '1.Korinther 1,18']::text[]),
  (248, 'Das in dem guten Erdreich aber sind die, welche das Wort, das sie gehört haben, in einem feinen und guten Herzen behalten und Frucht bringen in standhaftem Ausharren.', 'Lukas 8,15', ARRAY['Lukas 8,15']::text[]),
  (249, 'Zu jener Zeit begann Jesus und sprach: Ich preise dich, Vater, Herr des Himmels und der Erde, dass du dies vor den Weisen und Klugen verborgen und es den Unmündigen geoffenbart hast!', 'Matthäus 11,25', ARRAY['Matthäus 11,25']::text[]),
  (250, 'O Gott, du bist mein Gott; früh suche ich dich! Meine Seele dürstet nach dir; Mein Fleisch schmachtet nach dir In einem dürren, lechzenden Land ohne Wasser, Dass ich deine Macht und Herrlichkeit sehen darf, Gleichwie ich dich schaute im Heiligtum.', 'Psalm 63,2-3', ARRAY['Psalm 63,2-3']::text[]),
  (251, 'Wacht, steht fest im Glauben, seid mannhaft, seid stark! Lasst alles bei euch in Liebe geschehen!.', '1. Korinther 16,13-14', ARRAY['1. Korinther 16,13-14', '1.Korinther 16,13']::text[]),
  (252, 'Doch dir, o Herr, ist niemand gleich! Groß bist du, und groß ist dein Name an Macht! Wer sollte dich nicht fürchten, du König der Völker? Denn dir gebührt dies; unter allen Weisen der Völker und in allen ihren Königreichen ist ja keiner wie du!', 'Jeremia 10,6-7', ARRAY['Jeremia 10,6', 'Jeremia 10,6-7']::text[]),
  (253, 'Unser Bürgerrecht aber ist im Himmel, von woher wir auch den Herrn Jesus Christus erwarten als den Retter.', 'Philipper 3,20', ARRAY['Philipper 3,20', 'Philipper 3,20-21']::text[]),
  (254, 'Und siehe, ich komme bald und mein Lohn mit mir, um einem jeden so zu vergelten, wie sein Werk sein wird.', 'Offenbarung 22,12', ARRAY['Offenbarung 22,12']::text[]),
  (255, 'Denn ich wusste, dass du ein gnädiger und barmherziger Gott bist, langmütig und von großer Gnade, und das Unheil reut dich!', 'Jona 4,2', ARRAY['Jona 4,2b']::text[]),
  (256, 'Trachtet vielmehr zuerst nach dem Reich Gottes und nach seiner Gerechtigkeit, so wird euch dies alles hinzugefügt werden!', 'Matthäus 6,33', ARRAY['Matthäus 6,33', 'Matthäus 6:33']::text[]),
  (257, 'Jesus Christus ist derselbe gestern und heute und auch in Ewigkeit!', 'Hebräer 13,8', ARRAY['Hebräer 13,8']::text[]),
  (258, 'Er aber wandte sich um und sprach zu Petrus: Weiche von mir, Satan! Du bist mir ein Ärgernis; denn du denkst nicht göttlich, sondern menschlich!', 'Matthäus 16,23', ARRAY['Matthäus 16,23']::text[]),
  (259, 'Jagt nach dem Frieden mit jedermann und der Heiligung, ohne die niemand den Herrn sehen wird!', 'Hebräer 12,14', ARRAY['Hebräer 12,14']::text[]),
  (260, 'Er wird den Tod auf ewig verschlingen. Und GOTT, der Herr, wird die Tränen abwischen von jedem Angesicht und die Schmach seines Volkes hinwegnehmen von der ganzen Erde. Ja, der HERR hat es gesprochen.', 'Jesaja 25,8', ARRAY['Jesaja 25,8']::text[]),
  (261, 'Uns aber, HERR, wirst du Frieden schaffen; denn auch alle unsere Werke hast du für uns vollbracht.', 'Jesaja 26,12', ARRAY['Jesaja 26,12']::text[]),
  (262, 'Nun aber bleiben Glaube, Hoffnung, Liebe, diese drei; die größte aber von diesen ist die Liebe.', '1. Korinther 13,13', ARRAY['1.Korinther 13,13']::text[]),
  (263, 'So wartet auch ihr geduldig; stärkt eure Herzen, denn die Wiederkunft des Herrn ist nahe!', 'Jakobus 5,8', ARRAY['Jakobus 5,8']::text[]),
  (264, 'Ich will dem Dürstenden geben aus dem Quell des Wassers des Lebens umsonst!', 'Offenbarung 21,6', ARRAY['Offenbarung 21,6b']::text[]),
  (265, 'Lasst euch nicht so schnell in eurem Verständnis erschüttern oder gar in Schrecken jagen, weder durch einen Geist noch durch ein Wort noch durch einen angeblich von uns stammenden Brief, als wäre der Tag des Christus schon da.', '2. Thessalonicher 2,2', ARRAY['2.Thessalonicher 2,2']::text[]),
  (266, 'Sodass sie ohne Verdienst gerechtfertigt werden durch seine Gnade aufgrund der Erlösung, die in Christus Jesus ist.', 'Römer 3,24', ARRAY['Römer 3,24']::text[]),
  (267, 'Da er die Schmach des Christus für größeren Reichtum hielt als die Schätze, die in Ägypten waren; denn er sah die Belohnung an.', 'Hebräer 11,26', ARRAY['Hebräer 11,26']::text[]),
  (268, 'Darum, so spricht GOTT, der Herr: Siehe, ich lege in Zion einen Stein, einen bewährten Stein, einen kostbaren Eckstein, der aufs Festeste gegründet ist: Wer glaubt, der flieht nicht!', 'Jesaja 28,16', ARRAY['Jesaja 28,16']::text[]),
  (269, 'Denn ich sage kraft der Gnade, die mir gegeben ist, jedem unter euch, dass er nicht höher von sich denke, als sich zu denken gebührt, sondern dass er auf Bescheidenheit bedacht sei, wie Gott jedem Einzelnen das Maß des Glaubens zugeteilt hat.', 'Römer 12,3', ARRAY['Römer 12,3']::text[]),
  (270, 'Denn aus Gnade seid ihr errettet durch den Glauben, und das nicht aus euch — Gottes Gabe ist es;', 'Epheser 2,8', ARRAY['Epheser 2,8', 'Epheser 2,8-9', 'Epheserbrief 2:8']::text[]),
  (271, 'Ringt danach, durch die enge Pforte hineinzugehen! Denn viele, sage ich euch, werden hineinzugehen suchen und es nicht können.', 'Lukas 13,24', ARRAY['Lukas 13,24']::text[]),
  (272, 'Wer Unrecht tut, der tue weiter Unrecht, und wer unrein ist, der verunreinige sich weiter, und der Gerechte übe weiter Gerechtigkeit, und der Heilige heilige sich weiter!', 'Offenbarung 22,11', ARRAY['Offenbarung 22,11']::text[]),
  (273, 'Und das Wort wurde Fleisch und wohnte unter uns; und wir sahen seine Herrlichkeit, eine Herrlichkeit als des Eingeborenen vom Vater, voller Gnade und Wahrheit.', 'Johannes 1,14', ARRAY['Johannes 1,14']::text[]),
  (274, 'Ist mein Wort nicht wie ein Feuer, spricht der HERR, und wie ein Hammer, der Felsen zerschmettert?', 'Jeremia 23,29', ARRAY['Jeremia 23,29']::text[]),
  (275, 'Und ich will euch ein neues Herz geben und einen neuen Geist in euer Inneres legen; ich will das steinerne Herz aus eurem Fleisch wegnehmen und euch ein fleischernes Herz geben.', 'Hesekiel 36,26', ARRAY['Hesekiel 36,26']::text[]),
  (276, 'Lobe den Herrn, meine Seele, und vergiss nicht, was er dir Gutes getan hat!', 'Psalm 103,2', ARRAY['Psalm 103,2']::text[]),
  (277, 'Er aber sprach: Glückselig sind vielmehr die, die Gottes Wort hören und es bewahren!', 'Lukas 11,28', ARRAY['Lukas 11,28']::text[]),
  (278, 'Da antwortete Jesus und sprach zu ihnen: Wahrlich, wahrlich, ich sage euch: Der Sohn kann nichts von sich selbst aus tun, sondern nur, was er den Vater tun sieht; denn was dieser tut, das tut gleicherweise auch der Sohn.', 'Johannes 5,19', ARRAY['Johannes 5,19']::text[]),
  (279, 'Mehr als alles andere behüte dein Herz; denn von ihm geht das Leben aus.', 'Sprüche 4,23', ARRAY['Sprüche 4,23']::text[]),
  (280, 'Und mein Volk, über dem mein Name ausgerufen worden ist, demütigt sich, und sie beten und suchen mein Angesicht und kehren um von ihren bösen Wegen, so will ich es vom Himmel her hören und ihre Sünden vergeben und ihr Land heilen.', '2. Chronik 7,14', ARRAY['2.Chronik 7,14']::text[]),
  (281, 'Ich aber will mich freuen in dem Herrn und frohlocken über den Gott meines Heils!', 'Habakuk 3,18', ARRAY['Habakuk 3,18', 'Habakuk 3,18-19']::text[]),
  (282, 'Und nun, Kinder, bleibt in ihm, damit wir Freimütigkeit haben, wenn er erscheint, und uns nicht schämen müssen vor ihm bei seiner Wiederkunft.', '1. Johannes 2,28', ARRAY['1. Johannes 2,28', '1.Johannes 2,28']::text[]),
  (283, 'Weil wir nun diese Verheißungen haben, Geliebte, so wollen wir uns reinigen von aller Befleckung des Fleisches und des Geistes zur Vollendung der Heiligkeit in Gottesfurcht!', '2. Korinther 7,1', ARRAY['2.Korinther 7,1']::text[]),
  (284, 'Freut euch im Herrn allezeit; abermals sage ich: Freut euch!', 'Philipper 4,4', ARRAY['Philipper 4,4']::text[]),
  (285, 'Und meine Zunge soll reden von deiner Gerechtigkeit, Von deinem Lob allezeit!', 'Psalm 35,28', ARRAY['Psalm 35,28']::text[]),
  (286, 'Und der Friede Gottes, der allen Verstand übersteigt, wird eure Herzen und eure Gedanken bewahren in Christus Jesus!', 'Philipper 4,7', ARRAY['Philipper 4,7']::text[]),
  (287, 'Was betrübst du dich, meine Seele, Und bist so unruhig in mir? Harre auf Gott, denn ich werde ihm noch danken Für die Rettung, die von seinem Angesicht kommt!', 'Psalm 42,6', ARRAY['Psalm 42,6']::text[]),
  (288, 'Darum, meine geliebten Brüder, seid fest, unerschütterlich, nehmt immer zu in dem Werk des Herrn, weil ihr wisst, dass eure Arbeit nicht vergeblich ist im Herrn!', '1. Korinther 15,58', ARRAY['1. Korinther 15,58', '1.Korinther 15,58']::text[]),
  (289, 'Wie köstlich ist deine Gnade, o Gott, Dass Menschenkinder Zuflucht finden unter dem Schatten deiner Flügel!', 'Psalm 36,8', ARRAY['Psalm 36,8']::text[]),
  (290, 'Alles nun, was ihr wollt, dass die Leute euch tun sollen, das tut auch ihr ihnen ebenso; denn dies ist das Gesetz und die Propheten.', 'Matthäus 7,12', ARRAY['Matthäus 7,12', 'Matthäus 7:12']::text[]),
  (291, 'Denn ich weiß, was für Gedanken ich über euch habe, spricht der Herr, Gedanken des Friedens und nicht des Unheils, um euch eine Zukunft und eine Hoffnung zu geben.', 'Jeremia 29,11', ARRAY['Jeremia 29,11']::text[]),
  (292, 'Denn bei Gott ist kein Ding unmöglich.', 'Lukas 1,37', ARRAY['Lukas 1,37']::text[]),
  (293, 'Setze dir Wegweiser, stelle dir Meilensteine auf; richte dein Herz auf die gebahnte Straße, auf den Weg, den du gegangen bist! Kehre um, Jungfrau Israel, kehre um zu diesen deinen Städten!', 'Jeremia 31,21', ARRAY['Jeremia 31,21']::text[]),
  (294, 'Und einer von den Ältesten spricht zu mir: Weine nicht! Siehe, es hat überwunden der Löwe, der aus dem Stamm Juda ist, die Wurzel Davids, um das Buch zu öffnen und seine sieben Siegel zu brechen!', 'Offenbarung 5,5', ARRAY['Offenbarung 5,5']::text[]),
  (295, 'Dass aber der Pharao den Traum zweimal hatte, das bedeutet, dass die Sache bei Gott fest beschlossen ist und dass Gott es rasch ausführen wird.', '1. Mose 41,32', ARRAY['1. Mose 41,32']::text[]),
  (296, 'So lasst uns nun nach dem streben, was zum Frieden und zur gegenseitigen Erbauung dient.', 'Römer 14,19', ARRAY['Römer 14, 19', 'Römer 14,19']::text[]),
  (297, 'Geliebte, wenn Gott uns so geliebt hat, so sind auch wir es schuldig, einander zu lieben.', '1. Johannes 4,11', ARRAY['1. Johannes 4,11']::text[]),
  (298, 'Und der Zöllner stand von ferne, wagte nicht einmal seine Augen zum Himmel zu erheben, sondern schlug an seine Brust und sprach: O Gott, sei mir Sünder gnädig!', 'Lukas 18,13', ARRAY['Lukas 18,13']::text[]),
  (299, 'Der Gott des Ausharrens und des Trostes aber gebe euch, untereinander eines Sinnes zu sein, Christus Jesus gemäß.', 'Römer 15,5', ARRAY['Römer 15,5']::text[]),
  (300, 'So können wir nun zuversichtlich sagen: »Der Herr ist mein Helfer, und deshalb fürchte ich mich nicht vor dem, was ein Mensch mir antun könnte.«', 'Hebräer 13,6', ARRAY['Hebräer 13,6']::text[]),
  (301, 'Es ist allerdings die Gottesfurcht eine große Bereicherung, wenn sie mit Genügsamkeit verbunden wird.', '1. Timotheus 6,6', ARRAY['1. Timotheus 6,6']::text[]),
  (302, 'Tut nichts aus Selbstsucht oder nichtigem Ehrgeiz, sondern in Demut achte einer den anderen höher als sich selbst.', 'Philipper 2,3', ARRAY['Philipper 2,3']::text[]),
  (303, 'Wer seinen Mund und seine Zunge behütet, Der behütet seine Seele vor mancher Not.', 'Sprüche 21,23', ARRAY['Sprüche 21,23']::text[]),
  (304, 'Fürchte dich nicht, denn ich bin mit dir; sei nicht ängstlich, denn ich bin dein Gott; ich stärke dich, ich helfe dir auch, ja, ich erhalte dich durch die rechte Hand meiner Gerechtigkeit!', 'Jesaja 41,10', ARRAY['Jesaja 41,10']::text[]),
  (305, 'Wir aber, die wir dem Tag angehören, wollen nüchtern sein, angetan mit dem Brustpanzer des Glaubens und der Liebe und mit dem Helm der Hoffnung auf das Heil.', '1. Thessalonicher 5,8', ARRAY['1. Thessalonicher 5,8']::text[]),
  (306, 'Wenn jemand den Herrn Jesus Christus nicht liebt, der sei verflucht! Maranatha!', '1. Korinther 16,22', ARRAY['1. Korinther 16,22']::text[]),
  (307, 'Geliebte, lasst uns einander lieben! Denn die Liebe ist aus Gott, und jeder, der liebt, ist aus Gott geboren und erkennt Gott.', '1. Johannes 4,7', ARRAY['1. Johannes 4,7']::text[]),
  (308, 'Denn das Reich Gottes ist nicht Essen und Trinken, sondern Gerechtigkeit, Friede und Freude im Heiligen Geist!', 'Römer 14,17', ARRAY['Römer 14,17']::text[]),
  (309, 'Und der HERR sprach: Ich will alle meine Güte vor deinem Angesicht vorüberziehen lassen und will den Namen des HERRN vor dir ausrufen. Und wem ich gnädig bin, dem bin ich gnädig, und über wen ich mich erbarme, über den erbarme ich mich.', '2. Mose 33,19', ARRAY['2. Mose 33,19']::text[]),
  (310, 'Denn die Geldgier ist eine Wurzel alles Bösen; etliche, die sich ihr hingegeben haben, sind vom Glauben abgeirrt und haben sich selbst viel Schmerzen verursacht.', '1. Timotheus 6,10', ARRAY['1. Timotheus 6,10']::text[]),
  (311, 'Ich aber will nach dem Herrn ausschauen, will harren auf den Gott meines Heils; mein Gott wird mich erhören.', 'Micha 7,7', ARRAY['Micha 7,7']::text[]),
  (312, 'Gott ist treu, durch den ihr berufen seid zur Gemeinschaft mit seinem Sohn Jesus Christus, unserem Herrn.', '1. Korinther 1,9', ARRAY['1. Korinther 1,9']::text[]),
  (313, 'Siehe, zum Frieden diente mir bitteres Leid; du hast ja meine Seele liebevoll umfangen und sie aus der Grube des Verderbens herausgezogen; denn du hast alle meine Sünden hinter deinen Rücken geworfen!', 'Jesaja 38,17', ARRAY['Jesaja 38,17']::text[]),
  (314, 'Zerreißt eure Herzen und nicht eure Kleider, und kehrt um zu dem HERRN, eurem Gott; denn er ist gnädig und barmherzig, langmütig und von großer Gnade, und das Übel reut ihn.', 'Joel 2,13', ARRAY['Joel 2,12-13', 'Joel 2,13']::text[]),
  (315, 'Aber durch Gottes Gnade bin ich, was ich bin; und seine Gnade, die er an mir erwiesen hat, ist nicht vergeblich gewesen.', '1. Korinther 15,10', ARRAY['1. Korinther 15,10a']::text[]),
  (316, 'Daher kann er auch diejenigen vollkommen erretten, die durch ihn zu Gott kommen, weil er für immer lebt, um für sie einzutreten.', 'Hebräer 7,25', ARRAY['Hebräer 7,25']::text[]),
  (317, 'Wacht und betet, damit ihr nicht in Versuchung kommt! Der Geist ist willig, aber das Fleisch ist schwach.', 'Matthäus 26,41', ARRAY['Markus 14,38', 'Matthäus 26,41']::text[]),
  (318, 'Von nun an liegt für mich die Krone der Gerechtigkeit bereit, die mir der Herr, der gerechte Richter, an jenem Tag zuerkennen wird, nicht aber mir allein, sondern auch allen, die seine Erscheinung liebgewonnen haben.', '2. Timotheus 4,8', ARRAY['2. Timotheus 4,8']::text[]),
  (319, 'Die Liebe sei ungeheuchelt! Hasst das Böse, haltet fest am Guten!', 'Römer 12,9', ARRAY['Römer 12,9']::text[]),
  (320, 'Und doch wisst ihr nicht, was morgen sein wird! Denn was ist euer Leben? Es ist doch nur ein Dunst, der eine kleine Zeit sichtbar ist; danach aber verschwindet er.', 'Jakobus 4,14', ARRAY['Jakobus 4,14']::text[]),
  (321, 'Der Gottlose hat viele Plagen; Wer aber dem HERRN vertraut, Den wird er mit Gnade umgeben.', 'Psalm 32,10', ARRAY['Psalm 32,10']::text[]),
  (322, 'Wer nun Gutes zu tun weiß und es nicht tut, für den ist es Sünde.', 'Jakobus 4,17', ARRAY['Jakobus 4,17']::text[]),
  (323, 'Denn der HERR ist gut; Seine Gnade währt ewiglich Und seine Treue von Geschlecht zu Geschlecht.', 'Psalm 100,5', ARRAY['Psalm 100,5']::text[]),
  (324, 'Das ist es aber, was ihr tun sollt: Redet die Wahrheit, jeder mit seinem Nächsten, übt treulich Recht und fällt einen Rechtsspruch des Friedens in euren Toren; und keiner sinne Böses in seinem Herzen gegen seinen Bruder; liebt auch nicht falschen Eid! Denn dies alles hasse ich, spricht der Herr.', 'Sacharja 8,16-17', ARRAY['Sacharja 8,16-17']::text[]),
  (325, 'Doch nicht darüber freut euch, dass euch die Geister untertan sind; freut euch aber lieber darüber, dass eure Namen im Himmel geschrieben sind.', 'Lukas 10,20', ARRAY['Lukas 10,20']::text[]),
  (326, 'Nun redete Jesus wieder zu ihnen und sprach: Ich bin das Licht der Welt. Wer mir nachfolgt, wird nicht in der Finsternis wandeln, sondern er wird das Licht des Lebens haben.', 'Johannes 8,12', ARRAY['Johannes 8,12']::text[]),
  (327, 'Siehe, wir preisen die glückselig, welche standhaft ausharren! Von Hiobs standhaftem Ausharren habt ihr gehört, und ihr habt das Ende gesehen, das der Herr für ihn bereitet hat; denn der Herr ist voll Mitleid und Erbarmen.', 'Jakobus 5,11', ARRAY['Jakobus 5,11']::text[]),
  (328, 'Denn an Liebe habe ich Wohlgefallen und nicht am Opfer, an der Gotteserkenntnis mehr als an Brandopfern.', 'Hosea 6,6', ARRAY['Hosea 6,6', 'Hosea 6:6']::text[]),
  (329, 'Denn wenn der Dienst der Verdammnis Herrlichkeit hatte, wie viel mehr wird der Dienst der Gerechtigkeit von Herrlichkeit überfließen!', '2. Korinther 3,9', ARRAY['2. Korinther 3,9']::text[]),
  (330, 'Wer sagt, dass er in ihm bleibt, der ist verpflichtet, auch selbst so zu wandeln, wie jener gewandelt ist.', '1. Johannes 2,6', ARRAY['1. Johannes 2,6', '1. Johannes 2:6']::text[]),
  (331, 'Das Volk, das in der Finsternis wandelt, hat ein großes Licht gesehen; über den Bewohnern des Landes der Todesschatten ist ein Licht aufgeleuchtet.', 'Jesaja 9,1', ARRAY['Jesaja 9,1']::text[]),
  (332, 'Er hält für die Aufrichtigen Gelingen bereit Und beschirmt, die in Lauterkeit wandeln.', 'Sprüche 2,7', ARRAY['Sprüche 2,7']::text[]),
  (333, 'Ich will den HERRN loben von ganzem Herzen, Ich will alle deine Wunder erzählen.', 'Psalm 9,2', ARRAY['Psalm 9,2']::text[]),
  (334, 'Denn Gott hat seinen Sohn nicht in die Welt gesandt, damit er die Welt richte, sondern damit die Welt durch ihn gerettet werde.', 'Johannes 3,17', ARRAY['Johannes 3,17']::text[]),
  (335, 'Denn wer ist Gott außer dem HERRN. Und wer ist ein Fels außer unserem Gott? Gott ist es, der mich umgürtet mit Kraft Und meinen Weg unsträflich macht.', 'Psalm 18,32-33', ARRAY['Psalm 18,32-33']::text[]),
  (336, 'Meine Brüder, achtet es für lauter Freude, wenn ihr in mancherlei Anfechtungen geratet, da ihr ja wisst, dass die Bewährung eures Glaubens standhaftes Ausharren bewirkt. Das standhafte Ausharren aber soll ein vollkommenes Werk haben, damit ihr vollkommen und vollständig seid und es euch an nichts mangelt.', 'Jakobus 1,2-4', ARRAY['Jakobus 1,2-4']::text[]),
  (337, 'Und er verkündigte und sprach: Es kommt einer nach mir, der stärker ist als ich, und ich bin nicht würdig, ihm gebückt seinen Schuhriemen zu lösen.', 'Markus 1,7', ARRAY['Markus 1,7']::text[]),
  (338, 'Denn ein Kind ist uns geboren, ein Sohn ist uns gegeben; und die Herrschaft ruht auf seiner Schulter; und man nennt seinen Namen: Wunderbarer, Ratgeber, starker Gott, Ewig-Vater, Friedefürst.', 'Jesaja 9,5', ARRAY['Jesaja 9,5']::text[]),
  (339, 'Aber bei dem Herrn, unserem Gott, ist Barmherzigkeit und Vergebung; denn gegen ihn haben wir uns aufgelehnt.', 'Daniel 9,9', ARRAY['Daniel 9,9']::text[]),
  (340, 'Von ihm aus vollbringt der ganze Leib, zusammengefügt und verbunden durch alle Gelenke, die einander Handreichung tun nach dem Maß der Leistungsfähigkeit jedes einzelnen Gliedes, das Wachstum des Leibes zur Auferbauung seiner selbst in Liebe.', 'Epheser 4,16', ARRAY['Epheser 4,16']::text[]),
  (341, 'Und nun, so spricht der HERR, der dich geschaffen hat, Jakob, und der dich gebildet hat, Israel: Fürchte dich nicht, denn ich habe dich erlöst! Ich habe dich bei deinem Namen gerufen; du bist mein.', 'Jesaja 43,1', ARRAY['Jesaja 43,1']::text[]),
  (342, 'So tut nun Buße und bekehrt euch, dass eure Sünden ausgetilgt werden, damit Zeiten der Erquickung vom Angesicht des Herrn kommen', 'Apostelgeschichte 3,19', ARRAY['Apostelgeschichte 3,19', 'Apostelgeschichte 3:19']::text[]),
  (343, 'Niemand soll vor dir bestehen dein Leben lang! Wie ich mit Mose gewesen bin, so will ich auch mit dir sein; ich will dich nicht aufgeben und dich nicht verlassen.', 'Josua 1,5', ARRAY['Josua 1,5']::text[]),
  (344, 'Böse Gedanken sind dem Herrn ein Gräuel, aber freundliche Reden sind ihm rein.', 'Sprüche 15,26', ARRAY['Sprüche 15,26']::text[]),
  (345, 'Brüder, ich halte mich selbst nicht dafür, dass ich es ergriffen habe; eines aber tue ich: Ich vergesse, was dahinten ist, und strecke mich aus nach dem, was vor mir liegt.', 'Philipper 3,13', ARRAY['Philipper 3,13']::text[]),
  (346, 'Da erbarmte sich Jesus über ihn, streckte die Hand aus, rührte ihn an und sprach zu ihm: Ich will; sei gereinigt!', 'Markus 1,41', ARRAY['Markus 1,41']::text[]),
  (347, 'Sobald aber Jesus das Wort hörte, das sie redeten, sprach er zum Obersten der Synagoge: Fürchte dich nicht, glaube nur!', 'Markus 5,36', ARRAY['Markus 5,36']::text[]),
  (348, 'Dient dem HERRN mit Furcht Und frohlockt mit Zittern.', 'Psalm 2,11', ARRAY['Psalm 2,11']::text[]),
  (349, 'Ich, ich tilge deine Übertretungen um meinetwillen, und an deine Sünden will ich nie mehr gedenken!', 'Jesaja 43,25', ARRAY['Jesaja 43,25']::text[]),
  (350, 'Und er war einer, der dem HERRN glaubte, und das rechnete Er ihm als Gerechtigkeit an.', '1. Mose 15,6', ARRAY['1. Mose 15,6']::text[]),
  (351, 'Siehe, ich wirke Neues, jetzt sprosst es hervor; solltet ihr es nicht wissen? Ich will einen Weg in der Wüste bereiten und Ströme in der Einöde.', 'Jesaja 43,19', ARRAY['Jesaja 43,18-19', 'Jesaja 43,19']::text[]),
  (352, 'Lasst euch nicht von vielfältigen und fremden Lehren umhertreiben; denn es ist gut, dass das Herz fest wird, was durch Gnade geschieht, nicht durch Speisen, von denen die keinen Nutzen hatten, die mit ihnen umgingen.', 'Hebräer 13,9', ARRAY['Hebräer 13,9']::text[]),
  (353, 'Deine Hände haben mich als Ganzes gebildet und rundum gestaltet.', 'Hiob 10,8', ARRAY['Hiob 10,8a']::text[]),
  (354, 'und habe deine Lust am Herrn, so wird er dir geben, was dein Herz begehrt! 5 Befiehl dem Herrn deinen Weg, und vertraue auf ihn, so wird er es vollbringen.', 'Psalm 37,4-5', ARRAY['Psalm 37,4', 'Psalm 37,5', 'Psalmen 37:4-5']::text[]),
  (355, 'Und gedenke an deinen Schöpfer in den Tagen deiner Jugend, ehe die bösen Tage kommen und die Jahre herannahen, von denen du sagen wirst: »Sie gefallen mir nicht«.', 'Prediger 12,1', ARRAY['Prediger 12,1']::text[]),
  (356, 'So sollt auch ihr, wenn ihr alles getan habt, was euch befohlen war, sprechen: Wir sind unnütze Knechte; wir haben getan, was wir zu tun schuldig waren!', 'Lukas 17,10', ARRAY['Lukas 17,10']::text[]),
  (357, 'Und ich suchte unter ihnen einen Mann, der die Mauer zumauern und vor mir in den Riss treten könnte für das Land, damit ich es nicht zugrunde richte; aber ich fand keinen.', 'Hesekiel 22,30', ARRAY['Hesekiel 22,30']::text[]),
  (358, 'Darum, weil wir ein unerschütterliches Reich empfangen, lasst uns die Gnade festhalten, durch die wir Gott auf wohlgefällige Weise dienen können mit Scheu und Ehrfurcht!', 'Hebräer 12,28', ARRAY['Hebräer 12,28']::text[]),
  (359, 'Wir wissen aber, dass denen, die Gott lieben, alle Dinge zum Besten dienen, denen, die nach dem Vorsatz berufen sind.', 'Römer 8,28', ARRAY['Römer 8,28', 'Römerbrief 8:28']::text[]),
  (360, 'Ich freue mich über dein Wort Wie einer, der große Beute findet.', 'Psalm 119,162', ARRAY['Psalm 119,162']::text[]),
  (361, 'Darum umgürtet die Lenden eurer Gesinnung, seid nüchtern und setzt eure Hoffnung ganz auf die Gnade, die euch zuteil wird in der Offenbarung Jesu Christi.', '1. Petrus 1,13', ARRAY['1. Petrus 1,13']::text[]),
  (362, 'Denn nichts ist verborgen, das nicht offenbar werden wird, und nichts ist geheim, das nicht bekannt werden und an den Tag kommen wird.', 'Lukas 8,17', ARRAY['Lukas 8,17']::text[]),
  (363, 'Wascht, reinigt euch! Tut das Böse, das ihr getan habt, von meinen Augen hinweg; hört auf, Böses zu tun!', 'Jesaja 1,16', ARRAY['Jesaja 1,16']::text[]),
  (364, 'Gott aber, wird er nicht seinen Auserwählten Recht schaffen, die Tag und Nacht zu ihm rufen, wenn er auch lange zuwartet mit ihnen?', 'Lukas 18,7', ARRAY['Lukas 18,7']::text[]),
  (365, 'Denn Gott wird jedes Werk vor ein Gericht bringen, samt allem Verborgenen, es sei gut oder böse.', 'Prediger 12,14', ARRAY['Prediger 12,14']::text[]),
  (366, 'Und wer seine Gebote hält, der bleibt in Ihm und Er in ihm; und daran erkennen wir, dass Er in uns bleibt: an dem Geist, den Er uns gegeben hat.', '1. Johannes 3,24', ARRAY['1. Johannes 3,24']::text[]),
  (367, 'Du hast unsere Missetaten vor dich hingestellt, Unser geheimstes Tun in das Licht deines Angesichts.', 'Psalm 90,8', ARRAY['Psalm 90,8']::text[]),
  (368, 'Euch aber, die ihr meinen Namen fürchtet, wird die Sonne der Gerechtigkeit aufgehen, und Heilung wird unter ihren Flügeln sein; und ihr werdet herauskommen und hüpfen wie Kälber aus dem Stall!', 'Maleachi 3,20', ARRAY['Maleachi 3,20']::text[]),
  (369, 'Er hat uns vorherbestimmt zur Sohnschaft für sich selbst durch Jesus Christus, nach dem Wohlgefallen seines Willens, zum Lob der Herrlichkeit seiner Gnade, mit der er uns begnadigt hat in dem Geliebten.', 'Epheser 1,5-6', ARRAY['Epheser 1,5-6']::text[]),
  (370, 'Denn der Arme wird nicht aus dem Land verschwinden; darum gebiete ich dir: Tue deine Hand weit auf für deinen Bruder, für den Elenden und den Armen bei dir in deinem Land!', '5. Mose 15,11', ARRAY['5. Mose 15,11']::text[]),
  (371, 'Du hast mein Herz geprüft, mich in der Nacht durchforscht; du hast mich geläutert, und du hast nichts gefunden, worin ich mich vergangen hätte mit meinen Gedanken oder mit meinem Mund.', 'Psalm 17,3', ARRAY['Psalm 17,3']::text[]),
  (372, 'Dies ist der Tag, den der HERR gemacht hat; wir wollen uns freuen und fröhlich sein in ihm!', 'Psalm 118,24', ARRAY['Psalm 118,24']::text[]),
  (373, 'Du leitest in deiner Gnade das Volk, das du erlöst hast; durch deine Kraft bringst du sie zu der Wohnung deines Heiligtums.', '2. Mose 15,13', ARRAY['2. Mose 15,13']::text[]),
  (374, 'Denn wo zwei oder drei in meinem Namen versammelt sind, da bin ich in ihrer Mitte.', 'Matthäus 18,20', ARRAY['Matthäus 18,20']::text[]),
  (375, 'Denn du sollst keinen anderen Gott anbeten. Denn der HERR, dessen Name »Der Eifersüchtige« ist, ist ein eifersüchtiger Gott.', '2. Mose 34,14', ARRAY['2. Mose 34,14']::text[]),
  (376, 'Siehe, die Hand des Herrn ist nicht zu kurz zum Retten und sein Ohr nicht zu schwer zum Hören.', 'Jesaja 59,1', ARRAY['Jesaja 59,1']::text[]),
  (377, 'Der Herr aber ist der Geist; und wo der Geist des Herrn ist, da ist Freiheit.', '2. Korinther 3,17', ARRAY['2. Korinther 3,17', '2.Korinther 3,17']::text[]),
  (378, 'Wegen dieser Errettung haben die Propheten gesucht und nachgeforscht, die von der euch zuteil gewordenen Gnade geweissagt haben.', '1. Petrus 1,10', ARRAY['1. Petrus 1,10']::text[]),
  (379, 'Der Gott aller Gnade aber, der uns berufen hat zu seiner ewigen Herrlichkeit in Christus Jesus, er selbst möge euch, nachdem ihr eine kurze Zeit gelitten habt, völlig zubereiten, festigen, stärken, gründen!', '1. Petrus 5,10', ARRAY['1. Petrus 5,10']::text[]),
  (380, 'O welche Tiefe des Reichtums sowohl der Weisheit als auch der Erkenntnis Gottes! Wie unergründlich sind seine Gerichte, und wie unausforschlich seine Wege!', 'Römer 11,33', ARRAY['Römer 11,33']::text[]),
  (381, 'Der HERR behüte dich vor allem Übel, er behüte deine Seele; der HERR behüte deinen Ausgang und Eingang von nun an bis in Ewigkeit!', 'Psalm 121,7-8', ARRAY['Psalm 121,7-8']::text[]),
  (382, 'Vergeltet niemand Böses mit Bösem! Seid auf das bedacht, was in den Augen aller Menschen gut ist.', 'Römer 12,17', ARRAY['Römer 12,17']::text[]),
  (383, 'Der Weise trägt sein Herz auf dem rechten Fleck, der Narr hat es am unrechten Ort.', 'Prediger 10,2', ARRAY['Prediger 10,2']::text[]),
  (384, 'Darum bist du, HERR Gott, auch so hoch erhaben; denn dir ist niemand gleich, und es gibt keinen Gott außer dir, nach allem, was wir mit unseren Ohren gehört haben!', '2. Samuel 7,22', ARRAY['2. Samuel 7,22']::text[]),
  (385, 'Seht darauf, dass niemand Böses mit Bösem vergilt, sondern trachtet allezeit nach dem Guten, sowohl untereinander als auch gegenüber jedermann!', '1. Thessalonicher 5,15', ARRAY['1. Thessalonicher 5,15']::text[]),
  (386, 'Falsche Lippen sind dem Herrn ein Greuel, wer aber die Wahrheit übt, gefällt ihm wohl.', 'Sprüche 12,22', ARRAY['Sprüche 12,22']::text[]),
  (387, 'Du beobachtest mich, ob ich gehe oder liege, und bist vertraut mit allen meinen Wegen.', 'Psalm 139,3', ARRAY['Psalm 139,3']::text[]),
  (388, 'O Timotheus, bewahre das anvertraute Gut, meide das unheilige, nichtige Geschwätz und die Widersprüche der fälschlich so genannten »Erkenntnis«!', '1. Timotheus 6,20', ARRAY['1. Timotheus 6,20']::text[]),
  (389, 'Ein umhergehender Verleumder plaudert Geheimnisse aus; darum, weil er den Mund nicht halten kann, laß dich gar nicht mit ihm ein!', 'Sprüche 20,19', ARRAY['Sprüche 20,19']::text[]),
  (390, 'Wer an mich glaubt, wie die Schrift gesagt hat, aus seinem Leib werden Ströme lebendigen Wassers fließen.', 'Johannes 7,38', ARRAY['Johannes 7,38']::text[]),
  (391, 'Und der König wird ihnen antworten und sagen: Wahrlich, ich sage euch: Was ihr einem dieser meiner geringsten Brüder getan habt, das habt ihr mir getan!', 'Matthäus 25,40', ARRAY['Matthäus 25,40']::text[]),
  (392, 'Im Übrigen, meine Brüder, seid stark in dem Herrn und in der Macht seiner Stärke.', 'Epheser 6,10', ARRAY['Epheser 6,10']::text[]),
  (393, 'Jesus spricht zu ihm: Thomas, du glaubst, weil du mich gesehen hast; glückselig sind, die nicht sehen und doch glauben!', 'Johannes 20,29', ARRAY['Johannes 20,29']::text[]),
  (394, 'Und Jesus antwortete und sprach zu ihnen: Habt acht, dass euch niemand verführt!', 'Matthäus 24,4', ARRAY['Matthäus 24,4']::text[]),
  (395, 'Der HERR ist nahe denen, die zerbrochenen Herzens sind, und er hilft denen, die zerschlagenen Geistes sind.', 'Psalm 34,19', ARRAY['Psalm 34,19']::text[]),
  (396, 'Laß mich früh deine Gnade hören, denn auf dich vertraue ich! Laß mich den Weg erkennen, auf dem ich gehen soll, denn zu dir erhebe ich meine Seele.', 'Psalm 143,8', ARRAY['Psalm 143,8']::text[]),
  (397, 'Jesus spricht zu ihr: Habe ich dir nicht gesagt: Wenn du glaubst, wirst du die Herrlichkeit Gottes sehen?', 'Johannes 11,40', ARRAY['Johannes 11,40']::text[]),
  (398, 'Das alles aber kommt von Gott, der uns mit sich selbst versöhnt hat durch Jesus Christus und uns den Dienst der Versöhnung gegeben hat.', '2. Korinther 5,18', ARRAY['2. Korinther 5,18']::text[]),
  (399, 'Gib dem, der dich bittet, und wende dich nicht ab von dem, der von dir borgen will!', 'Matthäus 5,42', ARRAY['Matthäus 5,42']::text[]);
INSERT INTO _pool_seed (idx, verse, reference, raw_refs) VALUES
  (400, 'Darum vertrauen auf dich, die deinen Namen kennen; denn du hast nicht verlassen, die dich, Herr, suchen!', 'Psalm 9,11', ARRAY['Psalm 9,11']::text[]),
  (401, 'Der Herr aber ist es, der selbst vor dir hergeht, er wird mit dir sein und wird dich nicht aufgeben, noch dich verlassen; fürchte dich nicht und erschrick nicht!', '5. Mose 31,8', ARRAY['5. Mose 31,8', '5. Mose 31:8']::text[]),
  (402, 'Und Henoch wandelte mit Gott, und er war nicht mehr, denn Gott hatte ihn hinweggenommen.', '1. Mose 5,24', ARRAY['1. Mose 5,24']::text[]),
  (403, 'Denn das ganze Gesetz wird in einem Wort erfüllt, in dem: »Du sollst deinen Nächsten lieben wie dich selbst«.', 'Galater 5,14', ARRAY['Galater 5,14']::text[]),
  (404, 'Und die vorausgingen und die nachfolgten, riefen und sprachen: »Hosianna! Gepriesen sei der, welcher kommt im Namen des Herrn!«', 'Markus 11,9', ARRAY['Markus 11,9']::text[]),
  (405, 'Unzucht aber und alle Unreinheit oder Habsucht soll nicht einmal bei euch erwähnt werden, wie es Heiligen geziemt; auch nicht Schändlichkeit und albernes Geschwätz oder Witzeleien, die sich nicht gehören, sondern vielmehr Danksagung.', 'Epheser 5,3-4', ARRAY['Epheser 5,3-4']::text[]),
  (406, 'Und wer will euch Schaden zufügen, wenn ihr Nachahmer des Guten seid?', '1. Petrus 3,13', ARRAY['1. Petrus 3,13']::text[]),
  (407, 'Kämpfe den guten Kampf des Glaubens; ergreife das ewige Leben, zu dem du auch berufen bist und worüber du das gute Bekenntnis vor vielen Zeugen abgelegt hast.', '1. Timotheus 6,12', ARRAY['1. Timotheus 6,12']::text[]),
  (408, 'Habt acht auf die Hunde, habt acht auf die bösen Arbeiter, habt acht auf die Zerschneidung!', 'Philipper 3,2', ARRAY['Philipper 3,2']::text[]),
  (409, 'Denn so sehr hat Gott die Welt geliebt, dass er seinen eingeborenen Sohn gab, damit jeder, der an ihn glaubt, nicht verlorengeht, sondern ewiges Leben hat.', 'Johannes 3,16', ARRAY['Johannes 3,16']::text[]),
  (410, 'Vertraue auf ihn allezeit, o Volk, schüttet euer Herz vor ihm aus! Gott ist unsere Zuflucht. (Sela.)', 'Psalm 62,9', ARRAY['Psalm 62,9']::text[]),
  (411, 'Was sucht ihr den Lebenden bei den Toten? Er ist nicht hier, sondern er ist auferstanden!', 'Lukas 24,5-6', ARRAY['Lukas 24,5-6']::text[]),
  (412, 'Tod, wo ist dein Stachel? Totenreich, wo ist dein Sieg?', '1. Korinther 15,55', ARRAY['1. Korinther 15,54-55', '1. Korinther 15,55']::text[]),
  (413, 'Das Auge ist die Leuchte des Leibes. Wenn nun dein Auge lauter ist, so ist auch dein ganzer Leib licht; wenn es aber böse ist, so ist auch dein Leib finster.', 'Lukas 11,34', ARRAY['Lukas 11,34']::text[]),
  (414, 'dieser ist die Ausstrahlung seiner Herrlichkeit und der Ausdruck seines Wesens und trägt alle Dinge durch das Wort seiner Kraft; er hat sich, nachdem er die Reinigung von unseren Sünden durch sich selbst vollbracht hat, zur Rechten der Majestät in der Höhe gesetzt.', 'Hebräer 1,3', ARRAY['Hebräer 1,3']::text[]),
  (415, 'Der Geist ist es, der lebendig macht, das Fleisch nützt gar nichts. Die Worte, die ich zu euch rede, sind Geist und sind Leben.', 'Johannes 6,63', ARRAY['Johannes 6,63']::text[]),
  (416, 'Und wer nicht sein Kreuz auf sich nimmt und mir nachfolgt, der ist meiner nicht wert.', 'Matthäus 10,38', ARRAY['Matthäus 10,38']::text[]),
  (417, 'Weil nämlich Gott in Christus war und die Welt mit sich selbst versöhnte, indem er ihnen ihre Sünden nicht anrechnete und das Wort der Versöhnung in uns legte.', '2. Korinther 5,19', ARRAY['2. Korinther 5,19']::text[]),
  (418, 'Wir alle gingen in die Irre wie Schafe, jeder wandte sich auf seinen Weg; aber der HERR warf unser aller Schuld auf ihn.', 'Jesaja 53,6', ARRAY['Jesaja 53,6']::text[]),
  (419, 'Wenn wir aber im Licht wandeln, wie er im Licht ist, so haben wir Gemeinschaft miteinander, und das Blut Jesu Christi, seines Sohnes, reinigt uns von aller Sünde.', '1. Johannes 1,7', ARRAY['1. Johannes 1,7', '1.Johannes 1,7']::text[]),
  (420, 'Im Anfang war das Wort, und das Wort war bei Gott, und das Wort war Gott.', 'Johannes 1,1', ARRAY['Johannes 1,1']::text[]),
  (421, 'Bewahre deinen Fuß, wenn du zum Haus Gottes gehst! Sich nahen, um zu hören, ist besser, als wenn die Toren Opfer bringen; denn sie haben keine Erkenntnis, darum tun sie Böses.', 'Prediger 4,17', ARRAY['Prediger 4,17']::text[]),
  (422, 'Wo viele Worte sind, da geht es ohne Sünde nicht ab; wer aber seine Lippen im Zaum hält, der ist klug.', 'Sprüche 10,19', ARRAY['Sprüche 10,19', 'Sprüche 10:19']::text[]),
  (423, 'Denn der HERR sieht nicht auf das, worauf der Mensch sieht; denn der Mensch sieht auf das, was vor Augen ist, der Herr aber sieht das Herz an!', '1. Samuel 16,7', ARRAY['1. Samuel 16,7']::text[]),
  (424, 'Der HERR vergelte dir deine Tat, und dir werde voller Lohn zuteil von dem HERRN, dem Gott Israels, zu dem du gekommen bist, um Zuflucht zu suchen unter seinen Flügeln!', 'Ruth 2,12', ARRAY['Ruth 2,12']::text[]),
  (425, 'Bringt Opfer der Gerechtigkeit und vertraut auf den HERRN!', 'Psalm 4,6', ARRAY['Psalm 4,6']::text[]),
  (426, 'Du wirst mir den Weg des Lebens zeigen; vor deinem Angesicht sind Freuden in Fülle, liebliches Wesen zu deiner Rechten ewiglich!', 'Psalm 16,11', ARRAY['Psalm 16,11']::text[]),
  (427, 'Jesus antwortete und sprach zu ihm: Wenn jemand mich liebt, so wird er mein Wort befolgen, und mein Vater wird ihn lieben, und wir werden zu ihm kommen und Wohnung bei ihm machen.', 'Johannes 14,23', ARRAY['Johannes 14,23']::text[]),
  (428, 'Aus diesem Grund erleide ich dies auch; aber ich schäme mich nicht. Denn ich weiß, an wen ich glaube, und ich bin überzeugt, dass er mächtig ist, das mir anvertraute Gut zu bewahren bis zu jenem Tag.', '2. Timotheus 1,12', ARRAY['2. Timotheus 1,12']::text[]),
  (429, 'Wer ist ein Gott wie du, der die Sünde vergibt und dem Überrest seines Erbteils die Übertretung erläßt, der seinen Zorn nicht allezeit festhält, sondern Lust an der Gnade hat?', 'Micha 7,18', ARRAY['Micha 7,18']::text[]),
  (430, 'Wenn er aber als Christ leidet, so soll er sich nicht schämen, sondern er soll Gott verherrlichen in dieser Sache!', '1. Petrus 4,16', ARRAY['1. Petrus 4,16']::text[]),
  (431, 'Vor allem aber habt innige Liebe untereinander; denn die Liebe wird eine Menge von Sünden zudecken.', '1. Petrus 4,8', ARRAY['1. Petrus 4,8']::text[]),
  (432, 'Bringt den Zehnten ganz in das Vorratshaus, damit Speise in meinem Haus sei, und prüft mich doch dadurch, spricht der Herr der Heerscharen, ob ich euch nicht die Fenster des Himmels öffnen und euch Segen in überreicher Fülle herabschütten werde!', 'Maleachi 3,10', ARRAY['Maleachi 3,10']::text[]),
  (433, 'Und Gott segnete den siebten Tag und heiligte ihn, denn an ihm ruhte er von seinem ganzen Werk, das Gott schuf, als er es machte.', '1. Mose 2,3', ARRAY['1. Mose 2,3']::text[]),
  (434, 'Der Kluge tut alles mit Vernunft, aber der Tor verbreitet Dummheiten.', 'Sprüche 13,16', ARRAY['Sprüche 13,16']::text[]),
  (435, '»Ich will dich unterweisen und dir den Weg zeigen, auf dem du wandeln sollst; ich will dir raten, mein Auge auf dich richten.', 'Psalm 32,8', ARRAY['Psalm 32,8', 'Psalmen 32:8']::text[]),
  (436, 'Da nun Christus für uns im Fleisch gelitten hat, so wappnet auch ihr euch mit derselben Gesinnung; denn wer im Fleisch gelitten hat, der hat mit der Sünde abgeschlossen.', '1. Petrus 4,1', ARRAY['1. Petrus 4,1']::text[]),
  (437, 'Denn wir haben hier keine bleibende Stadt, sondern die zukünftige suchen wir.', 'Hebräer 13,14', ARRAY['Hebräer 13,14']::text[]),
  (438, 'HERR, zeige mir deine Wege und lehre mich deine Pfade! Leite mich in deiner Wahrheit und lehre mich, denn du bist der Gott meines Heils; auf dich harre ich allezeit.', 'Psalm 25,4-5', ARRAY['Psalm 25,4-5']::text[]),
  (439, 'Die sprachen: Ihr Männer von Galiläa, was steht ihr hier und seht zum Himmel? Dieser Jesus, der von euch weg in den Himmel aufgenommen worden ist, wird in derselben Weise wiederkommen, wie ihr ihn habt in den Himmel auffahren sehen!', 'Apostelgeschichte 1,11', ARRAY['Apostelgeschichte 1,11']::text[]),
  (440, 'Wohl dem Menschen, der beständig in der Furcht Gottes bleibt; wer aber sein Herz verhärtet, wird ins Unglück stürzen.', 'Sprüche 28,14', ARRAY['Sprüche 28,14']::text[]),
  (441, 'Dein Herz sei nicht eifersüchtig auf die Sünder, sondern trachte allezeit eifrig nach der Furcht des HERRN!', 'Sprüche 23,17', ARRAY['Sprüche 23,17']::text[]),
  (442, 'Wenn euch nun der Sohn frei machen wird, so seid ihr wirklich frei.', 'Johannes 8,36', ARRAY['Johannes 8,36']::text[]),
  (443, 'Auf Gott ruht mein Heil und meine Ehre; der Fels meiner Stärke, meine Zuflucht ist in Gott.', 'Psalm 62,8', ARRAY['Psalm 62,8']::text[]),
  (444, 'Denn jeder, der sich selbst erhöht, wird erniedrigt werden; und wer sich selbst erniedrigt, der wird erhöht werden.', 'Lukas 14,11', ARRAY['Lukas 14,11']::text[]),
  (445, 'So sei nun stark und sei ein Mann! Und befolge die Anordnungen des HERRN, deines Gottes, dass du in seinen Wegen wandelst, seine Satzungen, seine Gebote, seine Rechte und seine Zeugnisse hältst, wie es im Gesetz Moses geschrieben steht, damit du Gelingen hast in allem, was du tust und wohin du dich wendest.', '1. Könige 2,2-3', ARRAY['1. Könige 2,2-3']::text[]),
  (446, 'Erweist jedermann Achtung, liebt die Bruderschaft, fürchtet Gott, ehrt den König!', '1. Petrus 2,17', ARRAY['1. Petrus 2,17']::text[]),
  (447, 'Jesus aber blickte sie an und sprach: Bei den Menschen ist es unmöglich, aber nicht bei Gott! Denn bei Gott sind alle Dinge möglich.', 'Markus 10,27', ARRAY['Markus 10,27']::text[]),
  (448, 'Da wandte sich Jesus zu ihnen und sprach: Ihr Töchter Jerusalems, weint nicht über mich; weint vielmehr über euch selbst und über eure Kinder!', 'Lukas 23,28', ARRAY['Lukas 23,28']::text[]),
  (449, 'Besser wenig mit Gerechtigkeit, als ein großes Einkommen mit Unrecht.', 'Sprüche 16,8', ARRAY['Sprüche 16,8']::text[]),
  (450, 'Am guten Tag sei guter Dinge, und am bösen Tag bedenke: Auch diesen hat Gott gemacht gleichwie jenen – wie ja der Mensch auch gar nicht herausfinden kann, was nach ihm kommt.', 'Prediger 7,14', ARRAY['Prediger 7,14']::text[]),
  (451, 'Darum bist du nicht zu entschuldigen, o Mensch, wer du auch seist, der du richtest! Denn worin du den anderen richtest, verurteilst du dich selbst; denn du, der du richtest, verübst ja dasselbe!', 'Römer 2,1', ARRAY['Römer 2,1']::text[]),
  (452, 'Prüft euch selbst, ob ihr im Glauben seid; stellt euch selbst auf die Probe! Oder erkennt ihr euch selbst nicht, dass Jesus Christus in euch ist? Es sei denn, dass ihr unecht wärt!', '2. Korinther 13,5', ARRAY['2. Korinther 13,5']::text[]),
  (453, 'Aufgrund dieses Willens sind wir geheiligt durch die Opferung des Leibes Jesu Christi, und zwar ein für alle Mal.', 'Hebräer 10,10', ARRAY['Hebräer 10,10', 'Hebräerbrief 10:10']::text[]),
  (454, 'Die Frucht der Gerechtigkeit aber wird in Frieden denen gesät, die Frieden stiften.', 'Jakobus 3,18', ARRAY['Jakobus 3,18']::text[]),
  (455, 'Einem festen Herzen bewahrst du den Frieden, den Frieden, weil es auf dich vertraut.', 'Jesaja 26,3', ARRAY['Jesaja 26,3']::text[]),
  (456, 'Wer unbedacht schwatzt, der verletzt wie ein durchbohrendes Schwert; die Zunge der Weisen aber ist heilsam. Wahrhaftige Lippen bestehen ewiglich, die Lügenzunge nur einen Augenblick.', 'Sprüche 12,18-19', ARRAY['Sprüche 12,18', 'Sprüche 12,18-19']::text[]),
  (457, 'Nennt nicht alles Verschwörung, was dieses Volk Verschwörung nennt, und vor dem, was es fürchtet, fürchtet euch nicht und erschreckt nicht davor!', 'Jesaja 8,12', ARRAY['Jesaja 8,12']::text[]),
  (458, 'Siehe, das Auge des Herrn achtet auf die, welche ihn fürchten, die auf seine Gnade harren.', 'Psalm 33,18', ARRAY['Psalm 33,18']::text[]),
  (459, 'Ich will ihnen einen einzigen Hirten erwecken, der sie weiden soll, nämlich meinen Knecht David; der soll sie weiden, und der soll ihr Hirte sein', 'Hesekiel 34,23', ARRAY['Hesekiel 34,23']::text[]),
  (460, 'Er hing dem HERRN an, wich nicht von ihm ab und befolgte die Gebote, die der HERR dem Mose geboten hatte.', '2. Könige 18,6', ARRAY['2. Könige 18,6']::text[]),
  (461, 'Seid in allem dankbar; denn das ist der Wille Gottes in Christus Jesus für euch.', '1. Thessalonicher 5,18', ARRAY['1. Thessalonicher 5,18']::text[]),
  (462, 'So unterwerft euch nun Gott! Widersteht dem Teufel, so flieht er von euch!', 'Jakobus 4,7', ARRAY['Jakobus 4,7']::text[]),
  (463, 'Er gibt dem Müden Kraft und Stärke genug dem Unvermögenden.', 'Jesaja 40,29', ARRAY['Jesaja 40,29']::text[]),
  (464, 'Ich ermahne euch nun, ihr Brüder, angesichts der Barmherzigkeit Gottes, dass ihr eure Leiber darbringt als ein lebendiges, heiliges, Gott wohlgefälliges Opfer: das sei euer vernünftiger Gottesdienst!', 'Römer 12,1', ARRAY['Römer 12,1']::text[]),
  (465, 'Ein Psalm Davids. Der Herr ist mein Hirte; mir wird nichts mangeln. Er weidet mich auf grünen Auen und führt mich zu stillen Wassern.', 'Psalm 23,1-2', ARRAY['Psalm 23,1', 'Psalm 23,1-2']::text[]),
  (466, 'Die Liebe tut dem Nächsten nichts Böses; so ist nun die Liebe die Erfüllung des Gesetzes.', 'Römer 13,10', ARRAY['Römer 13,10']::text[]),
  (467, 'Es ist dir gesagt, o Mensch, was gut ist und was der Herr von dir fordert: Was anders als Recht tun, Liebe üben und demütig wandeln mit deinem Gott?', 'Micha 6,8', ARRAY['Micha 6,8', 'Micha 6:8']::text[]),
  (468, 'Denn es wird eine Zeit kommen, da werden sie die gesunde Lehre nicht ertragen, sondern sich selbst nach ihren eigenen Lüsten Lehrer beschaffen, weil sie empfindliche Ohren haben.', '2. Timotheus 4,3', ARRAY['2. Timotheus 4,3']::text[]),
  (469, 'Siehe, ich, der HERR, bin der Gott alles Fleisches; sollte mir irgendetwas unmöglich sein?', 'Jeremia 32,27', ARRAY['Jeremia 32,27']::text[]),
  (470, 'Darum habt gut acht auf eure Seelen, dass ihr den Herrn, euren Gott, lieb habt!', 'Josua 23,11', ARRAY['Josua 23,11']::text[]),
  (471, 'Ja, er kennt meinen Weg; wenn er mich prüft, so werde ich wie Gold hervorgehen! Mein Fuß ist seinen Tritten gefolgt; seinen Weg habe ich bewahrt und bin nicht davon abgewichen.', 'Hiob 23,10-11', ARRAY['Hiob 23,10-11']::text[]),
  (472, 'Ein neues Gebot gebe ich euch, dass ihr einander lieben sollt, damit, wie ich euch geliebt habe, auch ihr einander liebt.', 'Johannes 13,34', ARRAY['Johannes 13,34', 'Johannes 13,34-35', 'Johannes 13,35']::text[]),
  (473, 'Verleumdet einander nicht, ihr Brüder! Wer seinen Bruder verleumdet und seinen Bruder richtet, der verleumdet das Gesetz und richtet das Gesetz; wenn du aber das Gesetz richtest, so bist du nicht ein Täter, sondern ein Richter des Gesetzes.', 'Jakobus 4,11', ARRAY['Jakobus 4,11']::text[]),
  (474, 'Dabei stärkten sie die Seelen der Jünger und ermahnten sie, unbeirrt im Glauben zu bleiben, und sagten ihnen, dass wir durch viele Bedrängnisse in das Reich Gottes eingehen müssen.', 'Apostelgeschichte 14,22', ARRAY['Apostelgeschichte 14,22']::text[]),
  (475, 'Wach auf, meine Seele, Harfe und Laute, wacht auf! Ich will die Morgenröte wecken.', 'Psalm 57,9', ARRAY['Psalm 57,9']::text[]),
  (476, 'Und als Jesus an den Ort kam, blickte er auf und sah ihn und sprach zu ihm: Zachäus, steige schnell herab; denn heute muss ich in deinem Haus einkehren!', 'Lukas 19,5', ARRAY['Lukas 19,5']::text[]),
  (477, 'Möge mein Nachsinnen ihm wohlgefallen! Ich freue mich an dem HERRN.', 'Psalm 104,34', ARRAY['Psalm 104,34']::text[]),
  (478, 'Den Gottlosen erhält er nicht am Leben, aber den Elenden schafft er Recht. Er wendet seine Augen nicht ab von dem Gerechten, und er setzt sie auf ewig mit Königen auf den Thron, damit sie herrschen.', 'Hiob 36,6-7', ARRAY['Hiob 36,6-7']::text[]),
  (479, 'Erzittert und sündigt nicht! Denkt nach in eurem Herzen auf eurem Lager und seid still! (Sela.)', 'Psalm 4,5', ARRAY['Psalm 4,5']::text[]),
  (480, 'Deine Augen sahen mich schon als ungeformten Keim, und in dein Buch waren geschrieben alle Tage, die noch werden sollten, als noch keiner von ihnen war.', 'Psalm 139,16', ARRAY['Psalm 139,16']::text[]),
  (481, 'Wir aber gehören nicht zu denen, die feige zurückweichen zum Verderben, sondern zu denen, die glauben zur Errettung der Seele.', 'Hebräer 10,39', ARRAY['Hebräer 10,39']::text[]),
  (482, 'Die Heiligen, die auf Erden sind, sie sind die Edlen, an denen ich all mein Wohlgefallen habe.', 'Psalm 16,3', ARRAY['Psalm 16,3']::text[]),
  (483, 'Aber am letzten, dem großen Tag des Festes stand Jesus auf, rief und sprach: Wenn jemand dürstet, der komme zu mir und trinke!', 'Johannes 7,37', ARRAY['Johannes 7,37']::text[]),
  (484, 'So laufe ich nun nicht wie aufs Ungewisse; ich führe meinen Faustkampf nicht mit bloßen Luftstreichen, sondern ich bezwinge meinen Leib und beherrsche ihn, damit ich nicht anderen verkündige und selbst verwerflich werde.', '1. Korinther 9,26-27', ARRAY['1. Korinther 9,27', '1.Korinther 9,26-27']::text[]),
  (485, 'Weißt du es denn nicht, hast du es denn nicht gehört? Der ewige Gott, der HERR, der die Enden der Erde geschaffen hat, wird nicht müde noch matt; sein Verstand ist unerschöpflich!', 'Jesaja 40,28', ARRAY['Jesaja 40,28']::text[]),
  (486, 'Der Gerechte wird sich freuen im HERRN und auf ihn vertrauen, und alle aufrichtigen Herzen werden sich glücklich preisen.', 'Psalm 64,11', ARRAY['Psalm 64,11']::text[]),
  (487, 'Werdet meine Nachahmer, ihr Brüder, und seht auf diejenigen, die so wandeln, wie ihr uns zum Vorbild habt.', 'Philipper 3,17', ARRAY['Philipper 3,17']::text[]),
  (488, 'Der HERR ist mein Fels, meine Burg und mein Retter; mein Gott ist mein Fels, in dem ich mich berge, mein Schild und das Horn meines Heils, meine sichere Festung.', 'Psalm 18,3', ARRAY['Psalm 18,3']::text[]),
  (489, 'Wahrlich, wahrlich, ich sage euch: Der Knecht ist nicht größer als sein Herr, noch der Gesandte größer als der ihn gesandt hat.', 'Johannes 13,16', ARRAY['Johannes 13,16']::text[]),
  (490, 'Herr, tue meine Lippen auf, damit mein Mund dein Lob verkündige!', 'Psalm 51,17', ARRAY['Psalm 51,17']::text[]),
  (491, 'Wer unter euch fürchtet den Herrn? Wer gehorcht der Stimme seines Knechtes? Wenn er im Finstern wandelt und ihm kein Licht scheint, so vertraue er auf den Namen des Herrn und halte sich an seinen Gott!', 'Jesaja 50,10', ARRAY['Jesaja 50,10']::text[]),
  (492, 'Sucht den HERRN, solange er zu finden ist; ruft ihn an, während er nahe ist!', 'Jesaja 55,6', ARRAY['Jesaja 55,6']::text[]),
  (493, 'Denn so hoch der Himmel über der Erde ist, so groß ist seine Gnade über denen, die ihn fürchten.', 'Psalm 103,11', ARRAY['Psalm 103,11']::text[]),
  (494, 'Sei du nur stark und sehr mutig, und achte darauf, dass du nach dem ganzen Gesetz handelst, das dir mein Knecht Mose befohlen hat. Weiche nicht davon ab, weder zur Rechten noch zur Linken, damit du weise handelst überall, wo du hingehst!', 'Josua 1,7', ARRAY['Josua 1,7']::text[]),
  (495, 'Ein Vater der Waisen, ein Anwalt der Witwen ist Gott, der in seinem Heiligtum wohnt; ein Gott, der Vereinsamten ein Heim gibt, der Gefangene hinausführt ins Glück; aber die Widerspenstigen wohnen in dürrem Land.', 'Psalm 68,6-7', ARRAY['Psalm 68,6-7']::text[]),
  (496, 'Wenn wir nur in diesem Leben auf Christus hoffen, so sind wir die elendesten unter allen Menschen!', '1. Korinther 15,19', ARRAY['1. Korinther 15,19']::text[]),
  (497, 'Wer unter dem Schirm des Höchsten sitzt, der bleibt unter dem Schatten des Allmächtigen.', 'Psalm 91,1', ARRAY['Psalm 91,1']::text[]),
  (498, 'Dieses Volk naht sich zu mir mit seinem Mund und ehrt mich mit den Lippen, aber ihr Herz ist fern von mir.', 'Matthäus 15,8', ARRAY['Matthäus 15,8']::text[]),
  (499, 'Ihr gedachtet mir zwar Böses zu tun; aber Gott gedachte es gut zu machen, um es so hinauszuführen, wie es jetzt zutage liegt, um ein zahlreiches Volk am Leben zu erhalten.', '1. Mose 50,20', ARRAY['1. Mose 50,20']::text[]),
  (500, 'Ein Mensch macht vielerlei Pläne in seinem Herzen, aber der Ratschluss des Herrn hat Bestand.', 'Sprüche 19,21', ARRAY['Sprüche 19,21']::text[]),
  (501, 'Geliebte, da es mir ein großes Anliegen ist, euch von dem gemeinsamen Heil zu schreiben, hielt ich es für notwendig, euch mit der Ermahnung zu schreiben, dass ihr für den Glauben kämpft, der den Heiligen ein für allemal überliefert worden ist.', 'Judas 3', ARRAY['Judas 1,3', 'Judas 3']::text[]),
  (502, 'Denn Gott, der Herr, ist Sonne und Schild; der Herr gibt Gnade und Herrlichkeit, wer in Lauterkeit wandelt, dem versagt er nichts Gutes.', 'Psalm 84,12', ARRAY['Psalm 84,12']::text[]),
  (503, 'Die Furcht des Herrn ist der Anfang der Weisheit; sie macht alle einsichtig, die sie befolgen. Sein Ruhm bleibt ewiglich bestehen.', 'Psalm 111,10', ARRAY['Psalm 111,10']::text[]),
  (504, 'Da sprach Jesus zu seinen Jüngern: Wenn jemand mir nachkommen will, so verleugne er sich selbst und nehme sein Kreuz auf sich und folge mir nach!', 'Matthäus 16,24', ARRAY['Matthäus 16,24']::text[]),
  (505, 'Wer nicht mit mir ist, der ist gegen mich; und wer nicht mit mir sammelt, der zerstreut!', 'Lukas 11,23', ARRAY['Lukas 11,23']::text[]),
  (506, 'Und er ist deshalb für alle gestorben, damit die, welche leben, nicht mehr für sich selbst leben, sondern für den, der für sie gestorben und auferstanden ist.', '2. Korinther 5,15', ARRAY['2. Korinther 5,14-15', '2. Korinther 5,15']::text[]),
  (507, 'Wer Verstand erwirbt, liebt seine Seele; wer Einsicht bewahrt, findet Gutes.', 'Sprüche 19,8', ARRAY['Sprüche 19,8']::text[]),
  (508, 'Ihr aber, seid stark und lasst eure Hände nicht sinken; denn euer Werk hat seinen Lohn!', '2. Chronik 15,7', ARRAY['2. Chronik 15,7']::text[]),
  (509, 'Denn wenn dieses Vorhaben oder dieses Werk von Menschen ist, so wird es zunichte werden; ist es aber von Gott, so könnt ihr es nicht vernichten.', 'Apostelgeschichte 5,38-39', ARRAY['Apostelgeschichte 5,38-39']::text[]),
  (510, 'Aber der Herr ist meine sichere Burg geworden, mein Gott der Fels, bei dem ich Zuflucht gefunden habe.', 'Psalm 94,22', ARRAY['Psalm 94,22']::text[]),
  (511, 'Es pflegten sich ihm aber alle Zöllner und Sünder zu nahen, um ihn zu hören.', 'Lukas 15,1', ARRAY['Lukas 15,1']::text[]),
  (512, 'An dem Tag, da ich rief, hast du mir geantwortet; du hast mir Mut verliehen, in meine Seele kam Kraft.', 'Psalm 138,3', ARRAY['Psalm 138,2-3', 'Psalm 138,3']::text[]),
  (513, 'Trachtet nach dem, was droben ist, nicht nach dem, was auf Erden ist. Und was immer ihr tut in Wort oder Werk, das tut alles im Namen des Herrn Jesus und dankt Gott, dem Vater, durch ihn.', 'Kolosser 3,2.17', ARRAY['Kolosser 3,1-2', 'Kolosser 3,2+17']::text[]),
  (514, 'Licht wird dem Gerechten gesät und Freude den von Herzen Aufrichtigen.', 'Psalm 97,11', ARRAY['Psalm 97,11']::text[]),
  (515, 'Und erbarmt euch über die einen, wobei ihr unterscheiden sollt; andere aber rettet mit Furcht, indem ihr sie aus dem Feuer reißt, wobei ihr auch das vom Fleisch befleckte Gewand hassen sollt.', 'Judas 22-23', ARRAY['Judas 22-23']::text[]),
  (516, 'Dient einander, jeder mit der Gnadengabe, die er empfangen hat, als gute Haushalter der mannigfaltigen Gnade Gottes.', '1. Petrus 4,10', ARRAY['1. Petrus 4,10']::text[]),
  (517, 'Und lehrt sie alles halten, was ich euch befohlen habe. Und siehe, ich bin bei euch alle Tage bis an das Ende der Weltzeit! Amen.', 'Matthäus 28,20', ARRAY['Matthäus 28,20']::text[]),
  (518, 'Wenn der Unmut des Herrschers gegen dich aufsteigt, so verlasse deinen Posten nicht; denn Gelassenheit verhütet große Sünden.', 'Prediger 10,4', ARRAY['Prediger 10,4']::text[]),
  (519, 'O dass du doch auf meine Gebote geachtet hättest! Dann wäre dein Friede wie ein Wasserstrom gewesen und deine Gerechtigkeit wie Meereswellen.', 'Jesaja 48,18', ARRAY['Jesaja 48,18']::text[]),
  (520, 'So wie auch ich in allen Stücken allen zu Gefallen lebe und nicht meinen Nutzen suche, sondern den der vielen, damit sie gerettet werden.', '1. Korinther 10,33', ARRAY['1. Korinther 10,33']::text[]),
  (521, 'Er sagte ihnen aber auch ein Gleichnis, um ihnen zu zeigen, dass es nötig ist, allezeit zu beten und nicht nachlässig zu werden.', 'Lukas 18,1', ARRAY['Lukas 18,1']::text[]),
  (522, 'Ihm, der uns geliebt hat und uns von unseren Sünden gewaschen hat durch sein Blut, und uns zu Königen und Priestern gemacht hat für seinen Gott und Vater – Ihm sei die Herrlichkeit und die Macht von Ewigkeit zu Ewigkeit! Amen.', 'Offenbarung 1,5-6', ARRAY['Offenbarung 1,5-6']::text[]),
  (523, 'Fragt nach dem HERRN und nach seiner Macht, sucht sein Angesicht allezeit!', 'Psalm 105,4', ARRAY['Psalm 105,4']::text[]),
  (524, 'Lasst euch von niemand in irgendeiner Weise verführen! Denn es muss unbedingt zuerst der Abfall kommen und der Mensch der Sünde geoffenbart werden, der Sohn des Verderbens.', '2. Thessalonicher 2,3', ARRAY['2. Thessalonicher 2,3']::text[]),
  (525, 'Habt acht, dass ihr eure Almosen nicht vor den Leuten gebt, um von ihnen gesehen zu werden; sonst habt ihr keinen Lohn bei eurem Vater im Himmel.', 'Matthäus 6,1', ARRAY['Matthäus 6,1']::text[]),
  (526, 'Aber der Edle hat Edles im Sinn, und er steht auch zu dem, was edel ist.', 'Jesaja 32,8', ARRAY['Jesaja 32,8']::text[]),
  (527, 'Er hat uns errettet aus der Herrschaft der Finsternis und hat uns versetzt in das Reich des Sohnes seiner Liebe, in dem wir die Erlösung haben durch sein Blut, die Vergebung der Sünden.', 'Kolosser 1,13-14', ARRAY['Kolosser 1,13-14']::text[]),
  (528, 'Sondern dieses Wort habe ich ihnen befohlen: Gehorcht meiner Stimme, so will ich euer Gott sein, und ihr sollt mein Volk sein; und wandelt auf dem ganzen Weg, den ich euch gebieten werde, damit es euch wohlergehe!', 'Jeremia 7,23', ARRAY['Jeremia 7,23']::text[]),
  (529, 'Die Furcht des HERRN ist eine Quelle des Lebens; man meidet durch sie die Fallstricke des Todes.', 'Sprüche 14,27', ARRAY['Sprüche 14,27']::text[]),
  (530, 'Glückselig sind die, deren Gesetzlosigkeiten vergeben und deren Sünden zugedeckt sind; glückselig ist der Mann, dem der Herr die Sünde nicht anrechnet!', 'Römer 4,7-8', ARRAY['Römer 4,7-8']::text[]),
  (531, 'Die Rettung der Gerechten kommt von dem Herrn; er ist ihre Zuflucht zur Zeit der Drangsal.', 'Psalm 37,39', ARRAY['Psalm 37,39']::text[]),
  (532, 'Weisheit ist besser als Kriegsgerät; aber ein einziger Sünder verdirbt viel Gutes.', 'Prediger 9,18', ARRAY['Prediger 9,18']::text[]),
  (533, 'Er aber sagte ihnen: So gebt doch dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist!', 'Lukas 20,25', ARRAY['Lukas 20,25']::text[]),
  (534, 'Rufe mich an, so will ich dir antworten und dir große und unbegreifliche Dinge verkünden, die du nicht weißt.', 'Jeremia 33,3', ARRAY['Jeremia 33,3']::text[]),
  (535, 'Sei nicht allzu gerecht und erzeige dich nicht übermäßig weise! Warum willst du dich selbst verderben?', 'Prediger 7,16', ARRAY['Prediger 7,16']::text[]),
  (536, 'Als ich deine Worte fand, da verschlang ich sie; deine Worte sind mir zur Freude und Wonne meines Herzens geworden, denn ich bin ja nach deinem Namen genannt, o HERR, du Gott der Heerscharen!', 'Jeremia 15,16', ARRAY['Jeremia 15,16']::text[]),
  (537, 'Habt nicht lieb die Welt, noch was in der Welt ist! Wenn jemand die Welt lieb hat, so ist die Liebe des Vaters nicht in ihm.', '1. Johannes 2,15', ARRAY['1. Johannes 2,15']::text[]),
  (538, 'Und daran erkennen wir, dass wir aus der Wahrheit sind, und damit werden wir unsere Herzen vor Ihm stillen, dass, wenn unser Herz uns verurteilt, Gott größer ist als unser Herz und alles weiß.', '1. Johannes 3,19-20', ARRAY['1. Johannes 3,19-20']::text[]),
  (539, 'Glaubt mir, dass ich im Vater bin und der Vater in mir ist; wenn nicht, so glaubt mir doch um der Werke willen!', 'Johannes 14,11', ARRAY['Johannes 14,11']::text[]),
  (540, 'Ihr erforscht die Schriften, weil ihr meint, in ihnen das ewige Leben zu haben; und sie sind es, die von mir Zeugnis geben.', 'Johannes 5,39', ARRAY['Johannes 5,39']::text[]),
  (541, 'Die Weisheit von oben aber ist erstens rein, sodann friedfertig, gütig; sie lässt sich etwas sagen, ist voll Barmherzigkeit und guter Früchte, unparteiisch und frei von Heuchelei.', 'Jakobus 3,17', ARRAY['Jakobus 3,17']::text[]),
  (542, 'Glückselig sind jene Knechte, welche der Herr, wenn er kommt, wachend finden wird! Wahrlich, ich sage euch: Er wird sich schürzen und sie zu Tisch führen und hinzutreten und sie bedienen.', 'Lukas 12,37', ARRAY['Lukas 12,37']::text[]),
  (543, 'Und Gott erhörte ihr Wehklagen, und Gott gedachte an seinen Bund mit Abraham, Isaak und Jakob. Und Gott sah auf die Kinder Israels, und Gott nahm sich ihrer an.', '2. Mose 2,24-25', ARRAY['2. Mose 2,24-25']::text[]),
  (544, 'Euer Schmuck soll nicht der äußerliche sein, Haarflechten und Anlegen von Goldgeschmeide oder Kleidung, sondern der verborgene Mensch des Herzens in dem unvergänglichen Schmuck eines sanften und stillen Geistes, der vor Gott sehr kostbar ist.', '1. Petrus 3,3-4', ARRAY['1. Petrus 3,3-4']::text[]),
  (545, 'Siehe, es kommen Tage, spricht Gott, der Herr, da werde ich einen Hunger ins Land senden; nicht einen Hunger nach Brot, noch einen Durst nach Wasser, sondern danach, das Wort des Herrn zu hören.', 'Amos 8,11', ARRAY['Amos 8,11']::text[]),
  (546, 'Siehe, das war die Sünde deiner Schwester Sodom: Hochmut, Speise in Fülle und sorglose Ruhe wurde ihr und ihren Töchtern zuteil; aber dem Armen und Bedürftigen reichten sie nie die Hand.', 'Hesekiel 16,49', ARRAY['Hesekiel 16,49']::text[]),
  (547, 'Aber die Sanftmütigen werden das Land erben und sich großen Friedens erfreuen.', 'Psalm 37,11', ARRAY['Psalm 37,11']::text[]),
  (548, 'Da suchten die Minister und Satrapen eine Anklage gegen Daniel zu finden im Hinblick auf die Regierungsgeschäfte; aber sie konnten keine Schuld oder irgend etwas Nachteiliges finden, weil er treu war und keine Nachlässigkeit noch irgend ein Vergehen bei ihm gefunden werden konnte.', 'Daniel 6,5', ARRAY['Daniel 6,5']::text[]),
  (549, 'Und als er an den Ort gekommen war, sprach er zu ihnen: Betet, dass ihr nicht in Versuchung kommt!', 'Lukas 22,40', ARRAY['Lukas 22,40']::text[]),
  (550, 'Siehe, in meine Hände habe ich dich eingezeichnet; deine Mauern sind allezeit vor mir.', 'Jesaja 49,16', ARRAY['Jesaja 49,16']::text[]),
  (551, 'Vor allem aber ergreift den Schild des Glaubens, mit dem ihr alle feurigen Pfeile des Bösen auslöschen könnt, und nehmt auch den Helm des Heils und das Schwert des Geistes, welches das Wort Gottes ist.', 'Epheser 6,16-17', ARRAY['Epheser 6,16-17']::text[]),
  (552, 'Mache meine Schritte fest durch dein Wort, und lass nichts Böses über mich herrschen!', 'Psalm 119,133', ARRAY['Psalm 119,133']::text[]),
  (553, 'Hört mir zu, Juda und ihr Einwohner von Jerusalem: Vertraut auf den Herrn, euren Gott, so könnt ihr getrost sein, und glaubt seinen Propheten, so werdet ihr Gelingen haben!', '2. Chronik 20,20', ARRAY['2. Chronik 20,20']::text[]),
  (554, 'Darum lassen wir uns nicht entmutigen; sondern wenn auch unser äußerer Mensch zugrundegeht, so wird doch der innere Tag für Tag erneuert.', '2. Korinther 4,16', ARRAY['2. Korinther 4,16']::text[]),
  (555, 'Was ist mit dir, dass du so schläfst? Steh auf, rufe deinen Gott an! Vielleicht wird dieser Gott an uns gedenken, dass wir nicht untergehen!', 'Jona 1,6', ARRAY['Jona 1,6']::text[]),
  (556, 'Würdig bist du, o Herr, zu empfangen den Ruhm und die Ehre und die Macht; denn du hast alle Dinge geschaffen, und durch deinen Willen sind sie und wurden sie geschaffen!', 'Offenbarung 4,11', ARRAY['Offenbarung 4,11']::text[]),
  (557, 'Herrlichkeit bei Gott in der Höhe und Friede auf Erden, unter den Menschen Wohlgefallen!', 'Lukas 2,14', ARRAY['Lukas 2,14']::text[]),
  (558, 'Seid stark und mutig! Fürchtet euch nicht und lasst euch nicht vor ihnen grauen, denn der Herr, dein Gott, geht selbst mit dir; er wird dich nicht aufgeben noch dich verlassen!', '5. Mose 31,6', ARRAY['5. Mose 31,6']::text[]),
  (559, 'Er hat alles vortrefflich gemacht zu seiner Zeit, auch die Ewigkeit hat er ihnen ins Herz gelegt – nur dass der Mensch das Werk, das Gott getan hat, nicht von Anfang bis zu Ende ergründen kann.', 'Prediger 3,11', ARRAY['Prediger 3,11']::text[]),
  (560, 'Er aber sprach zu der Frau: Dein Glaube hat dich gerettet; geh hin in Frieden!', 'Lukas 7,50', ARRAY['Lukas 7,50']::text[]),
  (561, 'Jesus aber sprach zu ihm: Niemand, der seine Hand an den Pflug legt und zurückblickt, ist tauglich für das Reich Gottes!', 'Lukas 9,62', ARRAY['Lukas 9,62']::text[]),
  (562, 'Wenn ich mitten durch die Bedrängnis gehe, so wirst du mich am Leben erhalten; gegen den Zorn meiner Feinde wirst du deine Hand ausstrecken, und deine Rechte wird mich retten.', 'Psalm 138,7', ARRAY['Psalm 138,7']::text[]),
  (563, 'Achtet doch auf ihn, der solchen Widerspruch von den Sündern gegen sich erduldet hat, damit ihr nicht müde werdet und den Mut verliert!', 'Hebräer 12,3', ARRAY['Hebräer 12,3']::text[]),
  (564, 'Eines erbitte ich von dem Herrn, nach diesem will ich trachten: dass ich bleiben darf im Haus des Herrn mein ganzes Leben lang, um die Lieblichkeit des Herrn zu schauen und ihn zu suchen in seinem Tempel.', 'Psalm 27,4', ARRAY['Psalm 27,4']::text[]),
  (565, 'Denn wenn sie ihren Dienst gut versehen, erwerben sie sich selbst eine gute Stufe und viel Freimütigkeit im Glauben in Christus Jesus.', '1. Timotheus 3,13', ARRAY['1. Timotheus 3,13']::text[]),
  (566, 'Du aber rede, was der gesunden Lehre entspricht!', 'Titus 2,1', ARRAY['Titus 2,1']::text[]),
  (567, 'Dieser Gott – sein Weg ist vollkommen! Das Wort des Herrn ist geläutert; er ist ein Schild allen, die ihm vertrauen.', 'Psalm 18,31', ARRAY['Psalm 18,31']::text[]),
  (568, 'Und aus seiner Fülle haben wir alle empfangen Gnade um Gnade.', 'Johannes 1,16', ARRAY['Johannes 1,16']::text[]),
  (569, 'Gelobt sei Gott, der mein Gebet nicht abgewiesen noch seine Gnade von mir gewendet hat!', 'Psalm 66,20', ARRAY['Psalm 66,20']::text[]),
  (570, 'Aber die Stunde kommt und ist schon da, wo die wahren Anbeter den Vater im Geist und in der Wahrheit anbeten werden; denn der Vater sucht solche Anbeter.', 'Johannes 4,23', ARRAY['Johannes 4,23']::text[]),
  (571, 'Indem ihr zu jeder Zeit betet mit allem Gebet und Flehen im Geist, und wacht zu diesem Zweck in aller Ausdauer und Fürbitte für alle Heiligen.', 'Epheser 6,18', ARRAY['Epheser 6,18']::text[]),
  (572, 'Ist nicht deine Gottesfurcht deine Zuversicht, und die Tadellosigkeit deines Weges deine Hoffnung?', 'Hiob 4,6', ARRAY['Hiob 4,6']::text[]),
  (573, 'Das Auge ist die Leuchte des Leibes. Wenn nun dein Auge lauter ist, so wird dein ganzer Leib licht sein.', 'Matthäus 6,22', ARRAY['Matthäus 6,22']::text[]),
  (574, 'O ihr unverständigen Galater, wer hat euch verzaubert, dass ihr der Wahrheit nicht gehorcht, euch, denen Jesus Christus als unter euch gekreuzigt vor die Augen gemalt worden ist?', 'Galater 3,1', ARRAY['Galater 3,1']::text[]),
  (575, 'Denn »alles Fleisch ist wie Gras und alle Herrlichkeit des Menschen wie die Blume des Grases. Das Gras ist verdorrt und seine Blume abgefallen; aber das Wort des Herrn bleibt in Ewigkeit.«', '1. Petrus 1,24', ARRAY['1. Petrus 1,24']::text[]),
  (576, 'Denn der HERR, dein Gott, ist ein barmherziger Gott; er wird dich nicht verlassen noch verderben; er wird auch den Bund, den er deinen Vätern geschworen hat, nicht vergessen.', '5. Mose 4,31', ARRAY['5. Mose 4,31']::text[]),
  (577, 'Und die, bei denen unter die Dornen gesät wurde, das sind solche, die das Wort hören, aber die Sorgen dieser Weltzeit und der Betrug des Reichtums und die Begierden nach anderen Dingen dringen ein und ersticken das Wort, und es wird unfruchtbar.', 'Markus 4,18-19', ARRAY['Markus 4,18-19']::text[]),
  (578, 'Damit ihr einen Unterschied macht zwischen dem Heiligen und dem Unheiligen, zwischen dem Unreinen und Reinen.', '3. Mose 10,10', ARRAY['3. Mose 10,10']::text[]),
  (579, 'Er aber antwortete und sprach: Es steht geschrieben: »Der Mensch lebt nicht vom Brot allein, sondern von einem jeden Wort, das aus dem Mund Gottes hervorgeht!«', 'Matthäus 4,4', ARRAY['Matthäus 4,4']::text[]),
  (580, 'Umso reicher aber ist die Gnade, die er gibt. Darum spricht er: »Gott widersteht den Hochmütigen; den Demütigen aber gibt er Gnade«.', 'Jakobus 4,6', ARRAY['Jakobus 4,6']::text[]),
  (581, 'In der Furcht des HERRN liegt starkes Vertrauen, Er wird auch seinen Kindern eine Zuflucht sein.', 'Sprüche 14,26', ARRAY['Sprüche 14,26']::text[]),
  (582, 'Niemand kann zu mir kommen, es sei denn, dass ihn der Vater zieht, der mich gesandt hat; und ich werde ihn auferwecken am letzten Tag.', 'Johannes 6,44', ARRAY['Johannes 6,44']::text[]),
  (583, 'Wenn der Christus, unser Leben, offenbar werden wird, dann werdet auch ihr mit ihm offenbar werden in Herrlichkeit.', 'Kolosser 3,4', ARRAY['Kolosser 3,4']::text[]),
  (584, 'Er hat unsere Sünden selbst an seinem Leib getragen auf dem Holz, damit wir, den Sünden gestorben, der Gerechtigkeit leben mögen; durch seine Wunden seid ihr heil geworden.', '1. Petrus 2,24', ARRAY['1. Petrus 2,24']::text[]),
  (585, 'Und alles, was ihr glaubend erbittet im Gebet, das werdet ihr empfangen!', 'Matthäus 21,22', ARRAY['Matthäus 21,22']::text[]),
  (586, 'Denn auch Christus hat einmal für Sünden gelitten, der Gerechte für die Ungerechten, damit er uns zu Gott führte; und er wurde getötet nach dem Fleisch, aber lebendig gemacht durch den Geist.', '1. Petrus 3,18', ARRAY['1. Petrus 3,18']::text[]),
  (587, 'Also auch ihr: Haltet euch selbst dafür, dass ihr für die Sünde tot seid, aber für Gott lebt in Christus Jesus, unserem Herrn!', 'Römer 6,11', ARRAY['Römer 6,11']::text[]),
  (588, 'Totenreich und Abgrund sind dem HERRN bekannt, wie viel mehr die Herzen der Menschen!', 'Sprüche 15,11', ARRAY['Sprüche 15,11']::text[]),
  (589, 'Er hat uns das Geheimnis seines Willens bekanntgemacht, entsprechend dem Ratschluss, den er nach seinem Wohlgefallen gefasst hat in ihm.', 'Epheser 1,9', ARRAY['Epheser 1,9']::text[]),
  (590, 'Meine Brüder, verbindet den Glauben an unseren Herrn Jesus Christus, den Herrn der Herrlichkeit, nicht mit Ansehen der Person!', 'Jakobus 2,1', ARRAY['Jakobus 2,1']::text[]),
  (591, 'Denn ich bin der Herr, euer Gott; darum sollt ihr euch heiligen und sollt heilig sein, denn ich bin heilig; und ihr sollt euch nicht verunreinigen mit irgendwelchem Getier, das auf der Erde kriecht!', '3. Mose 11,44', ARRAY['3. Mose 11,44']::text[]),
  (592, 'Ich habe den guten Kampf gekämpft, den Lauf vollendet, den Glauben bewahrt.', '2. Timotheus 4,7', ARRAY['2. Timotheus 4,7']::text[]),
  (593, 'Denn er hat den, der von keiner Sünde wusste, für uns zur Sünde gemacht, damit wir in ihm zur Gerechtigkeit Gottes würden.', '2. Korinther 5,21', ARRAY['2. Korinther 5,21']::text[]),
  (594, 'Wenn jemand mir dienen will, so folge er mir nach; und wo ich bin, da soll auch mein Diener sein; und wenn jemand mir dient, so wird ihn mein Vater ehren.', 'Johannes 12,26', ARRAY['Johannes 12,26']::text[]),
  (595, 'Hört, meine geliebten Brüder: Hat nicht Gott die Armen dieser Welt erwählt, dass sie reich im Glauben würden und Erben des Reiches, das er denen verheißen hat, die ihn lieben?', 'Jakobus 2,5', ARRAY['Jakobus 2,5']::text[]),
  (596, 'Und alle, die gottesfürchtig leben wollen in Christus Jesus, werden Verfolgung erleiden.', '2. Timotheus 3,12', ARRAY['2. Timotheus 3,12']::text[]),
  (597, 'Als nun Jesus den Essig genommen hatte, sprach er: Es ist vollbracht! Und er neigte das Haupt und übergab den Geist.', 'Johannes 19,30', ARRAY['Johannes 19,30']::text[]),
  (598, 'Der HERR wird ihnen beistehen und sie erretten, er wird sie erretten von den Gottlosen und ihnen helfen; denn sie bergen sich bei ihm.', 'Psalm 37,40', ARRAY['Psalm 37,40']::text[]),
  (599, 'Er aber sprach zu ihr: Du redest so, wie eine törichte Frau redet! Wenn wir das Gute von Gott annehmen, sollten wir da das Böse nicht auch annehmen? – Bei alledem versündigte sich Hiob nicht mit seinen Lippen.', 'Hiob 2,10', ARRAY['Hiob 2,10']::text[]);
INSERT INTO _pool_seed (idx, verse, reference, raw_refs) VALUES
  (600, 'Zieht die ganze Waffenrüstung Gottes an, damit ihr standhalten könnt gegenüber den listigen Kunstgriffen des Teufels!', 'Epheser 6,11', ARRAY['Epheser 6,11']::text[]),
  (601, 'Und er rief die Volksmenge samt seinen Jüngern zu sich und sprach zu ihnen: Wer mir nachkommen will, der verleugne sich selbst und nehme sein Kreuz auf sich und folge mir nach!', 'Markus 8,34', ARRAY['Markus 8,34']::text[]),
  (602, 'Denn Christus ist das Ende des Gesetzes zur Gerechtigkeit für jeden, der glaubt.', 'Römer 10,4', ARRAY['Römer 10,4']::text[]),
  (603, 'Aber Jesus antwortete und sprach zu ihnen: Ihr irrt, weil ihr weder die Schriften noch die Kraft Gottes kennt.', 'Matthäus 22,29', ARRAY['Matthäus 22,29']::text[]),
  (604, 'Denn auch der Sohn des Menschen ist nicht gekommen, um sich dienen zu lassen, sondern um zu dienen und sein Leben zu geben als Lösegeld für viele.', 'Markus 10,45', ARRAY['Markus 10,45']::text[]),
  (605, 'So fliehe nun die jugendlichen Lüste, jage aber der Gerechtigkeit, dem Glauben, der Liebe, dem Frieden nach zusammen mit denen, die den Herrn aus reinem Herzen anrufen!', '2. Timotheus 2,22', ARRAY['2. Timotheus 2,22']::text[]),
  (606, 'Denn wir haben nichts in die Welt hineingebracht, und es ist klar, dass wir auch nichts hinausbringen können.', '1. Timotheus 6,7', ARRAY['1. Timotheus 6,7']::text[]),
  (607, 'Bin ich auch elend und arm – für mich sorgt der Herr. Du bist meine Hilfe und mein Retter; mein Gott, säume nicht!', 'Psalm 40,18', ARRAY['Psalm 40,18']::text[]),
  (608, 'Freut euch an dem Herrn und seid fröhlich, ihr Gerechten, und jubelt alle, die ihr aufrichtigen Herzens seid!', 'Psalm 32,11', ARRAY['Psalm 32,11']::text[]),
  (609, 'Denn die Ehre der Menschen war ihnen lieber als die Ehre Gottes.', 'Johannes 12,43', ARRAY['Johannes 12,43']::text[]),
  (610, 'Habt aber acht auf euch selbst, dass eure Herzen nicht beschwert werden durch Rausch und Trunkenheit und Sorgen des Lebens, und jener Tag unversehens über euch kommt!', 'Lukas 21,34', ARRAY['Lukas 21,34']::text[]),
  (611, 'Wenn jemand gegen einen Menschen sündigt, so wird Gott Schiedsrichter sein; wenn aber jemand gegen den HERRN sündigt, wer wird für ihn Fürsprecher sein?', '1. Samuel 2,25', ARRAY['1. Samuel 2,25']::text[]),
  (612, 'Vertraue auf den Herrn und tue Gutes, wohne im Land und übe Treue!', 'Psalm 37,3', ARRAY['Psalm 37,3']::text[]),
  (613, 'Wer ist weise und verständig unter euch? Der zeige durch einen guten Wandel seine Werke in Sanftmütigkeit, die aus der Weisheit kommt!', 'Jakobus 3,13', ARRAY['Jakobus 3,13']::text[]),
  (614, 'Nicht jeder, der zu mir sagt: Herr, Herr! wird in das Reich der Himmel eingehen, sondern wer den Willen meines Vaters im Himmel tut.', 'Matthäus 7,21', ARRAY['Matthäus 7,21']::text[]),
  (615, 'Und wenn jene Tage nicht verkürzt würden, so würde kein Fleisch gerettet werden; aber um der Auserwählten willen sollen jene Tage verkürzt werden.', 'Matthäus 24,22', ARRAY['Matthäus 24,22']::text[]),
  (616, 'Der Herr nun wurde, nachdem er mit ihnen geredet hatte, aufgenommen in den Himmel und setzte sich zur Rechten Gottes.', 'Markus 16,19', ARRAY['Markus 16,19']::text[]),
  (617, 'Gegen den Gütigen erzeigst du dich gütig, gegen den Rechtschaffenen rechtschaffen, gegen den Reinen erzeigst du dich rein, aber dem Hinterlistigen trittst du entgegen!', '2. Samuel 22,26-27', ARRAY['2. Samuel 22,26-27']::text[]),
  (618, '… auf dass sie alle eins seien, gleichwie du, Vater, in mir und ich in dir; auf dass auch sie in uns eins seien, damit die Welt glaube, dass du mich gesandt hast.', 'Johannes 17,21', ARRAY['Johannes 17,21']::text[]),
  (619, 'Seid still und erkennt, dass ich Gott bin; ich werde erhaben sein unter den Völkern, ich werde erhaben sein auf der Erde!', 'Psalm 46,11', ARRAY['Psalm 46,11']::text[]),
  (620, 'Und ich will den Vater bitten, und er wird euch einen anderen Beistand geben, dass er bei euch bleibt in Ewigkeit.', 'Johannes 14,16', ARRAY['Johannes 14,16']::text[]),
  (621, 'Denn meine Gedanken sind nicht eure Gedanken, und eure Wege sind nicht meine Wege, spricht der HERR.', 'Jesaja 55,8', ARRAY['Jesaja 55,8']::text[]),
  (622, 'Denn das Herz dieses Volkes ist verstockt, und mit den Ohren hören sie schwer, und ihre Augen haben sie verschlossen, dass sie nicht etwa mit den Augen sehen und mit den Ohren hören und mit dem Herzen verstehen und sich bekehren und ich sie heile.', 'Matthäus 13,15', ARRAY['Matthäus 13,15']::text[]),
  (623, 'Um deines Namens willen, o Herr, vergib meine Schuld; denn sie ist groß!', 'Psalm 25,11', ARRAY['Psalm 25,11']::text[]),
  (624, 'Und Jabez rief zu dem Gott Israels und sprach: O dass du mich reichlich segnen und meine Grenze erweitern wolltest und deine Hand mit mir wäre und du mich vor dem Übel bewahrtest, damit mich kein Schmerz trifft! Und Gott ließ kommen, was er gebeten hatte.', '1. Chronik 4,10', ARRAY['1. Chronik 4,10']::text[]),
  (625, 'Halte dich nicht selbst für weise; fürchte den HERRN und weiche vom Bösen!', 'Sprüche 3,7', ARRAY['Sprüche 3,7']::text[]),
  (626, 'Das ist aber der Wille dessen, der mich gesandt hat, dass jeder, der den Sohn sieht und an ihn glaubt, ewiges Leben hat; und ich werde ihn auferwecken am letzten Tag.', 'Johannes 6,40', ARRAY['Johannes 6,40']::text[]),
  (627, 'Und er sprach: Komm mit mir und sieh meinen Eifer für den HERRN! Und er führte ihn auf seinem Streitwagen.', '2. Könige 10,16', ARRAY['2. Könige 10,16']::text[]),
  (628, 'Übereile dich nicht mit deinem Mund, und lass dein Herz keine unbesonnenen Worte vor Gott aussprechen; denn Gott ist im Himmel, und du bist auf der Erde; darum sollst du nicht viele Worte machen!', 'Prediger 5,1', ARRAY['Prediger 5,1']::text[]),
  (629, 'Durch ihn lasst uns nun Gott beständig ein Opfer des Lobes darbringen, das ist die Frucht der Lippen, die seinen Namen bekennen!', 'Hebräer 13,15', ARRAY['Hebräer 13,15']::text[]),
  (630, 'Und die Gnade unseres Herrn wurde über alle Maßen groß samt dem Glauben und der Liebe, die in Christus Jesus ist.', '1. Timotheus 1,14', ARRAY['1. Timotheus 1,14']::text[]),
  (631, 'Gar keiner wird zuschanden, der auf dich harrt; zuschanden werden, die ohne Ursache treulos handeln.', 'Psalm 25,3', ARRAY['Psalm 25,3']::text[]),
  (632, 'Denn es ist uns unmöglich, nicht von dem zu reden, was wir gesehen und gehört haben!', 'Apostelgeschichte 4,20', ARRAY['Apostelgeschichte 4,20']::text[]),
  (633, 'Diese aber sind geschrieben, damit ihr glaubt, dass Jesus der Christus, der Sohn Gottes ist, und damit ihr durch den Glauben Leben habt in seinem Namen.', 'Johannes 20,31', ARRAY['Johannes 20,31']::text[]),
  (634, 'Denn die Schrift sagt: »Du sollst dem Ochsen nicht das Maul verbinden, wenn er drischt!«, und »Der Arbeiter ist seines Lohnes wert«. Gegen einen Ältesten nimm keine Klage an, außer aufgrund von zwei oder drei Zeugen.', '1. Timotheus 5,18-19', ARRAY['1. Timotheus 5,18-19']::text[]),
  (635, 'Sondern, wie geschrieben steht: »Was kein Auge gesehen und kein Ohr gehört und keinem Menschen ins Herz gekommen ist, was Gott denen bereitet hat, die ihn lieben«.', '1. Korinther 2,9', ARRAY['1. Korinther 2,9']::text[]),
  (636, 'Wer anderen eine Grube gräbt, fällt selbst hinein; und wer einen Stein auf andere wälzt, zu dem kehrt er zurück.', 'Sprüche 26,27', ARRAY['Sprüche 26,27']::text[]),
  (637, 'Darum, wie der Heilige Geist spricht: »Heute, wenn ihr seine Stimme hört, so verstockt eure Herzen nicht, wie in der Auflehnung, am Tag der Versuchung in der Wüste!«', 'Hebräer 3,7-8', ARRAY['Hebräer 3,7-8']::text[]),
  (638, 'Nimm dies zu Ohren, Hiob; steh still und erwäge Gottes Wundertaten!', 'Hiob 37,14', ARRAY['Hiob 37,14']::text[]),
  (639, 'Er hat auch euch, die ihr tot wart in den Übertretungen und dem unbeschnittenen Zustand eures Fleisches, mit ihm lebendig gemacht, indem er euch alle Übertretungen vergab.', 'Kolosser 2,13', ARRAY['Kolosser 2,13']::text[]),
  (640, 'Und das ist sein Gebot, dass wir glauben an den Namen seines Sohnes Jesus Christus und einander lieben, nach dem Gebot, das er uns gegeben hat.', '1. Johannes 3,23', ARRAY['1. Johannes 3,23']::text[]),
  (641, 'Endlich aber seid alle gleich gesinnt, mitfühlend, voll brüderlicher Liebe, barmherzig, gütig! 9 Vergeltet nicht Böses mit Bösem oder Schmähung mit Schmähung, sondern im Gegenteil segnet, weil ihr wisst, dass ihr dazu berufen seid, Segen zu erben.', '1. Petrus 3,8-9', ARRAY['1. Petrus 3,8', '1. Petrus 3:8-9']::text[]),
  (642, 'Dass aber durch das Gesetz niemand vor Gott gerechtfertigt wird, ist offenbar; denn »der Gerechte wird aus Glauben leben«.', 'Galater 3,11', ARRAY['Galater 3,11']::text[]),
  (643, 'Dein sind die Himmel, dir gehört auch die Erde, der Erdkreis und was ihn erfüllt; du hast es alles gegründet.', 'Psalm 89,12', ARRAY['Psalm 89,12']::text[]),
  (644, 'Siehe, der Vermessene – unaufrichtig ist seine Seele in ihm; der Gerechte aber wird durch seinen Glauben leben.', 'Habakuk 2,4', ARRAY['Habakuk 2,4']::text[]),
  (645, 'Einsicht macht einen Menschen langsam zum Zorn, und es ist ihm eine Ehre, Vergehungen zu übersehen.', 'Sprüche 19,11', ARRAY['Sprüche 19,11']::text[]),
  (646, 'Wer auf seinen Mund achtgibt, behütet seine Seele, wer aber immer seine Lippen aufsperrt, tut’s zu seinem Unglück.', 'Sprüche 13,3', ARRAY['Sprüche 13,3']::text[]),
  (647, 'Denn die Augen des Herrn durchstreifen die ganze Erde, um sich mächtig zu erweisen an denen, deren Herz ungeteilt auf ihn gerichtet ist.', '2. Chronik 16,9', ARRAY['2. Chronik 16,9']::text[]),
  (648, 'Die Werke seiner Hände sind Wahrheit und Recht; alle seine Verordnungen sind unwandelbar.', 'Psalm 111,7', ARRAY['Psalm 111,7']::text[]),
  (649, 'Und rufe mich an am Tag der Not, so will ich dich erretten, und du sollst mich ehren!', 'Psalm 50,15', ARRAY['Psalm 50,15']::text[]),
  (650, 'Frieden hinterlasse ich euch; meinen Frieden gebe ich euch. Nicht wie die Welt gibt, gebe ich euch; euer Herz erschrecke nicht und verzage nicht!', 'Johannes 14,27', ARRAY['Johannes 14,27']::text[]),
  (651, 'So fürchtet nun den HERRN und dient ihm in Wahrheit, mit eurem ganzen Herzen; denn seht, wie mächtig er sich an euch erwiesen hat!', '1. Samuel 12,24', ARRAY['1. Samuel 12,24']::text[]),
  (652, 'Um Mitternacht aber beteten Paulus und Silas und lobten Gott mit Gesang, und die Gefangenen hörten ihnen zu.', 'Apostelgeschichte 16,25', ARRAY['Apostelgeschichte 16,25']::text[]),
  (653, 'Ein verkehrtes Herz soll von mir weichen; von Bösem will ich nichts wissen!', 'Psalm 101,4', ARRAY['Psalm 101,4']::text[]),
  (654, 'Denn weil die Welt durch ihre Weisheit Gott in seiner Weisheit nicht erkannte, gefiel es Gott, durch die Torheit der Verkündigung diejenigen zu retten, die glauben.', '1. Korinther 1,21', ARRAY['1. Korinther 1,21']::text[]),
  (655, 'Lasst uns die Summe aller Lehre hören: Fürchte Gott und halte seine Gebote; denn das macht den ganzen Menschen aus.', 'Prediger 12,13', ARRAY['Prediger 12,13']::text[]),
  (656, 'Diese Hoffnung halten wir fest als einen sicheren und festen Anker der Seele, der auch hineinreicht ins Innere, hinter den Vorhang, wohin Jesus als Vorläufer für uns eingegangen ist, der Hoherpriester in Ewigkeit geworden ist nach der Weise Melchisedeks.', 'Hebräer 6,19-20', ARRAY['Hebräer 6,19-20']::text[]),
  (657, 'Aber ich vertraue auf dich, o Herr; ich sage: Du bist mein Gott! In deiner Hand steht meine Zeit; rette mich aus der Hand meiner Feinde und von meinen Verfolgern!', 'Psalm 31,15-16', ARRAY['Psalm 31,15-16']::text[]),
  (658, 'Wer die Unterweisung verwirft, verachtet seine Seele, wer aber auf Zurechtweisung hört, erwirbt Verstand.', 'Sprüche 15,32', ARRAY['Sprüche 15,32', 'Sprüche 15:32']::text[]),
  (659, 'Er sprach zu ihnen: Mose hat euch wegen der Härtigkeit eures Herzens erlaubt, eure Frauen zu entlassen; von Anfang an aber ist es nicht so gewesen.', 'Matthäus 19,8', ARRAY['Matthäus 19,8']::text[]),
  (660, 'So sei denn der Schrecken des Herrn über euch; nehmt euch in acht, was ihr tut! Denn bei dem Herrn, unserem Gott, gibt es weder Unrecht noch Ansehen der Person noch Bestechlichkeit.', '2. Chronik 19,7', ARRAY['2. Chronik 19,7']::text[]),
  (661, 'Nur auf Gott wartet still meine Seele; von ihm kommt meine Rettung. Nur er ist mein Fels und mein Heil, meine sichere Burg; ich werde nicht allzusehr wanken.', 'Psalm 62,2-3', ARRAY['Psalm 62,2-3']::text[]),
  (662, 'Aber der feste Grund Gottes bleibt bestehen und trägt dieses Siegel: Der Herr kennt die Seinen! und: Jeder, der den Namen des Christus nennt, wende sich ab von der Ungerechtigkeit!', '2. Timotheus 2,19', ARRAY['2. Timotheus 2,19']::text[]),
  (663, 'Ich ermahne euch aber, ihr Brüder, kraft des Namens unseres Herrn Jesus Christus, dass ihr alle einmütig seid in eurem Reden und keine Spaltungen unter euch zulasst, sondern vollkommen zusammengefügt seid in derselben Gesinnung und in derselben Überzeugung.', '1. Korinther 1,10', ARRAY['1. Korinther 1,10']::text[]),
  (664, 'Dann werdet ihr euch jubelnd freuen, die ihr jetzt eine kurze Zeit, wenn es sein muss, traurig seid in mancherlei Anfechtungen, damit die Bewährung eures Glaubens (der viel kostbarer ist als das vergängliche Gold, das doch durchs Feuer erprobt wird) Lob, Ehre und Herrlichkeit zur Folge habe bei der Offenbarung Jesu Christi.', '1. Petrus 1,6-7', ARRAY['1. Petrus 1,6-7']::text[]),
  (665, 'Eine übersättigte Seele tritt Honigseim mit Füßen, einer hungrigen Seele aber ist alles Bittere süß.', 'Sprüche 27,7', ARRAY['Sprüche 27,7']::text[]),
  (666, 'Und alles, was ihr tut, das tut von Herzen, als für den Herrn und nicht für Menschen, 24 da ihr wisst, dass ihr von dem Herrn zum Lohn das Erbe empfangen werdet; denn ihr dient Christus, dem Herrn!', 'Kolosser 3,23-24', ARRAY['Kollosser 3, 23-24', 'Kolosser 3,23-24', 'Kolosserbrief 3:23-24']::text[]),
  (667, 'Wer ist so weise, dass er das einsehe, und so klug, dass er das verstehe? Denn die Wege des Herrn sind richtig, und die Gerechten wandeln darauf; aber die Übertreter kommen auf ihnen zu Fall.', 'Hosea 14,10', ARRAY['Hosea 14,10']::text[]),
  (668, 'Wirf dein Anliegen auf den Herrn, und er wird für dich sorgen; er wird den Gerechten in Ewigkeit nicht wanken lassen!', 'Psalm 55,23', ARRAY['Psalm 55, 23', 'Psalmen 55:23']::text[]),
  (669, 'Darum sollst du zu ihnen sagen: So spricht der Herr der Heerscharen: Kehrt um zu mir, spricht der Herr der Heerscharen, so will ich mich zu euch kehren! spricht der Herr der Heerscharen.', 'Sacharja 1,3', ARRAY['Sacharja 1, 3']::text[]),
  (670, 'Dann zwingt er die Hand jedes Menschen zur Untätigkeit, damit alle Leute sein Werk erkennen möchten.', 'Hiob 37,7', ARRAY['Hiob 37,7']::text[]),
  (671, 'Seid niemand etwas schuldig, außer dass ihr einander liebt; denn wer den anderen liebt, hat das Gesetz erfüllt.', 'Römer 13,8', ARRAY['Römer 13,8']::text[]),
  (672, 'Ebenso ihr Jüngeren, ordnet euch den Ältesten unter; ihr alle sollt euch gegenseitig unterordnen und mit Demut bekleiden! Denn Gott widersteht den Hochmütigen; den Demütigen aber gibt er Gnade.', '1. Petrus 5,5', ARRAY['1.Petrus 5,5']::text[]),
  (673, 'Darum, wenn eine Speise meinem Bruder ein Anstoß wird, so will ich lieber in Ewigkeit kein Fleisch essen, damit ich meinem Bruder keinen Anstoß gebe.', '1. Korinther 8,13', ARRAY['1.Korinter 8,13', '1.Korinther 8,13']::text[]),
  (674, 'Neige mein Herz zu deinen Zeugnissen und nicht zur Habgier!', 'Psalm 119,36', ARRAY['Psalm 119,36']::text[]),
  (675, 'Der Geist des Herrn, des Herrschers, ist auf mir, weil der Herr mich gesalbt hat, den Armen frohe Botschaft zu verkünden; er hat mich gesandt, zu verbinden, die zerbrochenen Herzens sind, den Gefangenen Befreiung zu verkünden und Öffnung des Kerkers den Gebundenen.', 'Jesaja 61,1', ARRAY['Jesaja 61,1']::text[]),
  (676, 'Ohne Glauben aber ist es unmöglich, ihm wohlzugefallen; denn wer zu Gott kommt, muss glauben, dass er ist und dass er die belohnen wird, welche ihn suchen.', 'Hebräer 11,6', ARRAY['Hebräer 11,6', 'Hebräerbrief 11,6', 'Hebräerbrief 11:6']::text[]),
  (677, 'Gesegnet ist der Mann, der auf den Herrn vertraut und dessen Zuversicht der Herr geworden ist!', 'Jeremia 17,7', ARRAY['Jeremia 17,7']::text[]),
  (678, 'Warum fasten wir, und du siehst es nicht, warum kasteien wir unsere Seelen, und du beachtest es nicht? Seht, an eurem Fastentag geht ihr euren Geschäften nach und treibt alle eure Arbeiter an!', 'Jesaja 58,3', ARRAY['Jesaja 58,3']::text[]),
  (679, 'Ein Wallfahrtslied. Ich hebe meine Augen auf zu den Bergen: Woher kommt mir Hilfe?', 'Psalm 121,1', ARRAY['Psalm 121,1-2', 'Psalm 121:1-2', 'Psalmen 121:1']::text[]),
  (680, 'Denn das Brot Gottes ist derjenige, der aus dem Himmel herabkommt und der Welt Leben gibt.', 'Johannes 6,33', ARRAY['Johannes 6,33']::text[]),
  (681, 'Senke meine Tritte ein in deine Fußstapfen, damit mein Gang nicht wankend sei.', 'Psalm 17,5', ARRAY['Psalm 17,5']::text[]),
  (682, 'Ja, ich will meinen Geist in euer Inneres legen und werde bewirken, dass ihr in meinen Satzungen wandelt und meine Rechtsbestimmungen befolgt und tut.', 'Hesekiel 36,27', ARRAY['Hesekiel 36,27']::text[]),
  (683, 'Ob ihr nun eßt oder trinkt oder sonst etwas tut – tut alles zur Ehre Gottes!', '1. Korinther 10,31', ARRAY['1.Korinther 10,31']::text[]),
  (684, 'Samuel aber sprach zu Saul: Hat der Herr dasselbe Wohlgefallen an Schlachtopfern und Brandopfern wie daran, dass man der Stimme des Herrn gehorcht? Siehe, Gehorsam ist besser als Schlachtopfer und Folgsamkeit besser als das Fett von Widdern!', '1. Samuel 15,22', ARRAY['1.Samuel 15,22']::text[]),
  (685, 'Den Reichen in der jetzigen Weltzeit gebiete, nicht hochmütig zu sein, auch nicht ihre Hoffnung auf die Unbeständigkeit des Reichtums zu setzen, sondern auf den lebendigen Gott, der uns alles reichlich zum Genuss darreicht.', '1. Timotheus 6,17', ARRAY['1. Timotheus 6,17']::text[]),
  (686, 'Wehe der Welt wegen der Anstöße! Denn es ist zwar notwendig, dass die Anstöße zur Sünde kommen, aber wehe jenem Menschen, durch den der Anstoß zur Sünde kommt!', 'Matthäus 18,7', ARRAY['Matthäus 18,7']::text[]),
  (687, 'Es sei aber auch ferne von mir, mich an dem Herrn zu versündigen, dass ich aufhören sollte, für euch zu beten und euch den guten und richtigen Weg zu lehren!', '1. Samuel 12,23', ARRAY['1.Samuel 12,23']::text[]),
  (688, 'Hi, hier der Vers:„Was betrübst du dich, meine Seele, und bist so unruhig in mir? Harre auf Gott, denn ich werde ihm noch danken, dass er meine Rettung und mein Gott ist!“', 'Psalm 43,5', ARRAY['Psalm 43,5']::text[]),
  (689, 'Ich bin das lebendige Brot, das aus dem Himmel herabgekommen ist. Wenn jemand von diesem Brot isst, so wird er leben in Ewigkeit. Das Brot aber, das ich geben werde, ist mein Fleisch, das ich geben werde für das Leben der Welt.', 'Johannes 6,51', ARRAY['Johannes 6,51']::text[]),
  (690, 'Damit ihr an die Worte gedenkt, die von den heiligen Propheten vorausgesagt worden sind, und dessen, was euch der Herr und Retter durch uns, die Apostel, aufgetragen hat.', '2. Petrus 3,2', ARRAY['2. Petrus 3,2']::text[]),
  (691, 'Weiche vom Bösen und tue Gutes, so wirst du ewiglich bleiben!', 'Psalm 37,27', ARRAY['Psalm 37,27']::text[]),
  (692, 'Der Herr zögert nicht die Verheißung hinaus, wie etliche es für ein Hinauszögern halten, sondern er ist langmütig gegen uns, weil er nicht will, dass jemand verlorengehe, sondern dass jedermann Raum zur Buße habe.', '2. Petrus 3,9', ARRAY['2. Petrus 3,9']::text[]),
  (693, 'So steht denn nun fest, ihr Brüder, und haltet fest an den Überlieferungen, die ihr gelehrt worden seid, sei es durch ein Wort oder durch einen Brief von uns.', '2. Thessalonicher 2,15', ARRAY['2. Thessalonicherbrief 2,15']::text[]),
  (694, 'Glückselig ist, der die Worte der Weissagung liest, und die sie hören und bewahren, was darin geschrieben steht! Denn die Zeit ist nahe.', 'Offenbarung 1,3', ARRAY['Offenbarung 1,3']::text[]),
  (695, 'Ich bin mit Christus gekreuzigt; und nun lebe ich, aber nicht mehr ich selbst, sondern Christus lebt in mir. Was ich aber jetzt im Fleisch lebe, das lebe ich im Glauben an den Sohn Gottes, der mich geliebt und sich selbst für mich hingegeben hat.', 'Galater 2,20', ARRAY['Galater 2,20']::text[]),
  (696, 'Sondern heiligt vielmehr Gott, den Herrn, in euren Herzen! Seid aber allezeit bereit zur Verantwortung gegenüber jedermann, der Rechenschaft fordert über die Hoffnung, die in euch ist, und zwar mit Sanftmut und Ehrerbietung;', '1. Petrus 3,15', ARRAY['1.Petrus 3,15']::text[]),
  (697, 'Und er sprach zu ihnen: Ihr seid es, die sich selbst rechtfertigen vor den Menschen, aber Gott kennt eure Herzen; denn was bei den Menschen hoch angesehen ist, das ist ein Gräuel vor Gott.', 'Lukas 16,15', ARRAY['Lukas 16,15']::text[]),
  (698, 'Ich bin als ein Licht in die Welt gekommen, damit jeder, der an mich glaubt, nicht in der Finsternis bleibt.', 'Johannes 12,46', ARRAY['Johannes 12,46']::text[]),
  (699, 'Wenn auch ein Sünder hundertmal Böses tut und lange lebt, so weiß ich doch, dass es denen gut gehen wird, die Gott fürchten, die sich scheuen vor seinem Angesicht.', 'Prediger 8,12', ARRAY['Prediger 8,12']::text[]),
  (700, 'Ich bin gesucht worden von denen, die nicht nach mir fragten; ich bin gefunden worden von denen, die mich nicht suchten; ich habe gesagt: »Hier bin ich; hier bin ich!«, zu einem Volk, über dem mein Name nicht ausgerufen war.', 'Jesaja 65,1', ARRAY['Jesaja 65,1']::text[]),
  (701, 'Er, der sogar seinen eigenen Sohn nicht verschont hat, sondern ihn für uns alle dahingegeben hat, wie sollte er uns mit ihm nicht auch alles schenken?', 'Römer 8,32', ARRAY['Römerbrief 8,32']::text[]),
  (702, 'Vertraut auf den Herrn allezeit, denn Jah, der Herr, ist ein Fels der Ewigkeiten!', 'Jesaja 26,4', ARRAY['Jesaja 26,4']::text[]),
  (703, 'Ich weiß, Herr, dass der Weg des Menschen nicht in seiner Macht steht, dass der Mann, wenn er geht, seine Schritte nicht lenken kann.', 'Jeremia 10,23', ARRAY['Jeremia 10,23']::text[]),
  (704, 'Schmeckt und seht, wie freundlich der Herr ist; wohl dem, der auf ihn traut!', 'Psalm 34,9', ARRAY['Psalm 34,9']::text[]),
  (705, 'Meine Seele dürstet nach Gott, nach dem lebendigen Gott: Wann werde ich kommen und vor Gottes Angesicht erscheinen?', 'Psalm 42,3', ARRAY['Psalmen 42,3']::text[]),
  (706, 'Damit euer Glaube nicht auf Menschenweisheit beruhe, sondern auf Gottes Kraft.', '1. Korinther 2,5', ARRAY['1.Korinther 2, 5']::text[]),
  (707, 'Von David. Lobe den Herrn, meine Seele, und alles, was in mir ist, seinen heiligen Namen!', 'Psalm 103,1', ARRAY['Psalm 103,1']::text[]),
  (708, 'Denn das Wort des Herrn ist wahrhaftig, und all sein Tun ist Treue.', 'Psalm 33,4', ARRAY['Psalm 33,4']::text[]),
  (709, 'Denn Ungehorsam ist wie die Sünde der Wahrsagerei, und Widerspenstigkeit ist wie Abgötterei und Götzendienst. Weil du nun das Wort des Herrn verworfen hast, so hat er dich verworfen, dass du nicht mehr König sein sollst!', '1. Samuel 15,23', ARRAY['1. Samuel 15,23']::text[]),
  (710, 'Du nahtest dich mir an dem Tag, als ich dich anrief; du sprachst: »Fürchte dich nicht!«', 'Klagelieder 3,57', ARRAY['Klagelieder 3,57']::text[]),
  (711, 'Sie sollen nicht zuschanden werden zur bösen Zeit, sondern genug haben auch in den Tagen der Hungersnot.', 'Psalm 37,19', ARRAY['Psalm 37, 19', 'Psalm 37,19']::text[]),
  (712, 'Gut ist’s, schweigend zu warten auf die Rettung des Herrn. zu warten auf die Rettung des Herrn.', 'Klagelieder 3,26', ARRAY['Klagelieder 3,26']::text[]),
  (713, 'Als ich den Herrn suchte, antwortete er mir und rettete mich aus allen meinen Ängsten.', 'Psalm 34,5', ARRAY['Psalm 34,5']::text[]),
  (714, 'Ich will segnen, die dich segnen, und verfluchen, die dich verfluchen; und in dir sollen gesegnet werden alle Geschlechter auf der Erde!', '1. Mose 12,3', ARRAY['1. Mose 12,3']::text[]),
  (715, 'Es ist aber der Glaube eine feste Zuversicht auf das, was man hofft, eine Überzeugung von Tatsachen, die man nicht sieht.', 'Hebräer 11,1', ARRAY['Hebräer 11,1', 'Hebräerbrief 11:1']::text[]),
  (716, 'Wenn solche durch das Tal der Tränen gehen, machen sie es zu lauter Quellen, und der Frühregen bedeckt es mit Segen.', 'Psalm 84,7', ARRAY['Psalmen 84,7']::text[]),
  (717, 'Erwirb Weisheit, erwirb Verständnis; vergiss sie nicht und weiche nicht ab von den Reden meines Mundes!', 'Sprüche 4,5', ARRAY['Sprüche 4,5', 'Sprüche 4:5']::text[]),
  (718, 'So spricht der Herr: Verflucht ist der Mann, der auf Menschen vertraut und Fleisch zu seinem Arm macht, und dessen Herz vom Herrn weicht!', 'Jeremia 17,5', ARRAY['Jeremia 17,5']::text[]),
  (719, 'Entferne den Unmut aus deinem Herzen und halte das Übel von deinem Leib fern, denn Jugend und dunkles Haar sind nichtig!', 'Prediger 11,10', ARRAY['Prediger 11,10']::text[]),
  (720, 'O Gott, du kennst meine Torheit, und meine Verschuldungen sind dir nicht verborgen.', 'Psalm 69,6', ARRAY['Psalm 69,6']::text[]),
  (721, 'Groß ist der Herr und hoch zu loben, ja, seine Größe ist unerforschlich.', 'Psalm 145,3', ARRAY['Psalm 145,3']::text[]),
  (722, 'Eure Sanftmut lasst alle Menschen erfahren! Der Herr ist nahe!', 'Philipper 4,5', ARRAY['Philipper 4,5']::text[]),
  (723, 'So ist auch die Zunge ein kleines Glied und rühmt sich doch großer Dinge. Siehe, ein kleines Feuer — welch großen Wald zündet es an!', 'Jakobus 3,5', ARRAY['Jakobus 3,5']::text[]),
  (724, 'Diese Zeichen aber werden die begleiten, die gläubig geworden sind: In meinem Namen werden sie Dämonen austreiben, sie werden in neuen Sprachen reden, Schlangen werden sie aufheben, und wenn sie etwas Tödliches trinken, wird es ihnen nichts schaden; Kranken werden sie die Hände auflegen, und sie werden sich wohl befinden.', 'Markus 16,17-18', ARRAY['Markus 16,17-18']::text[]),
  (725, 'So demütigt euch nun unter die gewaltige Hand Gottes, damit er euch erhöhe zu seiner Zeit!', '1. Petrus 5,6', ARRAY['1. Petrus 5,6']::text[]),
  (726, 'Nachdem seine Seele Mühsal erlitten hat, wird er seine Lust sehen und die Fülle haben; durch seine Erkenntnis wird mein Knecht, der Gerechte, viele gerecht machen, und ihre Sünden wird er tragen.', 'Jesaja 53,11', ARRAY['Jesaja 53,11']::text[]),
  (727, 'Die aber Ihn lieben, sollen sein wie die Sonne, wenn sie aufgeht in ihrer Macht! Und das Land hatte Ruhe, 40 Jahre lang.', 'Richter 5,31', ARRAY['Richter 5,31b']::text[]),
  (728, 'Es sollen fröhlich sein und sich an dir freuen alle, die dich suchen; und die dein Heil lieben, sollen allezeit sagen: Gott ist groß!', 'Psalm 70,5', ARRAY['Psalm 70,5']::text[]),
  (729, 'Wer Liebe sucht, deckt die Verfehlung zu, wer aber eine Sache weitererzählt, trennt vertraute Freunde.', 'Sprüche 17,9', ARRAY['Sprüche 17,9']::text[]),
  (730, 'Erweise deine Gnade auch weiterhin denen, die dich kennen, und deine Gerechtigkeit denen, die aufrichtigen Herzens sind!', 'Psalm 36,11', ARRAY['Psalm 36,11']::text[]),
  (731, 'Wohl dem, der nicht wandelt nach dem Rat der Gottlosen, noch tritt auf den Weg der Sünder, noch sitzt, wo die Spötter sitzen, sondern seine Lust hat am Gesetz des Herrn und über sein Gesetz nachsinnt Tag und Nacht.', 'Psalm 1,1-2', ARRAY['Psalm 1,1-2']::text[]),
  (732, 'Halte im Gedächtnis Jesus Christus, aus dem Samen Davids, der aus den Toten auferstanden ist nach meinem Evangelium.', '2. Timotheus 2,8', ARRAY['2. Timotheus 2,8']::text[]),
  (733, 'Denn Gott hat uns nicht einen Geist der Furchtsamkeit gegeben, sondern der Kraft und der Liebe und der Zucht.', '2. Timotheus 1,7', ARRAY['2. Timotheus 1,7']::text[]),
  (734, 'Sondern ihr werdet Kraft empfangen, wenn der Heilige Geist auf euch gekommen ist, und ihr werdet meine Zeugen sein in Jerusalem und in ganz Judäa und Samaria und bis an das Ende der Erde!', 'Apostelgeschichte 1,8', ARRAY['Apostelgeschichte 1,8']::text[]),
  (735, 'Gott ist nicht ein Mensch, dass er lüge, noch ein Menschenkind, dass ihn etwas gereuen würde. Was er gesagt hat, sollte er es nicht tun? Was er geredet hat, sollte er es nicht ausführen?', '4. Mose 23,19', ARRAY['4. Mose 23,19']::text[]),
  (736, 'Und Gott wird abwischen alle Tränen von ihren Augen, und der Tod wird nicht mehr sein, weder Leid noch Geschrei noch Schmerz wird mehr sein; denn das Erste ist vergangen.', 'Offenbarung 21,4', ARRAY['Offenbarung 21,4', 'Offenbarung 21:4']::text[]),
  (737, 'Weil ich davon überzeugt bin, dass der, welcher in euch ein gutes Werk angefangen hat, es auch vollenden wird bis auf den Tag Jesu Christi.', 'Philipper 1,6', ARRAY['Philipper 1,6']::text[]),
  (738, 'Jesus aber sah sie an und sprach zu ihnen: Bei den Menschen ist dies unmöglich; aber bei Gott sind alle Dinge möglich.', 'Matthäus 19,26', ARRAY['Matthäus 19,26']::text[]),
  (739, 'Denn wer sein Leben retten will, der wird es verlieren; wer aber sein Leben verliert um meinetwillen und um des Evangeliums willen, der wird es retten.', 'Markus 8,35', ARRAY['Markus 8,35']::text[]),
  (740, 'Allen aber, die ihn aufnahmen, denen gab er das Anrecht, Kinder Gottes zu werden, denen, die an seinen Namen glauben;', 'Johannes 1,12', ARRAY['Johannes 1,12', 'Johannes 1:12']::text[]),
  (741, 'Von allen Seiten umgibst du mich und hältst deine Hand über mir.', 'Psalm 139,5', ARRAY['Psalmen 139,5']::text[]),
  (742, 'Erinnere sie, dass sie sich den Regierenden und Obrigkeiten unterordnen und gehorsam sind, zu jedem guten Werk bereit', 'Titus 3,1', ARRAY['Titus 3,1']::text[]),
  (743, 'Nähme ich Flügel der Morgenröte und ließe mich nieder am äußersten Ende des Meeres, so würde auch dort deine Hand mich führen und deine Rechte mich halten!', 'Psalm 139,9-10', ARRAY['Psalm 139,9-10']::text[]),
  (744, 'Der HERR erhält alle, die da fallen, und richtet auf alle, die niedergeschlagen sind. Aller Augen warten auf dich, und du gibst ihnen ihre Speise zur rechten Zeit.', 'Psalm 145,14-15', ARRAY['Psalm 145,14-15']::text[]),
  (745, 'Er sprach aber zu den Jüngern: Es ist unvermeidlich, dass Anstöße zur Sünde kommen; wehe aber dem, durch welchen sie kommen!', 'Lukas 17,1', ARRAY['Lukas 17,1']::text[]),
  (746, 'Sagt den Gerechten, dass es ihnen gut gehen wird; denn sie werden die Frucht ihrer Taten genießen.', 'Jesaja 3,10', ARRAY['Jesaja 3,10']::text[]),
  (747, 'Niemand verachte dich wegen deiner Jugend, sondern sei den Gläubigen ein Vorbild im Wort, im Wandel, in der Liebe, im Geist, im Glauben, in der Keuschheit!', '1. Timotheus 4,12', ARRAY['1. Timotheus 4,12']::text[]),
  (748, 'Der Gottlose verlasse seinen Weg und der Übeltäter seine Gedanken; und er kehre um zu dem Herrn, so wird er sich über ihn erbarmen, und zu unserem Gott, denn bei ihm ist viel Vergebung.', 'Jesaja 55,7', ARRAY['Jesaja 55,7']::text[]),
  (749, 'Da wir nun aus Glauben gerechtfertigt sind, so haben wir Frieden mit Gott durch unseren Herrn Jesus Christus,', 'Römer 5,1', ARRAY['Römer 5,1', 'Römerbrief 5:1']::text[]),
  (750, 'Ich danke Gott durch Jesus Christus, unseren Herrn! So diene ich selbst nun mit der Gesinnung dem Gesetz Gottes, mit dem Fleisch aber dem Gesetz der Sünde.', 'Römer 7,25', ARRAY['Römer 7,25']::text[]),
  (751, 'Denn ich bin gewiss, dass weder Tod noch Leben, weder Engel noch Fürstentümer noch Gewalten, weder Gegenwärtiges noch Zukünftiges, 39 weder Hohes noch Tiefes noch irgendein anderes Geschöpf uns zu scheiden vermag von der Liebe Gottes, die in Christus Jesus ist, unserem Herrn.', 'Römer 8,38-39', ARRAY['Römer 8, 37-39', 'Römer 8,37', 'Römer 8,38-39', 'Römerbrief 8:38-39']::text[]),
  (752, 'Wer überwindet, der wird alles erben, und ich werde sein Gott sein, und er wird mein Sohn sein.', 'Offenbarung 21,7', ARRAY['Offenbarung 21,7']::text[]),
  (753, 'Da tat Petrus den Mund auf und sprach: Nun erfahre ich in Wahrheit, dass Gott die Person nicht ansieht, sondern dass in jedem Volk derjenige ihm angenehm ist, der ihn fürchtet und Gerechtigkeit übt!', 'Apostelgeschichte 10,34-35', ARRAY['Apostelgeschichte 10,34-35']::text[]),
  (754, 'Ich hatte einen Bund geschlossen mit meinen Augen, dass ich ja nicht begehrlich auf eine Jungfrau blickte.', 'Hiob 31,1', ARRAY['Hiob 31,1', 'Hiob 31:1']::text[]),
  (755, 'So erkenne auch, dass die Weisheit gut ist für deine Seele; wenn du sie gefunden hast, so hast du eine Zukunft, und deine Hoffnung wird nicht zunichtewerden.', 'Sprüche 24,14', ARRAY['Sprüche 24,14']::text[]),
  (756, 'Gib mir wieder die Freude an deinem Heil, und stärke mich mit einem willigen Geist!', 'Psalm 51,14', ARRAY['Psalm 51,14']::text[]),
  (757, 'Wahrlich, wahrlich, ich sage euch: Wenn das Weizenkorn nicht in die Erde fällt und stirbt, so bleibt es allein; wenn es aber stirbt, so bringt es viel Frucht.', 'Johannes 12,24', ARRAY['Johannes 12,24']::text[]),
  (758, 'Die Furcht des Herrn ist der Anfang der Weisheit, und die Erkenntnis des Heiligen ist Einsicht.', 'Sprüche 9,10', ARRAY['Sprüche 9,10', 'Sprüche 9:10']::text[]),
  (759, 'Und die Welt vergeht und ihre Lust; wer aber den Willen Gottes tut, der bleibt in Ewigkeit.', '1. Johannes 2,17', ARRAY['1. Johannes 2,17']::text[]),
  (760, 'Ihn hat Gott zum Sühnopfer bestimmt, das wirksam wird durch den Glauben an sein Blut, um seine Gerechtigkeit zu erweisen, weil er die Sünden ungestraft ließ, die zuvor geschehen waren.', 'Römer 3,25', ARRAY['Römer 3,25']::text[]),
  (761, 'Denn Christus ist, als wir noch kraftlos waren, zur bestimmten Zeit für Gottlose gestorben.', 'Römer 5,6', ARRAY['Römer 5,6']::text[]),
  (762, 'Denn ich, der Herr, dein Gott, ergreife deine rechte Hand und sage dir: Fürchte dich nicht; ich helfe dir!', 'Jesaja 41,13', ARRAY['Jesaja 41,13']::text[]),
  (763, 'Denn wo Neid und Selbstsucht ist, da ist Unordnung und jede böse Tat.', 'Jakobus 3,16', ARRAY['Jakobus 3,16']::text[]),
  (764, 'Er hat nicht mit uns gehandelt nach unseren Sünden und uns nicht vergolten nach unseren Missetaten.', 'Psalm 103,10', ARRAY['Psalmen 103:10']::text[]),
  (765, 'Darum sollt ihr nicht sorgen und sagen: Was werden wir essen?, oder: Was werden wir trinken?, oder: Womit werden wir uns kleiden?', 'Matthäus 6,31', ARRAY['Matthäus 6:31']::text[]),
  (766, 'denn die Waffen unseres Kampfes sind nicht fleischlich, sondern mächtig durch Gott zur Zerstörung von Festungen,', '2. Korinther 10,4', ARRAY['2. Korinther 10:4']::text[]),
  (767, 'Du aber, wenn du betest, geh in dein Kämmerlein und schließe deine Türe zu und bete zu deinem Vater, der im Verborgenen ist; und dein Vater, der ins Verborgene sieht, wird es dir öffentlich vergelten.', 'Matthäus 6,6', ARRAY['Matthäus 6:6']::text[]),
  (768, 'Ich will achthaben auf den vollkommenen Weg. Wann wirst du zu mir kommen? Ich will mit lauterem Herzen wandeln im Innern meines Hauses.', 'Psalm 101,2', ARRAY['Psalmen 101:2']::text[]),
  (769, 'Seid aber gegeneinander freundlich und barmherzig und vergebt einander, gleichwie auch Gott euch vergeben hat in Christus.', 'Epheser 4,32', ARRAY['Epheserbrief 4:32']::text[]),
  (770, 'Darum soll der Bogen in den Wolken sein, dass ich ihn ansehe und an den ewigen Bund gedenke zwischen Gott und allen lebendigen Wesen von allem Fleisch, das auf der Erde ist!', '1. Mose 9,16', ARRAY['1. Mose 9:16']::text[]),
  (771, 'Oder verachtest du den Reichtum seiner Güte, Geduld und Langmut, und erkennst nicht, dass dich Gottes Güte zur Buße leitet?', 'Römer 2,4', ARRAY['Römerbrief 2:4']::text[]),
  (772, 'Denn die Gnade Gottes ist erschienen, die heilbringend ist für alle Menschen;', 'Titus 2,11', ARRAY['Titusbrief 2:11']::text[]),
  (773, 'Sollte ich etwa Stierfleisch essen oder Blut von Böcken trinken?', 'Psalm 50,13', ARRAY['Psalmen 50:13']::text[]),
  (774, 'Darum sage ich euch: Alles, was ihr auch immer im Gebet erbittet, glaubt, dass ihr es empfangt, so wird es euch zuteilwerden!', 'Markus 11,24', ARRAY['Markus 11:24']::text[]),
  (775, 'Groß ist unser Herr und reich an Macht; sein Verstand ist unermesslich.', 'Psalm 147,5', ARRAY['Psalmen 147:5']::text[]),
  (776, 'sondern, wahrhaftig in der Liebe, heranwachsen in allen Stücken zu ihm hin, der das Haupt ist, der Christus.', 'Epheser 4,15', ARRAY['Epheserbrief 4:15']::text[]),
  (777, 'Und er setzte sich und rief die Zwölf und sprach zu ihnen: Wenn jemand der Erste sein will, so sei er von allen der Letzte und aller Diener!', 'Markus 9,35', ARRAY['Markus 9:35']::text[]),
  (778, 'sie nimmt uns in Zucht, damit wir die Gottlosigkeit und die weltlichen Begierden verleugnen und besonnen und gerecht und gottesfürchtig leben in der jetzigen Weltzeit,', 'Titus 2,12', ARRAY['Titusbrief 2:12']::text[]),
  (779, 'Siehe, Gott ist mein Heil; ich will vertrauen und lasse mir nicht grauen; denn Jah, der Herr, ist meine Kraft und mein Lied, und er wurde mir zur Rettung!', 'Jesaja 12,2', ARRAY['Jesaja 12:2']::text[]),
  (780, 'Er wird seine Herde weiden wie ein Hirte; die Lämmer wird er in seinen Arm nehmen und im Bausch seines Gewandes tragen; die Mutterschafe wird er sorgsam führen.', 'Jesaja 40,11', ARRAY['Jesaja 40:11']::text[]),
  (781, 'Daran haben wir die Liebe erkannt, dass Er sein Leben für uns hingegeben hat; auch wir sind es schuldig, für die Brüder das Leben hinzugeben.', '1. Johannes 3,16', ARRAY['1. Johannes 3:16']::text[]),
  (782, 'Lass dieses Buch des Gesetzes nicht von deinem Mund weichen, sondern forsche darin Tag und Nacht, damit du darauf achtest, alles zu befolgen, was darin geschrieben steht; denn dann wirst du Gelingen haben auf deinen Wegen, und dann wirst du weise handeln!', 'Josua 1,8', ARRAY['Josua 1:8']::text[]),
  (783, 'er wird dich mit seinen Fittichen decken, und unter seinen Flügeln wirst du dich bergen; seine Treue ist Schirm und Schild.', 'Psalm 91,4', ARRAY['Psalmen 91:4']::text[]),
  (784, 'Wohl dem Mann, den du, Herr, züchtigst, und den du aus deinem Gesetz belehrst,', 'Psalm 94,12', ARRAY['Psalmen 94:12']::text[]),
  (785, 'Denn ich werde Wasser auf das Durstige gießen und Ströme auf das Dürre; ich werde meinen Geist auf deinen Samen ausgießen und meinen Segen auf deine Sprösslinge,', 'Jesaja 44,3', ARRAY['Jesaja 44:3']::text[]),
  (786, 'Betet ohne Unterlass!', '1. Thessalonicher 5,17', ARRAY['1. Thessalonicherbrief 5:17']::text[]),
  (787, 'Ein Wallfahrtslied. Wohl jedem, der den Herrn fürchtet, der in seinen Wegen wandelt!', 'Psalm 128,1', ARRAY['Psalmen 128:1']::text[]),
  (788, 'Wer seine Worte zurückhält, der besitzt Erkenntnis, und wer kühlen Geistes ist, der ist ein weiser Mann.', 'Sprüche 17,27', ARRAY['Sprüche 17:27']::text[]),
  (789, 'Ich werde mich in Frieden niederlegen und schlafen; denn du allein, Herr, lässt mich sicher wohnen.', 'Psalm 4,9', ARRAY['Psalmen 4:9']::text[]),
  (790, 'Doch ich sage euch: Es wird Tyrus und Zidon erträglicher gehen am Tag des Gerichts als euch!', 'Matthäus 11,22', ARRAY['Matthäus 11:22']::text[]),
  (791, 'Da wird dann einer sagen: »Du hast Glauben, und ich habe Werke. Beweise mir doch deinen Glauben aus deinen Werken, und ich werde dir aus meinen Werken meinen Glauben beweisen!«', 'Jakobus 2,18', ARRAY['Jakobus 2:18']::text[]),
  (792, 'Demnach kommt der Glaube aus der Verkündigung, die Verkündigung aber durch Gottes Wort.', 'Römer 10,17', ARRAY['Römerbrief 10:17']::text[]),
  (793, 'Du erhörst Gebet; darum kommt alles Fleisch zu dir.', 'Psalm 65,3', ARRAY['Psalmen 65:3']::text[]),
  (794, 'Ihr seid teuer erkauft; werdet nicht Knechte der Menschen!', '1. Korinther 7,23', ARRAY['1. Korinther 7:23']::text[]),
  (795, 'Freundliche Worte sind wie Honigseim, süß für die Seele und heilsam für das Gebein.', 'Sprüche 16,24', ARRAY['Sprüche 16:24']::text[]),
  (796, 'Erforsche mich, o Gott, und erkenne mein Herz; prüfe mich und erkenne, wie ich es meine; 24 und sieh, ob ich auf bösem Weg bin, und leite mich auf dem ewigen Weg!', 'Psalm 139,23-24', ARRAY['Psalmen 139:23-24']::text[]),
  (797, 'Wie es aber in den Tagen Noahs war, so wird es auch bei der Wiederkunft des Menschensohnes sein. 38 Denn wie sie in den Tagen vor der Sintflut aßen und tranken, heirateten und verheirateten bis zu dem Tag, als Noah in die Arche ging,', 'Matthäus 24,37-38', ARRAY['Matthäus 24:37-38']::text[]),
  (798, 'Wer aber ausharrt bis ans Ende, der wird gerettet werden. 14 Und dieses Evangelium vom Reich wird in der ganzen Welt verkündigt werden, zum Zeugnis für alle Heidenvölker, und dann wird das Ende kommen.', 'Matthäus 24,13-14', ARRAY['Matthäus 24:13-14']::text[]),
  (799, 'Darin ist die Liebe Gottes zu uns geoffenbart worden, dass Gott seinen eingeborenen Sohn in die Welt gesandt hat, damit wir durch ihn leben sollen.', '1. Johannes 4,9', ARRAY['1. Johannes 4:9']::text[]);
INSERT INTO _pool_seed (idx, verse, reference, raw_refs) VALUES
  (800, 'Die Stimme eines Rufenden ertönt: In der Wüste bereitet den Weg des Herrn, ebnet in der Steppe eine Straße unserem Gott!', 'Jesaja 40,3', ARRAY['Jesaja 40:3']::text[]),
  (801, 'Denn auch Christus hatte nicht an sich selbst Gefallen, sondern wie geschrieben steht: »Die Schmähungen derer, die dich schmähen, sind auf mich gefallen«.', 'Römer 15,3', ARRAY['Römerbrief 15:3']::text[]),
  (802, 'Herr, ich will dich preisen unter den Völkern und dir lobsingen unter den Nationen; 5 denn groß bis über die Himmel hinaus ist deine Gnade, und deine Treue bis zu den Wolken.', 'Psalm 108,4-5', ARRAY['Psalmen 108:4-5']::text[]),
  (803, 'Als das Jesus sah, wurde er unwillig und sprach zu ihnen: Lasst die Kinder zu mir kommen und wehrt ihnen nicht; denn solcher ist das Reich Gottes!', 'Markus 10,14', ARRAY['Markus 10:14']::text[]),
  (804, 'und werdet sagen zu jener Zeit: Dankt dem Herrn, ruft seinen Namen an, verkündigt unter den Völkern seine Taten, erinnert daran, dass sein Name hoch erhaben ist!', 'Jesaja 12,4', ARRAY['Jesaja 12:4']::text[]),
  (805, 'Lehre mich tun nach deinem Wohlgefallen, denn du bist mein Gott; dein guter Geist führe mich in ebenem Land!', 'Psalm 143,10', ARRAY['Psalmen 143:10']::text[]),
  (806, 'der sich selbst für uns hingegeben hat, um uns von aller Gesetzlosigkeit zu erlösen und für sich selbst ein Volk zum besonderen Eigentum zu reinigen, das eifrig ist, gute Werke zu tun.', 'Titus 2,14', ARRAY['Titusbrief 2:14']::text[]),
  (807, 'Ihr aber seid ein auserwähltes Geschlecht, ein königliches Priestertum, ein heiliges Volk, ein Volk des Eigentums, damit ihr die Tugenden dessen verkündet, der euch aus der Finsternis berufen hat zu seinem wunderbaren Licht', '1. Petrus 2,9', ARRAY['1. Petrus 2:9']::text[]),
  (808, 'Darum richtet nichts vor der Zeit, bis der Herr kommt, der auch das im Finstern Verborgene ans Licht bringen und die Absichten der Herzen offenbar machen wird; und dann wird jedem das Lob von Gott zuteilwerden.', '1. Korinther 4,5', ARRAY['1. Korinther 4:5']::text[]),
  (809, 'Ich freue mich sehr in dem Herrn, und meine Seele ist fröhlich in meinem Gott; denn er hat mir Kleider des Heils angezogen, mit dem Mantel der Gerechtigkeit mich bekleidet, wie ein Bräutigam sich den priesterlichen Kopfschmuck anlegt und wie eine Braut sich mit ihrem Geschmeide schmückt.', 'Jesaja 61,10', ARRAY['Jesaja 61:10']::text[]),
  (810, 'Sie nun gingen voll Freude vom Hohen Rat hinweg, weil sie gewürdigt worden waren, Schmach zu leiden um Seines Namens willen; 42 und sie hörten nicht auf, jeden Tag im Tempel und in den Häusern zu lehren und das Evangelium von Jesus, dem Christus, zu verkündigen.', 'Apostelgeschichte 5,41-42', ARRAY['Apostelgeschichte 5:41-42']::text[]),
  (811, 'Wie soll ich dem Herrn vergelten all seine Wohltaten an mir? 13 Den Kelch des Heils will ich nehmen und den Namen des Herrn anrufen;', 'Psalm 116,12-13', ARRAY['Psalmen 116:12-13']::text[]),
  (812, 'Alle Völker, die du gemacht hast, werden kommen und vor dir anbeten, o Herr, und deinem Namen Ehre geben; 10 denn du bist groß und tust Wunder, du bist Gott, du allein!', 'Psalm 86,9-10', ARRAY['Psalmen 86:9-10']::text[]),
  (813, 'Eine segnende Seele wird reichlich gesättigt, und wer anderen zu trinken gibt, wird selbst erquickt.', 'Sprüche 11,25', ARRAY['Sprüche 11:25']::text[]),
  (814, 'dagegen erneuert werdet im Geist eurer Gesinnung', 'Epheser 4,23', ARRAY['Epheserbrief 4:23']::text[]),
  (815, 'indem wir hinschauen auf Jesus, den Anfänger und Vollender des Glaubens, der um der vor ihm liegenden Freude willen das Kreuz erduldete und dabei die Schande für nichts achtete, und der sich zur Rechten des Thrones Gottes gesetzt hat.', 'Hebräer 12,2', ARRAY['Hebräerbrief 12:2']::text[]),
  (816, 'Und der Engel antwortete und sprach zu ihr: Der Heilige Geist wird über dich kommen, und die Kraft des Höchsten wird dich überschatten. Darum wird auch das Heilige, das geboren wird, Gottes Sohn genannt werden.', 'Lukas 1,35', ARRAY['Lukas 1:35']::text[]),
  (817, 'Und o selig bist du, die du geglaubt hast! denn es wird vollendet werden, was dir gesagt ist von dem HERRN.', 'Lukas 1,45', ARRAY['Lukas 1:45']::text[]),
  (818, 'Und Maria sprach: Meine Seele erhebt den HERRN,', 'Lukas 1,46', ARRAY['Lukas 1:46']::text[]),
  (819, 'Siehe, du wirst schwanger werden und einen Sohn gebären, des Namen sollst du Jesus heißen. 32 Der wird groß sein und ein Sohn des Höchsten genannt werden; und Gott der HERR wird ihm den Stuhl seines Vaters David geben; 33 und er wird ein König sein über das Haus Jakob ewiglich, und seines Königreiches wird kein Ende sein.', 'Lukas 1,31-33', ARRAY['Lukas 1:31-33']::text[]),
  (820, 'Die Liebe ist langmütig und freundlich, die Liebe eifert nicht, die Liebe treibt nicht Mutwillen, sie blähet sich nicht,', '1. Korinther 13,4', ARRAY['1. Korinther 13:4']::text[]);
